export const BUNDLED_WORKFLOWS: Record<string, string> = {
  "archon-adversarial-dev": "name: archon-adversarial-dev\ndescription: |\n  Use when: User wants to build a complete application from scratch using adversarial development.\n  Triggers: \"adversarial dev\", \"adversarial development\", \"build with adversarial\", \"gan dev\",\n            \"adversarial build\", \"build app adversarially\", \"adversarial coding\".\n  Does: Three-role GAN-inspired development — Planner creates spec with sprints, then a state-machine\n        loop alternates between Generator (builds code) and Evaluator (attacks it) with hard pass/fail\n        thresholds. The evaluator's job is to BREAK what the generator builds. If any criterion scores\n        below 7/10, the sprint goes back to the generator with adversarial feedback. Stops on sprint\n        failure after max retries.\n  NOT for: Bug fixes, PR reviews, refactoring existing code, simple one-off tasks.\n\n  Based on Anthropic's harness design article for long-running application development.\n  Separates planning, building, and evaluation into distinct roles with adversarial tension.\nprovider: claude\nmodel: medium\n\nnodes:\n  # ─── Phase 1: Planning ───────────────────────────────────────────────\n  - id: plan\n    prompt: |\n      You are a product planning expert. Your job is to take a short user prompt and expand it\n      into a comprehensive product specification.\n\n      ## User Request\n\n      $ARGUMENTS\n\n      ## Your Task\n\n      Write a comprehensive product specification to the file `$ARTIFACTS_DIR/spec.md` using the Write tool.\n\n      The spec MUST include ALL of the following sections:\n\n      ### 1. Product Overview\n      What the product does, who it's for, core value proposition.\n\n      ### 2. Tech Stack\n      Specific technologies, frameworks, and libraries. Be opinionated — pick concrete choices,\n      not \"a modern framework.\" Include exact package names and versions where relevant.\n\n      ### 3. Design Language\n      Visual style, specific color hex codes, typography choices, component patterns, spacing system.\n\n      ### 4. Feature List\n      Every feature organized by priority. Be exhaustive.\n\n      ### 5. Sprint Plan\n      Features broken into 3-6 sprints, ordered by dependency and importance:\n      - **Sprint 1** should establish the foundation (project setup, core data models, basic UI shell)\n      - Each subsequent sprint builds on the previous\n      - Label each sprint clearly: \"Sprint 1: Foundation\", \"Sprint 2: Core Features\", etc.\n      - List the specific features/deliverables for each sprint\n\n      Be specific and opinionated. The more concrete the spec (exact API paths, specific color codes,\n      named libraries), the better the generator can build and the evaluator can test.\n\n      IMPORTANT: Write the spec to `$ARTIFACTS_DIR/spec.md` using the Write tool. Do NOT just output\n      it as conversation text.\n    allowed_tools: [Read, Write, Glob, Grep]\n\n  # ─── Phase 2: Workspace Initialization ───────────────────────────────\n  - id: init-workspace\n    depends_on: [plan]\n    bash: |\n      ARTIFACTS=\"$ARTIFACTS_DIR\"\n\n      # Create directory structure for harness communication\n      mkdir -p \"$ARTIFACTS/contracts\"\n      mkdir -p \"$ARTIFACTS/feedback\"\n      mkdir -p \"$ARTIFACTS/app\"\n\n      # Initialize isolated git repo in app directory\n      cd \"$ARTIFACTS/app\"\n      git init -q\n      git commit --allow-empty -m \"Initial commit: adversarial-dev workspace\" -q\n\n      # Extract sprint count from spec (find highest \"Sprint N\" reference)\n      SPEC=\"$ARTIFACTS/spec.md\"\n      SPRINT_COUNT=3\n      if [ -f \"$SPEC\" ]; then\n        FOUND=$(grep -ioE 'sprint\\s+[0-9]+' \"$SPEC\" | grep -oE '[0-9]+' | sort -n | tail -1)\n        if [ -n \"$FOUND\" ] && [ \"$FOUND\" -ge 1 ] 2>/dev/null; then\n          SPRINT_COUNT=$FOUND\n        fi\n        if [ \"$SPRINT_COUNT\" -gt 10 ]; then\n          SPRINT_COUNT=10\n        fi\n      fi\n\n      # Write initial state machine file\n      cat > \"$ARTIFACTS/state.json\" << 'STATEEOF'\n      {\n        \"phase\": \"negotiating\",\n        \"sprint\": 1,\n        \"totalSprints\": SPRINT_COUNT_PLACEHOLDER,\n        \"retry\": 0,\n        \"maxRetries\": 3,\n        \"passThreshold\": 7,\n        \"completedSprints\": [],\n        \"status\": \"running\"\n      }\n      STATEEOF\n      STATE_TMP=\"$ARTIFACTS/state.json.tmp\"\n      sed \"s/SPRINT_COUNT_PLACEHOLDER/$SPRINT_COUNT/\" \"$ARTIFACTS/state.json\" > \"$STATE_TMP\"\n      mv \"$STATE_TMP\" \"$ARTIFACTS/state.json\"\n\n      echo \"{\\\"totalSprints\\\": $SPRINT_COUNT, \\\"appDir\\\": \\\"$ARTIFACTS/app\\\", \\\"artifactsDir\\\": \\\"$ARTIFACTS\\\"}\"\n    timeout: 30000\n\n  # ─── Phase 3: Adversarial Sprint Loop ────────────────────────────────\n  #\n  # State machine driven by $ARTIFACTS_DIR/state.json\n  # Each iteration plays ONE role: negotiator, generator, or evaluator\n  # fresh_context ensures genuine separation between roles\n  #\n  - id: adversarial-sprint\n    depends_on: [init-workspace]\n    idle_timeout: 600000\n    model: large\n    loop:\n      prompt: |\n        # Adversarial Development — Sprint Loop\n\n        You are part of a GAN-inspired adversarial development system with three distinct roles.\n        Each iteration you play ONE role, determined by the current phase in the state file.\n\n        ## FIRST: Read State\n\n        Read `$ARTIFACTS_DIR/state.json` to determine:\n        - `phase` — which role you play this iteration\n        - `sprint` — current sprint number\n        - `totalSprints` — how many sprints total\n        - `retry` — current retry attempt (0 = first try)\n        - `maxRetries` — max retries before hard failure (default 3)\n        - `passThreshold` — minimum score to pass (default 7)\n\n        Then read `$ARTIFACTS_DIR/spec.md` for product context.\n\n        ## Directory Layout\n\n        - App source code: `$ARTIFACTS_DIR/app/`\n        - Sprint contracts: `$ARTIFACTS_DIR/contracts/sprint-{N}.json`\n        - Evaluation feedback: `$ARTIFACTS_DIR/feedback/sprint-{N}-round-{R}.json`\n        - State machine: `$ARTIFACTS_DIR/state.json`\n\n        ---\n\n        ## ROLE: CONTRACT NEGOTIATOR (phase = \"negotiating\")\n\n        You negotiate the success criteria for the current sprint. Play BOTH sides sequentially:\n\n        **Step 1 — Generator's Proposal:**\n        Read the spec carefully. Identify what Sprint {N} should deliver based on the sprint plan.\n        Propose a sprint contract with 5-15 specific, testable criteria.\n\n        Each criterion MUST be concrete and verifiable. Examples:\n        - GOOD: \"GET /api/tasks returns 200 with JSON array; each item has id (number), title (string), status (string), createdAt (ISO date)\"\n        - GOOD: \"Clicking the Add Task button opens a modal with title input, priority dropdown (low/medium/high), and due date picker\"\n        - BAD: \"The API works well\"\n        - BAD: \"Tasks can be managed\"\n\n        **Step 2 — Evaluator's Tightening:**\n        Now review your proposal as an adversary. For EACH criterion ask:\n        - Is it specific enough to test programmatically?\n        - What edge cases are missing? (empty inputs, special characters, concurrent requests)\n        - Is the bar high enough, or would sloppy code pass?\n\n        Tighten vague criteria. Add edge cases. Raise the bar.\n\n        **Write the final contract** to `$ARTIFACTS_DIR/contracts/sprint-{N}.json`:\n        ```json\n        {\n          \"sprintNumber\": <N>,\n          \"features\": [\"feature1\", \"feature2\", ...],\n          \"criteria\": [\n            {\n              \"name\": \"short-kebab-name\",\n              \"description\": \"Specific, testable description of what must be true\",\n              \"threshold\": 7\n            }\n          ]\n        }\n        ```\n\n        **Update state.json**: Set `\"phase\": \"building\"`. Keep all other fields unchanged.\n\n        ---\n\n        ## ROLE: GENERATOR (phase = \"building\")\n\n        You are a software engineer. Build features that MUST survive an adversarial evaluator\n        who will actively try to break your code.\n\n        **Read these files:**\n        1. `$ARTIFACTS_DIR/spec.md` — full product spec (design language, tech stack, all features)\n        2. `$ARTIFACTS_DIR/contracts/sprint-{N}.json` — the contract you must satisfy\n        3. If `retry` > 0: read `$ARTIFACTS_DIR/feedback/sprint-{N}-round-{R-1}.json` for the\n           evaluator's previous feedback\n\n        **If this is a RETRY (retry > 0):**\n        Read the feedback CAREFULLY. Every failed criterion must be addressed.\n        - If scores were close (5-6) and trending up: REFINE your approach\n        - If scores were low (1-4) or the approach is fundamentally broken: PIVOT to a new strategy\n        - Address EVERY feedback item — the evaluator WILL check\n        - Re-verify each fix by running the code before committing\n\n        **Build rules:**\n        - All code goes in `$ARTIFACTS_DIR/app/`\n        - Build ONE feature at a time, verify it works, then commit:\n          ```bash\n          cd $ARTIFACTS_DIR/app && git add -A && git commit -m \"feat: description of what was built\"\n          ```\n        - Install dependencies as needed (npm/bun/pip/etc)\n        - Test your code — start the server, hit the endpoints, verify the UI renders\n        - Think about what the evaluator will attack: edge cases, error handling, input validation\n        - Build defensively — the evaluator's job is to break you\n\n        **Update state.json**: Set `\"phase\": \"evaluating\"`. Keep all other fields unchanged.\n\n        ---\n\n        ## ROLE: EVALUATOR (phase = \"evaluating\")\n\n        You are an ADVERSARIAL QA agent. Your mandate is to BREAK what the generator built.\n        You are not helpful. You are not generous. You are an attacker.\n\n        **CRITICAL CONSTRAINTS:**\n        - You are READ-ONLY for source code. NEVER use Write or Edit on files in `$ARTIFACTS_DIR/app/`.\n        - You MAY use Bash to run the app, curl endpoints, run test scripts, check behavior.\n        - You MUST kill any background processes (servers, watchers) you start BEFORE finishing.\n          Use: `pkill -f \"node\\|bun\\|python\\|npm\" 2>/dev/null || true`\n        - You MUST score EVERY criterion in the contract. No skipping.\n\n        **Scoring guidelines:**\n        - **9-10**: Exceptional. Works perfectly including edge cases the contract didn't mention.\n        - **7-8**: Solid. Meets the criterion as stated. Minor polish issues at most.\n        - **5-6**: Partial. Core functionality exists but fails important edge cases or has bugs.\n        - **3-4**: Weak. Barely functional. Major gaps.\n        - **1-2**: Broken. Does not work or is not implemented.\n\n        Do NOT grade on a curve. Do NOT give benefit of the doubt. A 7 means \"genuinely meets the bar.\"\n        If something is broken, say it's broken.\n\n        **Read**: `$ARTIFACTS_DIR/contracts/sprint-{N}.json` for the criteria.\n\n        **For each criterion:**\n        1. Read the relevant source code\n        2. Run the application (start server, test endpoints, check rendered UI)\n        3. Try to BREAK it — invalid inputs, missing fields, edge cases, error handling gaps\n        4. Score it honestly\n\n        **Write evaluation** to `$ARTIFACTS_DIR/feedback/sprint-{N}-round-{R}.json`:\n        ```json\n        {\n          \"passed\": <true if ALL scores >= passThreshold, false otherwise>,\n          \"scores\": {\n            \"criterion-name\": <score>,\n            ...\n          },\n          \"feedback\": [\n            {\n              \"criterion\": \"criterion-name\",\n              \"score\": <1-10>,\n              \"details\": \"Specific findings. Include file paths, line numbers, exact error messages, curl commands that failed.\"\n            }\n          ],\n          \"overallSummary\": \"What worked, what didn't, what the generator must fix.\"\n        }\n        ```\n\n        **Determine pass/fail** — `passed` is `true` ONLY if every single score >= `passThreshold`.\n\n        **Update state.json based on result:**\n\n        **If PASSED (all criteria >= threshold):**\n        - Add current sprint number to `completedSprints` array\n        - If `sprint` < `totalSprints`: set `\"phase\": \"negotiating\"`, increment `\"sprint\"` by 1, set `\"retry\": 0`\n        - If `sprint` == `totalSprints`: set `\"phase\": \"complete\"`, set `\"status\": \"complete\"`\n\n        **If FAILED:**\n        - If `retry` < `maxRetries`: set `\"phase\": \"building\"`, increment `\"retry\"` by 1\n        - If `retry` >= `maxRetries`: set `\"phase\": \"failed\"`, set `\"status\": \"failed\"`\n\n        **IMPORTANT**: Kill all background processes before finishing:\n        ```bash\n        pkill -f \"node|bun|python|npm|next|vite|webpack\" 2>/dev/null || true\n        ```\n\n        ---\n\n        ## COMPLETION\n\n        After updating state.json, check the `status` field:\n        - If `\"status\": \"complete\"` → all sprints passed! Output: `<promise>ALL_SPRINTS_COMPLETE</promise>`\n        - If `\"status\": \"failed\"` → sprint failed after max retries. Output: `<promise>ALL_SPRINTS_COMPLETE</promise>`\n        - If `\"status\": \"running\"` → more work to do. Do NOT output any completion signal.\n\n      until: ALL_SPRINTS_COMPLETE\n      max_iterations: 60\n      fresh_context: true\n      until_bash: |\n        grep -qE '\"status\"\\s*:\\s*\"(complete|failed)\"' \"$ARTIFACTS_DIR/state.json\"\n\n  # ─── Phase 4: Report ─────────────────────────────────────────────────\n  - id: report\n    depends_on: [adversarial-sprint]\n    trigger_rule: all_done\n    context: fresh\n    model: small\n    prompt: |\n      You are a project reporter. Generate a comprehensive summary of the adversarial development run.\n\n      ## Read ALL of these files:\n      1. `$ARTIFACTS_DIR/state.json` — final state (tells you success/failure, sprint count)\n      2. `$ARTIFACTS_DIR/spec.md` — the original product spec\n      3. All files in `$ARTIFACTS_DIR/contracts/` — sprint contracts (use Glob to find them)\n      4. All files in `$ARTIFACTS_DIR/feedback/` — evaluation results (use Glob to find them)\n\n      ## Generate a report covering:\n\n      ### Build Summary\n      - What application was built (from the spec)\n      - Final status: did all sprints pass or did it fail? On which sprint?\n      - Total sprints completed vs planned\n\n      ### Per-Sprint Breakdown\n      For each sprint that was attempted:\n      - What the contract required (features + key criteria)\n      - How many attempts were needed (retry count)\n      - Final scores for each criterion\n      - Key feedback that drove retries and improvements\n\n      ### Quality Metrics\n      - Average score across all final-round criteria\n      - Which criteria required the most retries\n      - Where the adversarial evaluator pushed quality the highest\n\n      ### How to Run\n      - The application code lives in: `$ARTIFACTS_DIR/app/`\n      - Include the tech stack and how to start the app (from the spec)\n      - Include any setup steps (install deps, env vars, etc.)\n\n      Write this report to `$ARTIFACTS_DIR/report.md` AND output it as your response so the user\n      sees it directly.\n    allowed_tools: [Read, Write, Glob, Grep]\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-architect": "name: archon-architect\ndescription: |\n  Use when: User wants an architectural sweep, complexity reduction, or codebase health improvement.\n  Triggers: \"architect\", \"simplify codebase\", \"reduce complexity\", \"architectural sweep\",\n            \"clean up architecture\", \"codebase health\", \"fix architecture\".\n  Does: Scans codebase metrics -> analyzes architecture with principled lens -> plans targeted\n        simplifications -> executes fixes with self-review loops (hooks) -> validates -> creates PR.\n  NOT for: Single-file fixes, feature development, bug fixes, PR reviews.\n\n  DAG workflow showcasing per-node hooks:\n  - PostToolUse hooks create organic quality loops (lint after write, self-review)\n  - PreToolUse hooks inject architectural principles before changes\n  - Different nodes have different trust levels and steering\n\nprovider: claude\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 1: MEASURE\n  # Gather raw metrics — file sizes, complexity hotspots, dependency fan-out\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: scan-metrics\n    bash: |\n      echo \"=== FILE SIZE HOTSPOTS (top 30 largest source files) ===\"\n      find . -name '*.ts' -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/dist/*' \\\n        -exec wc -l {} + 2>/dev/null | sort -rn | head -30\n\n      echo \"\"\n      echo \"=== IMPORT FAN-OUT (files with most imports) ===\"\n      for f in $(find . -name '*.ts' -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/dist/*'); do\n        count=$(grep -c \"^import \" \"$f\" 2>/dev/null) || count=0\n        if [ \"$count\" -gt 8 ]; then\n          echo \"$count imports: $f\"\n        fi\n      done | sort -rn | head -20\n\n      echo \"\"\n      echo \"=== EXPORT FAN-OUT (files with most exports) ===\"\n      for f in $(find . -name '*.ts' -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/dist/*'); do\n        count=$(grep -c \"^export \" \"$f\" 2>/dev/null) || count=0\n        if [ \"$count\" -gt 5 ]; then\n          echo \"$count exports: $f\"\n        fi\n      done | sort -rn | head -20\n\n      echo \"\"\n      echo \"=== FUNCTION LENGTH HOTSPOTS (functions over 50 lines) ===\"\n      grep -rn \"^\\(export \\)\\?\\(async \\)\\?function \\|=> {$\" \\\n        --include='*.ts' --exclude-dir=node_modules --exclude-dir=.git --exclude-dir=dist . 2>/dev/null \\\n        | head -30\n\n      echo \"\"\n      echo \"=== TYPE SAFETY GAPS ===\"\n      echo \"any usage:\"\n      grep -rn \": any\\b\\|as any\\b\" --include='*.ts' --exclude-dir=node_modules --exclude-dir=.git --exclude-dir=dist . 2>/dev/null | wc -l\n      echo \"eslint-disable comments:\"\n      grep -rn \"eslint-disable\" --include='*.ts' --exclude-dir=node_modules --exclude-dir=.git --exclude-dir=dist . 2>/dev/null | wc -l\n    timeout: 60000\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 2: ANALYZE\n  # Read through hotspots with an architectural lens\n  # Hooks inject assessment criteria after every file read\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: analyze\n    prompt: |\n      You are a senior software architect performing a codebase health assessment.\n\n      ## Codebase Metrics\n\n      $scan-metrics.output\n\n      ## User Focus\n\n      $ARGUMENTS\n\n      ## Instructions\n\n      1. Read the top 10-15 files flagged by the metrics above (largest, most imports, most exports)\n      2. For each file, assess the criteria injected after you read it (you'll see them)\n      3. Build a running list of architectural concerns\n      4. Focus on:\n         - Modules doing too many things (SRP violations)\n         - Abstractions that don't earn their complexity\n         - Duplicated patterns that should be consolidated (Rule of Three)\n         - God files or god functions\n         - Leaky abstractions or tight coupling between layers\n         - Dead code or unused exports\n      5. Do NOT suggest changes yet — only diagnose\n\n      ## Output\n\n      Write a structured assessment to $ARTIFACTS_DIR/architecture-assessment.md with:\n      - Executive summary (3-5 sentences)\n      - Top findings ranked by impact\n      - For each finding: file, what's wrong, why it matters, estimated effort\n    depends_on: [scan-metrics]\n    context: fresh\n    denied_tools: [Write, Edit, Bash]\n    hooks:\n      PostToolUse:\n        - matcher: \"Read\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PostToolUse\n              additionalContext: >\n                For the file you just read, assess:\n                (1) Single responsibility — does this module do exactly one thing?\n                (2) Cognitive load — could a new team member understand this in 5 minutes?\n                (3) Abstraction value — does every abstraction earn its complexity, or is it premature?\n                (4) Dependency direction — does this file depend on things at its own level or below, not above?\n                Add any concerns to your running list. Be specific — cite line ranges and function names.\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 3: PLAN\n  # Prioritize and scope the changes — pure reasoning, no tools\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: plan\n    prompt: |\n      You are planning targeted architectural improvements.\n\n      ## Assessment\n\n      $analyze.output\n\n      ## Principles\n\n      - KISS: prefer straightforward over clever\n      - YAGNI: remove speculative abstractions\n      - Rule of Three: only extract when a pattern appears 3+ times\n      - Each change must be independently revertible\n      - Do NOT mix refactoring with behavior changes\n      - Scope to what can be done safely in one pass (max 5-7 files)\n\n      ## Instructions\n\n      1. From the assessment, select the top 3-5 highest-impact, lowest-risk improvements\n      2. For each, write a precise plan: which file, what to change, why\n      3. Order them so each change is independent (no cascading dependencies between changes)\n      4. Estimate blast radius — how many other files are affected\n\n      ## Output\n\n      Write the plan as a numbered list. Be specific about exactly what code to change.\n      Keep it concise — the implement node will follow this literally.\n    depends_on: [analyze]\n    allowed_tools: [Read]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 4: EXECUTE\n  # Make the changes with hooks creating quality feedback loops\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: simplify\n    prompt: |\n      You are implementing targeted architectural simplifications.\n\n      ## Plan\n\n      $plan.output\n\n      ## Rules\n\n      - Follow the plan exactly — do not add extra improvements you notice along the way\n      - Each change must preserve existing behavior (refactor only, no feature changes)\n      - After each file edit, you'll be prompted to validate — follow those instructions\n      - If a change turns out to be harder than expected, skip it and move on\n      - Commit each logical change separately with a clear commit message\n\n      ## Instructions\n\n      1. Work through the plan items in order\n      2. For each item: read the file, make the change, follow the post-edit checklist\n      3. After all changes, do a final `git diff --stat` to verify scope\n    depends_on: [plan]\n    context: fresh\n    hooks:\n      PreToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PreToolUse\n              additionalContext: >\n                Before writing: Is this file in your plan? If not, explain why you're\n                touching it. Check how many files import from this module — changes to\n                widely-imported modules need extra scrutiny.\n      PostToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            systemMessage: >\n              You just modified a file. Do these things NOW before moving on:\n              1. Run the type checker to verify your change compiles\n              2. Re-read the file you changed — is it ACTUALLY simpler, or did you just move complexity around?\n              3. State in ONE sentence why this change reduces complexity. If you cannot justify it, revert it.\n        - matcher: \"Read\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PostToolUse\n              additionalContext: >\n                Before modifying this file, consider: will your change reduce or increase\n                the number of concepts a reader needs to hold in their head?\n        - matcher: \"Bash\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PostToolUse\n              additionalContext: >\n                Check the exit code. If the command failed, diagnose the root cause\n                before attempting a fix. Do not blindly retry.\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 5: VALIDATE\n  # Run full validation suite — bash only, cannot edit to \"fix\" failures\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: validate\n    bash: |\n      echo \"=== TYPE CHECK ===\"\n      bun run type-check 2>&1\n      TC_EXIT=$?\n\n      echo \"\"\n      echo \"=== LINT ===\"\n      bun run lint 2>&1\n      LINT_EXIT=$?\n\n      echo \"\"\n      echo \"=== TESTS ===\"\n      bun run test 2>&1\n      TEST_EXIT=$?\n\n      echo \"\"\n      echo \"=== RESULTS ===\"\n      echo \"Type check: $([ $TC_EXIT -eq 0 ] && echo 'PASS' || echo 'FAIL')\"\n      echo \"Lint: $([ $LINT_EXIT -eq 0 ] && echo 'PASS' || echo 'FAIL')\"\n      echo \"Tests: $([ $TEST_EXIT -eq 0 ] && echo 'PASS' || echo 'FAIL')\"\n\n      # Always exit 0 so downstream nodes can read output and decide\n      if [ $TC_EXIT -eq 0 ] && [ $LINT_EXIT -eq 0 ] && [ $TEST_EXIT -eq 0 ]; then\n        echo \"VALIDATION_STATUS: PASS\"\n      else\n        echo \"VALIDATION_STATUS: FAIL\"\n      fi\n    depends_on: [simplify]\n    timeout: 300000\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 6: FIX VALIDATION FAILURES (if any)\n  # Only runs if validate failed — focused fix with same quality hooks\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: fix-failures\n    prompt: |\n      Review the validation output below.\n\n      ## Validation Output\n\n      $validate.output\n\n      ## Instructions\n\n      If the output ends with \"VALIDATION_STATUS: PASS\", respond with\n      \"All checks passed — no fixes needed.\" and stop.\n\n      If there are failures:\n\n      1. Read the validation failures carefully\n      2. Fix ONLY what's broken — do not make additional improvements\n      3. If a fix requires changing behavior (not just fixing a type/lint error),\n         revert the original change instead\n      4. Run the specific failing check after each fix to confirm it passes\n      5. After all fixes, run the full validation suite: `bun run validate`\n    depends_on: [validate]\n    context: fresh\n    hooks:\n      PostToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            systemMessage: >\n              You just made a fix. Run the specific failing validation check NOW\n              to verify your fix works. Do not batch fixes — verify each one.\n      PreToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PreToolUse\n              additionalContext: >\n                You are fixing validation failures only. Do not make any changes\n                beyond what's needed to pass the failing checks. If in doubt, revert\n                the original change that caused the failure.\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 7: CREATE PR\n  # Hooks ensure this node only does git operations\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: create-pr\n    prompt: |\n      Create a pull request for the architectural improvements.\n\n      ## Context\n\n      - Architecture assessment: $analyze.output\n      - Plan: $plan.output\n      - Validation: $validate.output\n\n      ## Instructions\n\n      1. Stage all changes and create a single commit (or verify existing commits)\n      2. Push the branch: `git push -u origin HEAD`\n      3. Resolve the origin repo — in a fork clone, gh otherwise targets the upstream parent:\n         `ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')`\n      4. Check if a PR already exists: `gh pr list --repo \"$ORIGIN_REPO\" --head $(git branch --show-current)`\n      5. Create the PR targeting `$BASE_BRANCH` as the base branch:\n         `gh pr create --repo \"$ORIGIN_REPO\" --base $BASE_BRANCH --title \"...\" --body \"...\"`\n         - Title: concise description of what was simplified (under 70 chars)\n         - Body: use the format below\n      6. Save the PR URL to `$ARTIFACTS_DIR/.pr-url`\n\n      ## PR Body Format\n\n      ```markdown\n      ## Architectural Sweep\n\n      **Focus**: $ARGUMENTS\n\n      ### Assessment\n\n      [3-5 sentence summary from the architecture assessment]\n\n      ### Changes\n\n      [For each change: what file, what was simplified, why]\n\n      ### Validation\n\n      - [x] Type check passes\n      - [x] Lint passes\n      - [x] Tests pass\n      - [x] Each change preserves existing behavior\n      ```\n    depends_on: [fix-failures]\n    context: fresh\n    hooks:\n      PreToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PreToolUse\n              permissionDecision: deny\n              permissionDecisionReason: \"PR creation node — do not modify source files. Use only git and gh commands.\"\n      PostToolUse:\n        - matcher: \"Bash\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PostToolUse\n              additionalContext: >\n                Verify this command succeeded. If git push or gh pr create failed,\n                read the error message carefully before retrying.\n\n  - id: verify-pr-base\n    bash: |\n      set -euo pipefail\n      # Pin to the origin remote — in a fork clone, gh otherwise queries the upstream parent\n      ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')\n      HEAD_BRANCH=$(git rev-parse --abbrev-ref HEAD)\n      PR_NUMBER=$(gh pr list --repo \"$ORIGIN_REPO\" --head \"$HEAD_BRANCH\" --state open --json number -q '.[0].number')\n      if [ -z \"$PR_NUMBER\" ]; then\n        echo \"No open PR found for branch $HEAD_BRANCH\" >&2\n        exit 1\n      fi\n      EXPECTED=\"$BASE_BRANCH\"\n      ACTUAL=$(gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json baseRefName -q '.baseRefName')\n      if [ \"$ACTUAL\" != \"$EXPECTED\" ]; then\n        echo \"Base mismatch on PR #$PR_NUMBER: expected=$EXPECTED actual=$ACTUAL — re-targeting\" >&2\n        gh pr edit \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --base \"$EXPECTED\"\n      else\n        echo \"PR base verified: $EXPECTED\"\n      fi\n    depends_on: [create-pr]\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-assist": "name: archon-assist\ndescription: |\n  Use when: No other workflow matches the request.\n  Handles: Questions, debugging, exploration, one-off tasks, explanations, CI failures, general help.\n  Capability: Full Claude Code agent with all tools available.\n  Note: Will inform user when assist mode is used for tracking.\n\n# Run in the live checkout, not in a fresh sub-worktree. Without this, every\n# auto-routed `archon-assist` invocation creates an isolated sub-worktree\n# whose edits are unreachable from the calling chat (no commit step, no\n# branch propagation back). With `worktree.enabled: false`, edits land in\n# the parent's working tree where syncWorkspace's #1516 fast-forward\n# default keeps them safe across chat ticks. Closes #1546.\nworktree:\n  enabled: false\n\nnodes:\n  - id: assist\n    command: archon-assist\n",
  "archon-comprehensive-pr-review": "name: archon-comprehensive-pr-review\ndescription: |\n  Use when: User wants a comprehensive code review of a pull request with automatic fixes.\n  Triggers: \"review this PR\", \"review PR #123\", \"comprehensive review\", \"full PR review\",\n            \"review and fix\", \"check this PR\", \"code review\".\n  Does: Syncs PR with main (rebase if needed) -> runs 5 specialized review agents in parallel ->\n        synthesizes findings -> auto-fixes CRITICAL/HIGH issues -> reports remaining issues.\n  NOT for: Quick questions about a PR, checking CI status, simple \"what changed\" queries.\n\n  This workflow produces artifacts in $ARTIFACTS_DIR/../reviews/pr-{number}/ and posts\n  a comprehensive review comment to the GitHub PR.\n\nnodes:\n  - id: scope\n    command: archon-pr-review-scope\n\n  - id: sync\n    command: archon-sync-pr-with-main\n    depends_on: [scope]\n\n  - id: code-review\n    command: archon-code-review-agent\n    depends_on: [sync]\n\n  - id: error-handling\n    command: archon-error-handling-agent\n    depends_on: [sync]\n\n  - id: test-coverage\n    command: archon-test-coverage-agent\n    depends_on: [sync]\n\n  - id: comment-quality\n    command: archon-comment-quality-agent\n    depends_on: [sync]\n\n  - id: docs-impact\n    command: archon-docs-impact-agent\n    depends_on: [sync]\n\n  - id: synthesize\n    command: archon-synthesize-review\n    depends_on: [code-review, error-handling, test-coverage, comment-quality, docs-impact]\n    trigger_rule: one_success\n\n  - id: implement-fixes\n    command: archon-implement-review-fixes\n    depends_on: [synthesize]\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-create-issue": "name: archon-create-issue\ndescription: |\n  Use when: User wants to report a bug or problem as a GitHub issue with automated reproduction.\n  Triggers: \"create issue\", \"file a bug\", \"report this bug\", \"open an issue for\",\n            \"create github issue\", \"report issue\", \"log this bug\".\n  Does: Classifies problem area (haiku) -> gathers context in parallel (templates, git state, duplicates) ->\n        investigates relevant code -> reproduces the issue using area-specific tools (agent-browser, CLI, DB queries) ->\n        gates on reproduction success -> creates issue with full evidence OR reports back if cannot reproduce.\n  NOT for: Feature requests, enhancements, or non-bug work. Only for bugs/problems.\n\n  Reproduction gating: If the issue cannot be reproduced, the workflow does NOT create an issue.\n  Instead, it reports what was tried and suggests next steps to the user.\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 1: CLASSIFY — Haiku classification of user's problem\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: classify\n    prompt: |\n      You are a problem classifier for the Archon codebase. Analyze the user's\n      description and determine the issue type and which area of the system is affected.\n\n      ## User's Description\n      $ARGUMENTS\n\n      ## Area Definitions\n      | Area | Packages | Indicators |\n      |------|----------|------------|\n      | web-ui | @archon/web, @archon/server (routes, web adapter) | UI rendering, SSE streaming, React components, browser behavior |\n      | api-server | @archon/server (routes, middleware) | HTTP endpoints, response codes, request handling |\n      | cli | @archon/cli | CLI commands, workflow invocation from terminal, output formatting |\n      | isolation | @archon/isolation, @archon/git | Worktrees, branch operations, cleanup, environment lifecycle |\n      | workflows | @archon/workflows | YAML parsing, DAG execution, variable substitution, node types |\n      | database | @archon/core (db/) | SQLite/PostgreSQL queries, schema, data integrity, migrations |\n      | adapters | @archon/adapters | Slack/Telegram/GitHub/Discord message handling, auth, polling |\n      | core | @archon/core (orchestrator, handlers, clients) | Message routing, session management, AI client streaming |\n      | other | Any package not covered above | Cross-cutting concerns, build tooling, config, unknown area |\n\n      ## Classification Rules\n      - Choose the MOST SPECIFIC area. \"SSE disconnects\" = web-ui (not api-server).\n      - If ambiguous between two areas, pick the one closer to the user-facing symptom.\n      - Use \"other\" only when the problem genuinely doesn't fit any specific area.\n      - needs_server: Set to \"true\" if reproducing requires a running Archon server.\n        Typically true for: web-ui, api-server, core, adapters.\n        Typically false for: cli, isolation, workflows, database.\n        For \"other\": use your judgment based on the description.\n      - repro_hint: Extract the user's reproduction steps into a concise instruction.\n        If no explicit steps given, infer the most likely way to trigger the issue.\n\n      Provide reasoning for your classification.\n    model: small\n    allowed_tools: []\n    output_format:\n      type: object\n      properties:\n        type:\n          type: string\n          enum: [\"bug\", \"regression\", \"crash\", \"performance\", \"configuration\"]\n        area:\n          type: string\n          enum: [\"web-ui\", \"api-server\", \"cli\", \"isolation\", \"workflows\", \"database\", \"adapters\", \"core\", \"other\"]\n        title:\n          type: string\n        keywords:\n          type: string\n        repro_hint:\n          type: string\n        needs_server:\n          type: string\n          enum: [\"true\", \"false\"]\n      required: [type, area, title, keywords, repro_hint, needs_server]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 2: PARALLEL CONTEXT GATHERING\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: fetch-template\n    bash: |\n      # Search for GitHub issue templates in standard locations\n      TEMPLATES_FOUND=0\n\n      # Check for issue template directory (YAML-based templates)\n      if [ -d \".github/ISSUE_TEMPLATE\" ]; then\n        echo \"=== Issue Templates Found ===\"\n        for f in .github/ISSUE_TEMPLATE/*.md .github/ISSUE_TEMPLATE/*.yaml .github/ISSUE_TEMPLATE/*.yml; do\n          if [ -f \"$f\" ]; then\n            TEMPLATES_FOUND=$((TEMPLATES_FOUND + 1))\n            echo \"--- Template: $f ---\"\n            cat \"$f\"\n            echo \"\"\n          fi\n        done\n      fi\n\n      # Check for single issue template\n      for f in .github/ISSUE_TEMPLATE.md docs/ISSUE_TEMPLATE.md; do\n        if [ -f \"$f\" ]; then\n          TEMPLATES_FOUND=$((TEMPLATES_FOUND + 1))\n          echo \"--- Template: $f ---\"\n          cat \"$f\"\n        fi\n      done\n\n      if [ \"$TEMPLATES_FOUND\" -eq 0 ]; then\n        echo \"No issue templates found — will use standard format\"\n      fi\n    depends_on: [classify]\n\n  - id: git-context\n    bash: |\n      echo \"=== Branch ===\"\n      git branch --show-current\n\n      echo \"=== Recent Commits (last 15) ===\"\n      git log --oneline -15\n\n      echo \"=== Working Tree Status ===\"\n      git status --short\n\n      echo \"=== Modified Files (last 3 commits) ===\"\n      git diff --name-only HEAD~3..HEAD 2>/dev/null || echo \"(fewer than 3 commits)\"\n\n      echo \"=== Environment ===\"\n      echo \"Node: $(node --version 2>/dev/null || echo 'N/A')\"\n      echo \"Bun: $(bun --version 2>/dev/null || echo 'N/A')\"\n      echo \"OS: $(uname -s 2>/dev/null || echo 'Windows') $(uname -r 2>/dev/null || ver 2>/dev/null || echo '')\"\n      echo \"Platform: $(uname -m 2>/dev/null || echo 'unknown')\"\n    depends_on: [classify]\n\n  - id: dedup-check\n    bash: |\n      KEYWORDS=$classify.output.keywords\n      echo \"=== Searching for duplicates: $KEYWORDS ===\"\n\n      echo \"--- Open Issues ---\"\n      gh issue list --search \"$KEYWORDS\" --state open --limit 5 --json number,title,url,labels 2>/dev/null || echo \"No open matches\"\n\n      echo \"--- Recently Closed ---\"\n      gh issue list --search \"$KEYWORDS\" --state closed --limit 3 --json number,title,url,labels 2>/dev/null || echo \"No closed matches\"\n    depends_on: [classify]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 3: INVESTIGATE — Search codebase for related code\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: investigate\n    prompt: |\n      You are a codebase investigator. Search for code related to the reported problem.\n\n      ## Problem\n      - **Area**: $classify.output.area\n      - **Type**: $classify.output.type\n      - **Title**: $classify.output.title\n      - **Reproduction hint**: $classify.output.repro_hint\n\n      ## Git Context\n      $git-context.output\n\n      ## Instructions\n\n      1. Based on the area, search the relevant packages:\n         - web-ui: `packages/web/src/`, `packages/server/src/adapters/web/`, `packages/server/src/routes/`\n         - api-server: `packages/server/src/routes/`, `packages/server/src/`\n         - cli: `packages/cli/src/`\n         - isolation: `packages/isolation/src/`, `packages/git/src/`\n         - workflows: `packages/workflows/src/`\n         - database: `packages/core/src/db/`\n         - adapters: `packages/adapters/src/`\n         - core: `packages/core/src/orchestrator/`, `packages/core/src/handlers/`\n         - other: search broadly based on keywords — check `packages/*/src/`, config files, build scripts\n\n      2. Find: entry points, error handling paths, related type definitions, recent changes\n         to the affected area (check git log for the specific files).\n\n      3. Write your findings to `$ARTIFACTS_DIR/issue-context.md` with this structure:\n         ```\n         # Codebase Investigation\n         ## Relevant Files\n         - `file:line` — description of what's there\n         ## Error Handling\n         - How errors are currently handled in this area\n         ## Recent Changes\n         - Any recent commits touching this code\n         ## Suspected Root Cause\n         - Based on code analysis, where the bug likely is\n         ```\n\n      Be thorough but focused. Only include files directly relevant to the reported problem.\n    depends_on: [classify, git-context]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 4: REPRODUCE — Area-specific issue reproduction\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: start-server\n    bash: |\n      # Allocate a free port using Bun's OS assignment\n      PORT=$(bun -e \"const s = Bun.serve({port: 0, fetch: () => new Response('')}); console.log(s.port); s.stop()\")\n      echo \"$PORT\" > \"$ARTIFACTS_DIR/.server-port\"\n\n      # Start dev server in background\n      PORT=$PORT bun run dev:server > \"$ARTIFACTS_DIR/.server-log\" 2>&1 &\n      SERVER_PID=$!\n      echo \"$SERVER_PID\" > \"$ARTIFACTS_DIR/.server-pid\"\n\n      # Wait for server to be ready (up to 30s)\n      for i in $(seq 1 30); do\n        if curl -s \"http://localhost:$PORT/api/health\" > /dev/null 2>&1; then\n          echo \"Server ready on port $PORT (PID: $SERVER_PID)\"\n          exit 0\n        fi\n        sleep 1\n      done\n\n      echo \"WARNING: Server may not be fully ready after 30s (port $PORT, PID $SERVER_PID)\"\n      echo \"Continuing anyway — reproduce node will handle connection errors\"\n    depends_on: [classify]\n    when: \"$classify.output.needs_server == 'true'\"\n    timeout: 45000\n\n  - id: reproduce\n    prompt: |\n      You are an issue reproduction specialist. Your job is to reproduce the reported\n      problem and capture evidence (screenshots, command output, error messages).\n\n      ## Problem Context\n      - **Area**: $classify.output.area\n      - **Type**: $classify.output.type\n      - **Title**: $classify.output.title\n      - **Reproduction hint**: $classify.output.repro_hint\n\n      ## Investigation Findings\n      $investigate.output\n\n      ## Server Info\n      If a server was started, read the port from: `cat \"$ARTIFACTS_DIR/.server-port\"`\n      If the file doesn't exist, no server is running (area doesn't need one).\n\n      ---\n\n      ## Reproduction Playbooks\n\n      Follow the playbook matching the area. Capture ALL evidence to `$ARTIFACTS_DIR/`.\n\n      ### web-ui\n      1. Read the server port: `PORT=$(cat \"$ARTIFACTS_DIR/.server-port\" | tr -d '\\n')`\n      2. Open the app: `agent-browser open http://localhost:$PORT`\n      3. Take a baseline screenshot: `agent-browser screenshot \"$ARTIFACTS_DIR/repro-01-baseline.png\"`\n      4. Get interactive elements: `agent-browser snapshot -i`\n      5. Navigate to the area related to the issue (use @refs from snapshot)\n      6. Perform the actions described in the repro_hint\n      7. Screenshot each significant state: `agent-browser screenshot \"$ARTIFACTS_DIR/repro-02-action.png\"`\n      8. If an error appears, capture it: `agent-browser get text @errorElement`\n      9. Check browser console: `agent-browser console`\n      10. Check for JS errors: `agent-browser errors`\n      11. Final screenshot: `agent-browser screenshot \"$ARTIFACTS_DIR/repro-03-result.png\"`\n      12. Close browser: `agent-browser close`\n\n      ### api-server\n      1. Read the server port: `PORT=$(cat \"$ARTIFACTS_DIR/.server-port\" | tr -d '\\n')`\n      2. Create a test conversation: `curl -s -X POST http://localhost:$PORT/api/conversations -H \"Content-Type: application/json\" -d '{}'`\n      3. Hit the problematic endpoint based on the repro_hint\n      4. Capture response codes and bodies: `curl -s -w \"\\nHTTP_CODE: %{http_code}\\n\" ...`\n      5. For SSE issues: `curl -s -N http://localhost:$PORT/api/stream/<id>` (timeout after 10s)\n      6. Check server logs: `cat \"$ARTIFACTS_DIR/.server-log\" | tail -50`\n      7. Save all curl output to `$ARTIFACTS_DIR/repro-api-responses.txt`\n\n      ### cli\n      1. Run the CLI command that should trigger the issue\n      2. Capture stdout and stderr separately:\n         `bun run cli <command> > \"$ARTIFACTS_DIR/repro-cli-stdout.txt\" 2> \"$ARTIFACTS_DIR/repro-cli-stderr.txt\"; echo \"EXIT_CODE: $?\" >> \"$ARTIFACTS_DIR/repro-cli-stdout.txt\"`\n      3. If workflow-related: `bun run cli workflow list --json > \"$ARTIFACTS_DIR/repro-workflow-list.json\" 2>&1`\n      4. If the command hangs, use timeout: `timeout 30 bun run cli <command>`\n      5. Check for error messages in output\n\n      ### isolation\n      1. Check current state: `bun run cli isolation list > \"$ARTIFACTS_DIR/repro-isolation-list.txt\" 2>&1`\n      2. Check git worktrees: `git worktree list > \"$ARTIFACTS_DIR/repro-worktree-list.txt\"`\n      3. Check branches: `git branch -a > \"$ARTIFACTS_DIR/repro-branches.txt\"`\n      4. Try the operation that should fail (based on repro_hint)\n      5. Capture the error output\n      6. Query isolation DB: `sqlite3 ~/.archon/archon.db \"SELECT * FROM remote_agent_isolation_environments ORDER BY created_at DESC LIMIT 10\" > \"$ARTIFACTS_DIR/repro-isolation-db.txt\" 2>&1`\n\n      ### workflows\n      1. List workflows: `bun run cli workflow list --json > \"$ARTIFACTS_DIR/repro-workflow-list.json\" 2>&1`\n      2. If a specific workflow is mentioned, try running it:\n         `bun run cli workflow run <name> --no-worktree \"test input\" > \"$ARTIFACTS_DIR/repro-workflow-run.txt\" 2>&1`\n      3. If YAML parsing is the issue, try loading the definition directly\n      4. Check for error messages in execution output\n\n      ### database\n      1. Check DB exists: `ls -la ~/.archon/archon.db 2>/dev/null`\n      2. Run targeted queries against affected tables:\n         - `sqlite3 ~/.archon/archon.db \".schema <table>\" > \"$ARTIFACTS_DIR/repro-db-schema.txt\"`\n         - `sqlite3 ~/.archon/archon.db \"SELECT COUNT(*) FROM <table>\" > \"$ARTIFACTS_DIR/repro-db-counts.txt\"`\n      3. Check for the specific data condition described in the repro_hint\n      4. If PostgreSQL: use `psql $DATABASE_URL -c \"...\"` instead\n\n      ### adapters\n      1. Read the server port: `PORT=$(cat \"$ARTIFACTS_DIR/.server-port\" | tr -d '\\n')`\n      2. Check adapter configuration: look for relevant env vars in `.env`\n      3. Check server startup logs: `cat \"$ARTIFACTS_DIR/.server-log\" | grep -i \"adapter\\|slack\\|telegram\\|github\\|discord\" | head -20`\n      4. If the adapter fails to initialize, capture the error\n      5. Test message routing via web API as a proxy:\n         `curl -s -X POST http://localhost:$PORT/api/conversations/<id>/message -H \"Content-Type: application/json\" -d '{\"message\":\"/status\"}'`\n\n      ### core\n      1. Read the server port: `PORT=$(cat \"$ARTIFACTS_DIR/.server-port\" | tr -d '\\n')`\n      2. Create a conversation: `curl -s -X POST http://localhost:$PORT/api/conversations -H \"Content-Type: application/json\" -d '{}'`\n      3. Send a message that triggers the issue:\n         `curl -s -X POST http://localhost:$PORT/api/conversations/<id>/message -H \"Content-Type: application/json\" -d '{\"message\":\"<repro_hint>\"}'`\n      4. Poll for responses: `curl -s http://localhost:$PORT/api/conversations/<id>/messages`\n      5. Check session state in DB: `sqlite3 ~/.archon/archon.db \"SELECT * FROM remote_agent_sessions WHERE conversation_id='<id>'\" 2>/dev/null`\n      6. Check server logs: `cat \"$ARTIFACTS_DIR/.server-log\" | tail -50`\n\n      ### other\n      1. Run `bun run validate` to check for any obvious failures — capture output:\n         `bun run validate > \"$ARTIFACTS_DIR/repro-validate.txt\" 2>&1; echo \"EXIT_CODE: $?\" >> \"$ARTIFACTS_DIR/repro-validate.txt\"`\n      2. Search the codebase for keywords from the repro_hint:\n         - Use Grep/Glob to find related files\n         - Check recent git log for relevant changes\n      3. If the description implies a build or config issue:\n         - Check `package.json` scripts, `tsconfig.json`, `.env.example`\n         - Try running the relevant build/dev command\n      4. If the description implies a runtime issue:\n         - Start the server (if `.server-port` file exists) and try to trigger the behavior\n         - Check logs for errors\n      5. Document everything you tried, even if nothing reproduces clearly\n\n      ---\n\n      ## Output\n\n      After following the playbook, write your findings to `$ARTIFACTS_DIR/reproduction-results.md`:\n\n      ```markdown\n      # Reproduction Results\n\n      ## Status: [REPRODUCED | NOT_REPRODUCED | PARTIAL]\n\n      ## Steps Taken\n      1. [step]\n      2. [step]\n\n      ## Expected Behavior\n      [what should happen]\n\n      ## Actual Behavior\n      [what actually happened — or \"could not trigger the reported behavior\"]\n\n      ## Evidence Files\n      - `$ARTIFACTS_DIR/repro-*.png` — screenshots (if web-ui)\n      - `$ARTIFACTS_DIR/repro-*.txt` — command output\n      - `$ARTIFACTS_DIR/repro-*.json` — structured data\n\n      ## Environment\n      [OS, versions, relevant config]\n\n      ## Notes\n      [any additional observations, suspected root cause refinements]\n      ```\n\n      CRITICAL: The Status line MUST be exactly one of: REPRODUCED, NOT_REPRODUCED, PARTIAL.\n      This value is read by a downstream bash node to decide whether to create the issue.\n\n      Even if you cannot fully reproduce the issue, document what you tried\n      and what you observed. Partial reproduction is still valuable evidence.\n      Use $agent-browser when browser-based reproduction is relevant.\n    depends_on: [classify, git-context, investigate, start-server]\n    context: fresh\n    skills:\n      - agent-browser\n    trigger_rule: one_success\n    idle_timeout: 300000\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 5: CLEANUP + GATE\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: cleanup-server\n    bash: |\n      SERVER_PID=$(cat \"$ARTIFACTS_DIR/.server-pid\" 2>/dev/null | tr -d '\\n')\n      SERVER_PORT=$(cat \"$ARTIFACTS_DIR/.server-port\" 2>/dev/null | tr -d '\\n')\n\n      if [ -z \"$SERVER_PID\" ]; then\n        echo \"No server was started — skipping cleanup\"\n        exit 0\n      fi\n\n      echo \"Cleaning up server PID $SERVER_PID on port $SERVER_PORT...\"\n\n      # Kill by PID (cross-platform)\n      kill \"$SERVER_PID\" 2>/dev/null || taskkill //F //T //PID \"$SERVER_PID\" 2>/dev/null || true\n\n      # Kill by port (fallback)\n      if [ -n \"$SERVER_PORT\" ]; then\n        fuser -k \"$SERVER_PORT/tcp\" 2>/dev/null || true\n        lsof -ti:\"$SERVER_PORT\" 2>/dev/null | xargs kill -9 2>/dev/null || true\n        netstat -ano 2>/dev/null | grep \":$SERVER_PORT \" | grep LISTENING | awk '{print $5}' | sort -u | while read pid; do\n          taskkill //F //T //PID \"$pid\" 2>/dev/null || true\n        done\n      fi\n\n      # Close any agent-browser session\n      agent-browser close 2>/dev/null || true\n\n      sleep 1\n      echo \"Cleanup complete\"\n    depends_on: [reproduce]\n    trigger_rule: all_done\n\n  - id: check-reproduction\n    bash: |\n      # Read the reproduction status from the results file\n      if [ ! -f \"$ARTIFACTS_DIR/reproduction-results.md\" ]; then\n        echo \"NOT_REPRODUCED\"\n        exit 0\n      fi\n\n      STATUS=$(grep -oE '(NOT_REPRODUCED|REPRODUCED|PARTIAL)' \"$ARTIFACTS_DIR/reproduction-results.md\" | head -1)\n\n      if [ -z \"$STATUS\" ]; then\n        echo \"NOT_REPRODUCED\"\n      else\n        echo \"$STATUS\"\n      fi\n    depends_on: [cleanup-server]\n    trigger_rule: all_done\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 6: BRANCH ON REPRODUCTION RESULT\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: report-failure\n    prompt: |\n      The issue could not be reproduced. Report this to the user with actionable detail.\n\n      ## Problem Description\n      - **Title**: $classify.output.title\n      - **Area**: $classify.output.area\n      - **Type**: $classify.output.type\n      - **Reproduction hint**: $classify.output.repro_hint\n\n      ## What Was Tried\n      $reproduce.output\n\n      ## Investigation Findings\n      $investigate.output\n\n      ## Instructions\n\n      Report to the user clearly:\n\n      1. **State upfront**: \"Could not reproduce the reported issue. No GitHub issue was created.\"\n\n      2. **Summarize what was tried**: List the specific steps the reproduce node took,\n         based on the area playbook. Be concrete — \"Started server on port X, navigated to Y,\n         clicked Z — no error appeared.\"\n\n      3. **Share what was found**: Include relevant findings from the investigation\n         (code references, recent changes, suspected areas).\n\n      4. **Suggest next steps**:\n         - Ask the user to provide more specific reproduction steps\n         - Mention any environment-specific factors that might matter\n           (OS, browser, database state, specific data conditions)\n         - If the investigation found suspicious code, mention it as a lead\n         - Suggest running with debug logging: `LOG_LEVEL=debug bun run dev`\n\n      5. **Offer to retry**: \"If you can provide more specific steps, run the workflow\n         again with those details.\"\n\n      Do NOT create a GitHub issue. The purpose of this node is to communicate back to the\n      user so they can provide better information or investigate manually.\n    depends_on: [check-reproduction]\n    when: \"$check-reproduction.output == 'NOT_REPRODUCED'\"\n    context: fresh\n\n  - id: draft-issue\n    prompt: |\n      You are a technical writer drafting a GitHub issue. Assemble all gathered\n      context into a clear, well-structured issue body.\n\n      ## Classification\n      - **Type**: $classify.output.type\n      - **Area**: $classify.output.area\n      - **Title**: $classify.output.title\n\n      ## Issue Template\n      If templates were found, use the most appropriate one as the structure:\n      $fetch-template.output\n\n      ## Duplicate Check Results\n      $dedup-check.output\n\n      ## Codebase Investigation\n      $investigate.output\n\n      ## Reproduction Results\n      $reproduce.output\n\n      ## Instructions\n\n      1. **Check duplicates first**: If the dedup-check found a clearly matching open issue,\n         note this prominently at the top. Still draft the issue but add a note suggesting\n         it may be a duplicate of #XYZ.\n\n      2. **Use the template** if one was found for bug reports. Fill every section with real data.\n\n      3. **Structure** (if no template):\n         ```markdown\n         ## Description\n         [Clear 1-2 sentence description]\n\n         ## Steps to Reproduce\n         [Numbered steps from reproduction results]\n\n         ## Expected Behavior\n         [What should happen]\n\n         ## Actual Behavior\n         [What actually happened, with evidence]\n\n         ## Environment\n         - OS: [from git-context]\n         - Bun: [version]\n         - Node: [version]\n         - Branch: [current branch]\n\n         ## Relevant Code\n         [Key file:line references from investigation]\n\n         ## Additional Context\n         [Screenshots, logs, database state — reference artifact files]\n         ```\n\n      4. **Include reproduction evidence**:\n         - If REPRODUCED: include full steps and all evidence\n         - If PARTIAL: include what was observed, note incomplete reproduction\n\n      5. **Suggest labels** based on classification:\n         - Area label: `area: web`, `area: cli`, `area: workflows`, etc.\n         - Type label: `bug`, `regression`, `performance`, etc.\n\n      6. Write the complete issue body to `$ARTIFACTS_DIR/issue-draft.md`\n\n      7. Write a one-line suggested title to `$ARTIFACTS_DIR/.issue-title`\n\n      8. Write suggested labels (comma-separated) to `$ARTIFACTS_DIR/.issue-labels`\n    depends_on: [check-reproduction, fetch-template, dedup-check, investigate]\n    when: \"$check-reproduction.output != 'NOT_REPRODUCED'\"\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 7: CREATE ISSUE\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: create-issue\n    prompt: |\n      Create the GitHub issue using the drafted content.\n\n      ## Instructions\n\n      1. Read the draft: `cat \"$ARTIFACTS_DIR/issue-draft.md\"`\n      2. Read the title: `cat \"$ARTIFACTS_DIR/.issue-title\"`\n      3. Read suggested labels: `cat \"$ARTIFACTS_DIR/.issue-labels\"`\n\n      4. Check which labels actually exist in the repo:\n         ```bash\n         gh label list --json name -q '.[].name' | head -50\n         ```\n         Only use labels that exist. Skip any suggested label that doesn't match.\n\n      5. Create the issue:\n         ```bash\n         gh issue create \\\n           --title \"$(cat \"$ARTIFACTS_DIR/.issue-title\")\" \\\n           --body-file \"$ARTIFACTS_DIR/issue-draft.md\" \\\n           --label \"label1,label2\"\n         ```\n\n      6. Capture the result:\n         ```bash\n         ISSUE_URL=$(gh issue list --limit 1 --json url -q '.[0].url')\n         echo \"$ISSUE_URL\" > \"$ARTIFACTS_DIR/.issue-url\"\n         ```\n\n      7. Report to the user:\n         - Issue URL\n         - Title\n         - Labels applied\n         - Whether duplicates were found\n         - Summary of reproduction results (reproduced/partial)\n    depends_on: [draft-issue]\n    context: fresh\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-deliver": "name: archon-deliver\ndescription: |\n  The delivery tail, autonomous on its green path: implement the work, gate on\n  green, open a draft PR, review it, correct and close the findings, validate,\n  wait for checks to clear, then flip the PR ready for review. Late CI red that\n  the branch did not introduce pauses for an explicit rerun and resume. There\n  is no in-run approval gate — the human gate is PR review and merge on GitHub,\n  outside the run.\n\n  Use when: decided work should become a reviewed, ready-to-merge PR —\n  \"deliver this plan\", \"take this to a PR\", \"build and ship this\".\n  NOT for: deciding what to build, or merging (always human).\n\n# Review establishes the first verdict. When blockers remain, a bounded static\n# body repeats fix → light review, so every correction is independently checked\n# and a clean review stops immediately. Exhausting the bound fails truthfully\n# with the PR still draft and the canonical report carrying the open findings.\n\nrequires: [github]\n\ninputs:\n  work:\n    default: \"\"\n    description: >-\n      What to deliver — a plan path, findings, or a description. Empty means\n      the run's trigger message is the work.\n  prior_report:\n    default: \"\"\n    description: >-\n      Cross-run review continuity: the previous delivery run's review report\n      path. Round 1 then verifies prior findings (rejections included) instead\n      of relitigating them from scratch. Empty on a first delivery.\n  # Error review can be forced on or off. Code, seams, simplify, and tests always run;\n  # docs runs only when the classifier finds shipped documentation in the diff.\n  errors:\n    default: \"auto\"\n    description: Silent-failure lens — auto, true, or false.\n\n# The returns node is what a composed dependency on this workflow resolves to,\n# and what a caller's binding of this workflow's output reads. Both must mean\n# \"the delivery finished\": the flip is the delivery's proof, where the pr\n# node's record exists from the moment of creation even when everything after\n# it dies. Returning the flip makes a failed flip block a composing caller's\n# terminal node, an earlier death hand it a null, and a success hand it the\n# read-back-verified URL — never a stale record presented as a delivery.\n# The deliberate cost: when the flip itself FAILS, the composing tail's\n# terminal node is blocked, so its caveat and discovery surfacing is skipped\n# along with the false delivery claim — the operator gets the flip's own\n# error, which names the recovery. Truthful failure beats a lying report;\n# surfacing caveats on every failure path is terminal-result ownership the\n# engine is growing toward, not something each tail should hand-roll.\nreturns: flip-ready\n\nnodes:\n  - id: impl\n    include: archon-implement\n    with:\n      work: \"$INPUTS.work\"\n\n  # R3's gate: run success never certifies green — this does, deterministically,\n  # before anything public happens. Strict field access: a missing field fails\n  # the node rather than passing the gate. It fails on red the change introduced\n  # and passes red the change cannot have caused, recording that caveat for every\n  # downstream reader — see scripts/gate-green.py for why that trade is safe.\n  - id: gate-green\n    script: gate-green\n    runtime: uv\n    depends_on: [impl]\n    with:\n      green: \"$impl.output.green\"\n      red_cause: \"$impl.output.red_cause\"\n      summary: \"$impl.output.summary\"\n      stage: \"The implementation\"\n\n  - id: pr\n    include: archon-pr\n    with:\n      draft: \"true\"\n    depends_on: [gate-green]\n\n  # Initial review: full on a first delivery, light continuation when\n  # the caller passes the previous run's report (adjudications carry across\n  # runs instead of being relitigated).\n  # Review scope is decided from the actual PR, not declared blind at launch:\n  # the diff is information that does not exist until the PR does. classify\n  # judges whether errors and docs warrant their conditional lenses; resolve-scope\n  # then merges the operator's declared error override over that judgment. Its\n  # output feeds the errors gate, while the classifier feeds the docs gate. Round\n  # 1 decides once,\n  # and correction reviews preserve those concerns while one continuation\n  # reviewer judges the prior report and correction delta.\n  - id: classify\n    command: classify-review-scope\n    depends_on: [pr]\n    mutates_checkout: false\n    output_type: review-scope\n    output_format:\n      type: object\n      properties:\n        errors: { type: boolean }\n        docs: { type: boolean }\n        reasons:\n          type: object\n          properties:\n            errors: { type: string }\n            docs: { type: string }\n          required: [errors, docs]\n      required: [errors, docs, reasons]\n\n  # Deterministic merge at the boundary: a declared 'true'/'false' beats the\n  # classifier; 'auto' adopts its judgment. Output values are the strings the\n  # lens gates compare against.\n  - id: resolve-scope\n    script: resolve-review-scope\n    runtime: uv\n    with:\n      c_errors: \"$classify.output.errors\"\n    depends_on: [classify]\n\n  - id: review\n    include: archon-review\n    with:\n      # The PR node's structured read-back is the target authority. Review must\n      # not rediscover an ambient branch→PR mapping.\n      scope: \"$pr.output.number\"\n      prior_report: \"$INPUTS.prior_report\"\n      work_order: \"$INPUTS.work\"\n      errors: \"$resolve-scope.output.errors\"\n      docs: \"$classify.output.docs\"\n    depends_on: [resolve-scope]\n\n  # Validate the authored verdict before it controls a costly branch. `ready`\n  # remains the review outcome; `action` says what delivery may do about it.\n  - id: review-action\n    script: validate-review-action\n    runtime: uv\n    with:\n      ready: \"$review.output.ready\"\n      action: \"$review.output.action\"\n    depends_on: [review]\n\n  # A ready initial review skips this block. Otherwise each iteration corrects\n  # the current canonical findings, proves the correction is green, then runs a\n  # fresh continuation review over the report and delta, never an unreviewed\n  # final fix. The bound\n  # is a runaway backstop, not a pacing device: until_bash ends the loop the\n  # moment a recheck certifies ready, so a healthy fix-class run still exits in\n  # one or two rounds. Five rounds is calibrated to the feature-class evidence\n  # (2026-08-25: every executor-heavy delivery needed 4-6 rounds and every\n  # non-starved resume converged; 3 cut two converging runs short). A per-lane\n  # bound would need runtime-parameterized composition, which the language\n  # deliberately does not have — the flat bound buys the same outcome free.\n  #\n  # CI feeds the fix, without waiting: checks run on the pushed commits while\n  # review happens, so concluded results usually exist by the time a round\n  # starts. Each round reads that state once, at its boundary — after the\n  # previous recheck landed — and hands it to the fix as evidence. A failure a\n  # check can prove is cheapest to fix here, in the round that caused it, not\n  # an hour later at the terminal wait. The loop itself never waits on CI, and\n  # await-checks below remains the authority on the flip.\n  - id: corrections\n    depends_on: [review-action]\n    when: \"$review-action.output.action == 'correct'\"\n    loop_group:\n      # `none` converged and `replan` must stop correction. gate-ready below\n      # accepts only `none`; a replan outcome leaves the PR draft and fails with\n      # the canonical report intact instead of spending another correction.\n      until_bash: test $recheck-action.output.action != \"correct\"\n      max_iterations: 5\n      fresh_context: true\n      nodes:\n        # Evidence provisioning, never a gate: this node cannot fail the round\n        # and never waits. A read that fails, times out, or finds no checks\n        # reports that fact and the round proceeds on the review findings\n        # alone. One read, one captured document — deriving failures and counts\n        # from separate reads could present a half-failed read as clean CI. The\n        # engine owns the bounded read. A timeout skips this optional producer;\n        # ci-evidence below turns that absence into the declared fallback passed\n        # to the fix. The exit code is read together with the captured output,\n        # never alone — this gh form can encode check state in its exit code and\n        # can exit zero on failing checks, so non-zero with output is data, and\n        # only empty output from a failed read means the read itself failed.\n        - id: ci-note\n          timeout: 45000\n          on_timeout: skip\n          bash: |\n            PR_NUMBER=$pr.output.number\n            ORIGIN_REPO=$(git remote get-url origin 2>/dev/null | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##' || true)\n            LINES=$(gh pr checks \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json name,bucket \\\n              --jq '.[] | if .bucket == \"pending\" then \"PENDING\" elif .bucket == \"pass\" or .bucket == \"skipping\" then \"GREEN\" else \"RED \\(.name) (\\(.bucket))\" end' \\\n              2>/dev/null)\n            RC=$?\n            if [ \"$RC\" -ne 0 ] && [ -z \"$LINES\" ]; then\n              echo \"No CI evidence is available for this round (the check read failed). Proceed on the review findings alone.\"\n              exit 0\n            fi\n            if [ -z \"$LINES\" ]; then\n              echo \"No CI evidence is available for this round (no checks reported). Proceed on the review findings alone.\"\n              exit 0\n            fi\n            FAILING=$(printf '%s\\n' \"$LINES\" | sed -n 's/^RED /- /p')\n            PENDING=$(printf '%s\\n' \"$LINES\" | grep -c '^PENDING') || true\n            echo \"CI state for this pull request, read at the start of this round; it describes the currently pushed head:\"\n            if [ -n \"$FAILING\" ]; then\n              echo \"Concluded non-green checks:\"\n              printf '%s\\n' \"$FAILING\"\n            else\n              echo \"No concluded failures.\"\n            fi\n            case \"$PENDING\" in\n              ''|0) ;;\n              *) echo \"$PENDING check(s) still running — never wait on them.\" ;;\n            esac\n            exit 0\n\n        - id: ci-evidence\n          script: console.log(process.env.INPUTS_NOTE ?? '')\n          runtime: bun\n          depends_on: [ci-note]\n          trigger_rule: all_done\n          with:\n            note:\n              from: \"$ci-note.output\"\n              if_skipped: >-\n                No CI evidence is available for this round (the check read timed out).\n                Proceed on the review findings alone.\n\n        - id: fix\n          include: archon-implement\n          depends_on: [ci-evidence]\n          with:\n            work: >-\n              Fix every open Critical and Important finding recorded in\n              $ARTIFACTS_DIR/review/report.md, within the accepted work order\n              below. Read both in full before editing. When a causal finding\n              records a finite affected-member inventory, the finding is not\n              fixed until every affected member is handled and the smallest\n              relevant proof passes. Do not cross an explicit boundary to make\n              a finding disappear; the following review must return replan if\n              the requested outcome requires that expansion.\n\n              Concluded CI evidence observed before this round — evidence, not\n              a verdict, and the same red-cause discipline applies to it:\n\n              $ci-evidence.output\n\n              A concluded CI failure that this branch's changes introduced is\n              part of this round's work, exactly like a review finding. Red on\n              a check this branch cannot have caused is classified with\n              evidence, not chased. Never wait on running checks — but results\n              can conclude while you work, so before declaring done, re-read\n              the concluded check state for this pull request with one\n              non-blocking read, and treat anything newly red the same way.\n\n              Accepted work order:\n              $INPUTS.work\n\n              When the correction is green, push its commits to the branch this\n              run is on. Push it explicitly by name; do not let git select an\n              upstream. Do not change the PR's draft state or edit the canonical\n              review comment; the following review owns that public verdict.\n              Record the exact push target and a read-back of the remote ref in\n              implementation.md; never record credentials.\n\n        # The same gate, same script: a correction can hit inherited or environment\n        # red exactly as the first implementation can, and a\n        # correction refused for a red it did not cause wastes the whole round.\n        - id: gate-correction-green\n          script: gate-green\n          runtime: uv\n          depends_on: [fix]\n          with:\n            green: \"$fix.output.green\"\n            red_cause: \"$fix.output.red_cause\"\n            summary: \"$fix.output.summary\"\n            stage: \"The correction\"\n\n        - id: recheck\n          include: archon-review\n          with:\n            scope: \"$pr.output.number\"\n            prior_report: \"$ARTIFACTS_DIR/review/report.md\"\n            work_order: \"$INPUTS.work\"\n            # Continuation mode owns coverage and skips every specialist,\n            # regardless of these conditional-lens bindings.\n            errors: \"$resolve-scope.output.errors\"\n            docs: \"$classify.output.docs\"\n          depends_on: [gate-correction-green]\n\n        - id: recheck-action\n          script: validate-review-action\n          runtime: uv\n          with:\n            ready: \"$recheck.output.ready\"\n            action: \"$recheck.output.action\"\n          depends_on: [recheck]\n\n  # none_failed_min_one_success joins the mutually exclusive paths as bound\n  # values: the\n  # initial review's verdict directly, and the correction loop's final verdict\n  # with if_skipped defaults. The loop can stop on `none` (ready) or `replan`\n  # (truthful terminal refusal); the script below owns that final distinction.\n  # A failed loop (bound exhausted) or failed review prevents this node from\n  # running, so lifecycle success alone never certifies readiness. if_skipped\n  # covers only skipped/pending producers, never failed ones.\n  - id: gate-ready\n    script: gate-ready\n    runtime: uv\n    depends_on: [review-action, corrections]\n    trigger_rule: none_failed_min_one_success\n    with:\n      review_ready: { from: \"$review-action.output.ready\", if_skipped: false }\n      review_action: { from: \"$review-action.output.action\", if_skipped: null }\n      correction_ready: { from: \"$corrections.output.ready\", if_skipped: false }\n      correction_action: { from: \"$corrections.output.action\", if_skipped: null }\n\n  # Correction rounds change the diff after `pr` wrote the description, so\n  # concrete claims in the body can be falsified by the very fixes the review\n  # demanded. One resync, once readiness is certified — never per iteration\n  # (that would be repeated public writes describing diffs the next iteration\n  # falsifies). Skipped when the initial review was already ready: the diff\n  # never changed after the body was written.\n  - id: sync-pr-body\n    command: sync-pr-body\n    model: medium\n    with:\n      pr_number: \"$pr.output.number\"\n      pr_head: \"$pr.output.head\"\n    depends_on: [gate-ready]\n    when: \"$review.output.ready == 'false'\"\n\n  # Final local gate, ALWAYS run: the project's own checks via the validate\n  # package. Uniform on every path — and when CI is maintainer-gated (fork\n  # PRs), this is the only validation before the flip.\n  - id: validate\n    include: archon-validate\n    depends_on: [gate-ready]\n\n  # The third gate on the same script, for the same reason: a local gate that\n  # refuses every red refuses red the change did not cause, and the base break\n  # this branch inherited is exactly the red that survives to here. Introduced red\n  # still stops the run. Inherited or environment red proceeds to await-checks,\n  # where the pull request's own CI decides — an inherited break is red there\n  # too, is classified once more by the convergence pass below, and pauses for\n  # explicit operator action before any ready flip can run.\n  - id: gate-validated\n    script: gate-green\n    runtime: uv\n    depends_on: [validate]\n    with:\n      green: \"$validate.output.green\"\n      red_cause: \"$validate.output.red_cause\"\n      summary: \"$validate.output.summary\"\n      stage: \"The project gate\"\n\n  # CI wait, durably. The probe classifies check state once; a pending state\n  # routes into the engine's `wait:` node, which suspends the run and\n  # releases the worker slot. A concluded GitHub check signals the wait and\n  # the continuation scheduler resumes it; the five-minute deadline preserves\n  # progress when no webhook arrives. Red is a reported state here, never a\n  # body failure: the probe declares it, the loop exits as concluded, and the\n  # convergence pass below owns what red means. A concluded probe skips the\n  # pause and `until_bash` ends the loop with zero wasted wait. 13 iterations\n  # bound the watch at ~60 minutes of CI time, the same ceiling the poller had\n  # — exhausting it fails the run rather than flipping a PR whose CI never\n  # ended.\n  - id: await-checks\n    loop_group:\n      max_iterations: 13\n      # Completion computed EXTERNALLY (gh state), never from body-node output\n      # substitution: the resumed-wait completion recheck does not evaluate\n      # until_bash against the iteration's outputs (seen flipping a PR\n      # with CI still running). Red counts as done here; ci-verdict below is\n      # the node that classifies a concluded red — never flip-ready first —\n      # and flip-ready's preflight refuses any non-green state regardless.\n      until_bash: '! gh pr checks --json bucket --jq \".[].bucket\" 2>/dev/null | grep -q \"^pending$\"'\n      nodes:\n        - id: ci-probe\n          script: check-ci\n          runtime: uv\n          # The probe's only in-process wait is the single 60 s registration\n          # grace; headroom over the 120 s script default keeps that honest.\n          timeout: 180000\n        - id: ci-pause\n          wait:\n            event: checks.complete\n            deadline_ms: 300000\n          when: $ci-probe.output.state == 'pending'\n          depends_on: [ci-probe]\n    depends_on: [gate-validated]\n\n  # Late-red convergence. Review convergence and CI conclusion race: a\n  # branch-introduced failure can conclude after the last recheck, the wait\n  # exits on any non-pending state, and flip-ready's only moves are flip or\n  # terminal failure. The pass below is the bounded route between them:\n  # classify, correct, re-review, re-await. It sits after the wait because\n  # loop completion is computed externally (see await-checks) and a DAG has\n  # no back-edges.\n  - id: ci-verdict\n    script: check-ci\n    runtime: uv\n    timeout: 180000\n    depends_on: [await-checks]\n\n  # One round, expressed natively: max_iterations bounds the pass, and the\n  # loop converges only on a `none` verdict. The terminal result carries both\n  # that reviewed verdict and the correction's red classification so the DAG\n  # can distinguish an introduced failure from red that requires an outside\n  # action. Entered only on concluded red; every other state skips the pass.\n  - id: ci-corrections\n    depends_on: [ci-verdict]\n    when: \"$ci-verdict.output.state == 'red'\"\n    loop_group:\n      until_bash: test $ci-round-result.output.action = \"none\"\n      max_iterations: 1\n      nodes:\n        - id: ci-fix\n          include: archon-implement\n          with:\n            work: >-\n              CI concluded non-green after the review converged. The failing\n              checks:\n\n              $ci-verdict.output.detail\n\n              The same red-cause discipline as every round applies. A concluded\n              CI failure this branch's changes introduced is this pass's work:\n              fix it at the cause and push the correction to the branch this\n              run is on, explicitly by name. Red on a check this branch cannot\n              have caused is classified with evidence — red_cause inherited or\n              environment, with the summary naming the proof — never chased and\n              never \"fixed\" by weakening a test. Do not change the PR's draft\n              state or edit the canonical review comment; the following review\n              owns that public verdict.\n\n              Accepted work order, for scope only — do not reopen it:\n              $INPUTS.work\n\n        # The same gate, same script, fourth consumer: introduced-and-unfixed\n        # or unexplained red refuses loudly; inherited or environment red\n        # passes with its caveat recorded and routes to the explicit action\n        # wait below.\n        - id: gate-ci-fix\n          script: gate-green\n          runtime: uv\n          depends_on: [ci-fix]\n          with:\n            green: \"$ci-fix.output.green\"\n            red_cause: \"$ci-fix.output.red_cause\"\n            summary: \"$ci-fix.output.summary\"\n            stage: \"The CI correction\"\n\n        # Never an unreviewed final fix — the corrections loop's rule holds\n        # for this pass too.\n        - id: ci-recheck\n          include: archon-review\n          with:\n            scope: \"$pr.output.number\"\n            prior_report: \"$ARTIFACTS_DIR/review/report.md\"\n            work_order: \"$INPUTS.work\"\n            errors: \"$resolve-scope.output.errors\"\n            docs: \"$classify.output.docs\"\n          depends_on: [gate-ci-fix]\n\n        - id: ci-recheck-action\n          script: validate-review-action\n          runtime: uv\n          with:\n            ready: \"$ci-recheck.output.ready\"\n            action: \"$ci-recheck.output.action\"\n          depends_on: [ci-recheck]\n\n        - id: ci-round-result\n          script: ci-round-result\n          runtime: uv\n          with:\n            ready: \"$ci-recheck-action.output.ready\"\n            action: \"$ci-recheck-action.output.action\"\n            red_cause: \"$ci-fix.output.red_cause\"\n          depends_on: [ci-recheck-action]\n\n  # The re-wait after a pushed correction: same probe, webhook wake-up,\n  # five-minute deadline fallback, and ceiling as await-checks. On an inherited\n  # or environment classification nothing was pushed, the state is still\n  # concluded red, and this exits in one probe before the explicit action route\n  # below.\n  - id: await-fix-checks\n    loop_group:\n      max_iterations: 13\n      until_bash: '! gh pr checks --json bucket --jq \".[].bucket\" 2>/dev/null | grep -q \"^pending$\"'\n      nodes:\n        - id: fix-ci-probe\n          script: check-ci\n          runtime: uv\n          timeout: 180000\n        - id: fix-ci-pause\n          wait:\n            event: checks.complete\n            deadline_ms: 300000\n          when: $fix-ci-probe.output.state == 'pending'\n          depends_on: [fix-ci-probe]\n    depends_on: [ci-corrections]\n\n  # Late red that the branch did not introduce needs a person, not another\n  # autonomous correction. Preserve the draft PR and the recorded refusal,\n  # then probe once per explicit resume until the operator has rerun the check.\n  - id: ci-attention-route\n    script: ci-attention-route\n    runtime: uv\n    depends_on: [ci-verdict, ci-corrections, await-fix-checks]\n    trigger_rule: none_failed_min_one_success\n    with:\n      red_cause: { from: \"$ci-corrections.output.red_cause\", if_skipped: \"\" }\n\n  - id: ci-attention\n    depends_on: [ci-attention-route]\n    when: \"$ci-attention-route.output.attention == 'true'\"\n    loop_group:\n      max_iterations: 13\n      until_bash: test $attention-ci-probe.output.state = \"concluded\"\n      nodes:\n        - id: attention-ci-probe\n          script: check-ci\n          runtime: uv\n          timeout: 180000\n        - id: attention-ci-pause\n          wait:\n            attention: >-\n              CI remains non-green for pull request\n              #$pr.output.number after Archon classified the failure as\n              $ci-attention-route.output.red_cause:\n              $attention-ci-probe.output.detail\n              Re-run the failing check, then resume this run.\n          when: \"$attention-ci-probe.output.state != 'concluded'\"\n          depends_on: [attention-ci-probe]\n\n  - id: flip-ready\n    bash: |\n      set -euo pipefail\n      # --repo pins to the origin remote: gh's default resolution in a\n      # fork clone targets the upstream parent instead. With --repo, gh disables\n      # branch inference and REQUIRES an explicit selector — omitting it is a\n      # usage error.\n      # Nothing below streams a command's own output. The engine broadcasts a\n      # node's stderr to the operator as it runs and retains what the node prints,\n      # so every git and gh call here is captured: this node's authored messages\n      # are the only text that reaches its streams. That also keeps the raw origin\n      # URL — which can carry a credential (https://<token>@host/...) — out of\n      # both, since it is normalized inside the substitution that reads it and\n      # only the owner/repo below ever reaches a command line or a message.\n      if ! ORIGIN_REPO=$(git remote get-url origin 2>/dev/null | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##'); then\n        printf '%s\\n' \"flip-ready: could not read the origin remote.\" >&2\n        exit 1\n      fi\n      case \"$ORIGIN_REPO\" in\n        *[!A-Za-z0-9_.-]*/* | */*[!A-Za-z0-9_.-]* | */*/* | /* | */ | \"\")\n          printf '%s\\n' \"flip-ready: origin remote does not resolve to an owner/repo.\" >&2\n          exit 1\n          ;;\n      esac\n      # The recorded number is the selector. Which branch is checked out is not\n      # re-derived here: the run owns its worktree and the PR was created in it,\n      # so this node cannot be the place that discovers otherwise. See the pack\n      # README on guards.\n      PR_NUMBER=$pr.output.number\n      # Public-surface preflight: the flip is the one irreversible\n      # step, so it re-verifies CI itself instead of trusting the loop above —\n      # any pending or non-green check refuses the flip loudly. The check count\n      # is read through gh's GraphQL API, whose exit code is the structured\n      # signal: success returns the JSON totalCount (0 = no checks configured,\n      # or gated checks that never started — both proceed, matching the probe's\n      # permission-agnostic skip), and a non-zero exit is a failed read that\n      # refuses. A failed observation is not evidence that no CI exists, and the\n      # flip below must never run on one. stderr is dropped like every other\n      # value read in this node — a gh notice must never become the count.\n      if ! CHECK_COUNT=$(gh api graphql \\\n        -f query='query($owner: String!, $repo: String!, $number: Int!) { repository(owner: $owner, name: $repo) { pullRequest(number: $number) { commits(last: 1) { nodes { commit { statusCheckRollup { contexts { totalCount } } } } } } } }' \\\n        -f owner=\"${ORIGIN_REPO%/*}\" -f repo=\"${ORIGIN_REPO#*/}\" -F number=\"$PR_NUMBER\" \\\n        --jq '(.data.repository.pullRequest.commits.nodes[0].commit.statusCheckRollup.contexts.totalCount // 0)' 2>/dev/null); then\n        printf '%s\\n' \"flip-ready: could not read check state.\" >&2\n        exit 1\n      fi\n      if [ \"$CHECK_COUNT\" -gt 0 ]; then\n        # Checks exist: classify them with gh's structured bucket mapping. This\n        # read cannot legitimately be empty (the count above saw checks), so a\n        # failure here is a failed read too, never a no-checks case.\n        if ! NOT_GREEN=$(gh pr checks \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json name,bucket --jq '.[] | select(.bucket != \"pass\" and .bucket != \"skipping\") | \"\\(.name) (\\(.bucket))\"' 2>/dev/null); then\n          printf '%s\\n' \"flip-ready: checks exist but their state could not be read.\" >&2\n          exit 1\n        fi\n        if [ -n \"$NOT_GREEN\" ]; then\n          printf '%s\\n' \"flip-ready: refusing to flip with non-green checks: $NOT_GREEN\" >&2\n          exit 1\n        fi\n      fi\n      # The flip prints a confirmation this node has no use for, and its stdout is\n      # not a value, so both streams are captured together and re-emitted only if\n      # the flip failed — where gh's own words are the diagnostic.\n      if ! FLIP=$(gh pr ready \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" 2>&1); then\n        printf '%s\\n' \"flip-ready: the ready flip failed: $FLIP\" >&2\n        exit 1\n      fi\n      # The two reads below capture a VALUE, so their stderr is dropped rather than\n      # merged: a gh notice must never become the draft state or the delivered URL.\n      # Each failure names the read it could not complete, so neither is silent.\n      if ! draft=$(gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json isDraft --jq .isDraft 2>/dev/null); then\n        printf '%s\\n' \"flip-ready: PR was flipped but its draft state could not be read back.\" >&2\n        exit 1\n      fi\n      if [ \"$draft\" != \"false\" ]; then\n        printf '%s\\n' \"flip-ready: PR still reports draft after the ready flip\" >&2\n        exit 1\n      fi\n      # This node's stdout is the delivered URL and nothing else; `outcome` reports\n      # the value verbatim.\n      if ! gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json url --jq .url 2>/dev/null; then\n        printf '%s\\n' \"flip-ready: PR was flipped but its URL could not be read back.\" >&2\n        exit 1\n      fi\n    # Every failable ancestor is a DIRECT dependency, deliberately: the\n    # engine's default rule turns a failed ancestor into a skipped dependent\n    # at the very next hop, so a join that only names the tail of a chain\n    # never sees the chain's gates fail. Naming every gate ancestor here —\n    # await-checks, the convergence loop, the re-wait, gate-validated,\n    # gate-ready, and validate — is what makes their failures block the flip\n    # instead of skipping past it. The trigger rule lets the green path's\n    # SKIPPED nodes pass — the convergence pass and its re-wait, and a resync\n    # skipped because the initial review was ready — while a FAILED one still\n    # blocks. ci-verdict always runs, anchoring the rule's one required\n    # success. sync-pr-body stays named for the no-CI repo, where the waits\n    # return immediately and the flip could otherwise beat the resync.\n    depends_on:\n      [await-checks, ci-verdict, ci-corrections, await-fix-checks, ci-attention-route,\n       ci-attention, sync-pr-body,\n       gate-validated, gate-ready, validate]\n    trigger_rule: none_failed_min_one_success\n\n  # This tail's terminal report, like every other SDLC tail's (scripts/outcome.py).\n  # flip-ready owns the one irreversible public action and stops there; composing\n  # the text its reader receives is separate work, and a named script keeps it out\n  # of a bash body that would otherwise need a python interpreter Windows hosts do\n  # not reliably have.\n  - id: outcome\n    script: outcome\n    runtime: uv\n    with:\n      pr_url: \"$flip-ready.output\"\n    depends_on: [flip-ready]\n",
  "archon-feature-development": "name: archon-feature-development\ndescription: |\n  Use when: Implementing a feature from an existing plan.\n  Input: Path to a plan file ($ARTIFACTS_DIR/plan.md) or GitHub issue containing a plan.\n  Does: Implements the plan with validation loops -> creates pull request.\n  NOT for: Creating plans (plans should be created separately), bug fixes, code reviews.\n\nnodes:\n  - id: implement\n    command: archon-implement\n    provider: claude\n    model: large\n\n  - id: create-pr\n    command: archon-create-pr\n    depends_on: [implement]\n    context: fresh\n\n  - id: verify-pr-base\n    bash: |\n      set -euo pipefail\n      # Pin to the origin remote — in a fork clone, gh otherwise queries the upstream parent\n      ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')\n      HEAD_BRANCH=$(git rev-parse --abbrev-ref HEAD)\n      PR_NUMBER=$(gh pr list --repo \"$ORIGIN_REPO\" --head \"$HEAD_BRANCH\" --state open --json number -q '.[0].number')\n      if [ -z \"$PR_NUMBER\" ]; then\n        echo \"No open PR found for branch $HEAD_BRANCH\" >&2\n        exit 1\n      fi\n      EXPECTED=\"$BASE_BRANCH\"\n      ACTUAL=$(gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json baseRefName -q '.baseRefName')\n      if [ \"$ACTUAL\" != \"$EXPECTED\" ]; then\n        echo \"Base mismatch on PR #$PR_NUMBER: expected=$EXPECTED actual=$ACTUAL — re-targeting\" >&2\n        gh pr edit \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --base \"$EXPECTED\"\n      else\n        echo \"PR base verified: $EXPECTED\"\n      fi\n    depends_on: [create-pr]\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-fix-github-issue": "name: archon-fix-github-issue\ndescription: |\n  Use when: User wants to FIX, RESOLVE, or IMPLEMENT a solution for a GitHub issue.\n  Triggers: \"fix this issue\", \"implement issue #123\", \"resolve this bug\", \"fix it\",\n            \"fix issue\", \"resolve issue\", \"fix #123\".\n  NOT for: Comprehensive multi-agent reviews (use archon-issue-review-full),\n           questions about issues, CI failures, PR reviews, general exploration.\n\n  DAG workflow that:\n  1. Classifies the issue (bug/feature/enhancement/etc)\n  2. Researches context (web research + codebase exploration via investigate/plan)\n  3. Routes to investigate (bugs) or plan (features) based on classification\n  4. Implements the fix/feature with validation\n  5. Creates a draft PR using the repo's PR template\n  6. Runs smart review (always code review + CLAUDE.md check, conditional additional agents)\n  7. Aggressively self-fixes all findings (tests, docs, error handling)\n  8. Simplifies changed code (implements fixes directly, not just reports)\n  9. Reports results back to the GitHub issue with follow-up suggestions\n\nprovider: claude\nmodel: medium\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 1: FETCH & CLASSIFY\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: parse-request\n    command: archon-parse-user-request\n    model: small\n    output_format:\n      type: object\n      properties:\n        user_request:\n          type: string\n        issue_number:\n          type: string\n        repo:\n          type: string\n        repo_url:\n          type: string\n      required:\n        - user_request\n        - issue_number\n        - repo\n        - repo_url\n\n  - id: fetch-issue\n    bash: |\n      # Substitutions are injected already shell-quoted by Archon — assign them\n      # unquoted, then quote normally as locals (see #1884).\n      req=$parse-request.output.user_request\n      num=$parse-request.output.issue_number\n      repo=$parse-request.output.repo\n      url=$parse-request.output.repo_url\n\n      # user_request is the ONE guaranteed field: verbatim input, never empty for\n      # a non-empty message. Empty here means the parse step failed to return what\n      # it was given — a real defect, and a countable one, rather than an unusual\n      # input. The other three are best-effort by contract.\n      if [ -z \"$req\" ]; then\n        echo \"parse-request returned an empty user_request — the parse step failed.\" >&2\n        echo \"This is a parser defect, not a bad request. Consider raising its model tier.\" >&2\n        exit 1\n      fi\n\n      # `gh issue view <n>` resolves against the CURRENT checkout, so a number\n      # separated from the repository it came from silently fetches this repo's\n      # issue of the same number (#2412). Prefer whichever form the operator\n      # actually gave, most-complete first, and never reassemble one from parts.\n      if [ -n \"$url\" ]; then\n        # A URL carries its repository with it — no number needed, and no\n        # reassembly step to get wrong. Checked BEFORE the numeric gate below: a\n        # best-effort miss on issue_number must not fail a run whose URL alone is\n        # a complete, valid argument.\n        gh issue view \"$url\" --json title,body,labels,comments,state,url,author\n      else\n        if ! printf '%s' \"$num\" | grep -qE '^[0-9]+$'; then\n          echo \"No GitHub issue number found in: $req\" >&2\n          echo \"This workflow fixes a GitHub issue; give it an issue number or URL.\" >&2\n          exit 1\n        fi\n        if [ -n \"$repo\" ]; then\n          # owner/repo#N states the repository explicitly; honour it.\n          gh issue view \"$num\" --repo \"$repo\" --json title,body,labels,comments,state,url,author\n        else\n          gh issue view \"$num\" --json title,body,labels,comments,state,url,author\n        fi\n      fi\n    depends_on: [parse-request]\n\n  - id: classify\n    prompt: |\n      You are an issue classifier. Analyze the GitHub issue below and determine its type.\n\n      ## Issue Content\n\n      $fetch-issue.output\n\n      ## Classification Rules\n\n      | Type | Indicators |\n      |------|------------|\n      | bug | \"broken\", \"error\", \"crash\", \"doesn't work\", stack traces, regression |\n      | feature | \"add\", \"new\", \"support\", \"would be nice\", net-new capability |\n      | enhancement | \"improve\", \"better\", \"update existing\", \"extend\", incremental improvement |\n      | refactor | \"clean up\", \"simplify\", \"reorganize\", \"restructure\" |\n      | chore | \"update deps\", \"upgrade\", \"maintenance\", \"CI/CD\" |\n      | documentation | \"docs\", \"readme\", \"clarify\", \"examples\" |\n\n      Provide reasoning for your classification.\n    depends_on: [fetch-issue]\n    model: small\n    allowed_tools: []\n    output_format:\n      type: object\n      properties:\n        issue_type:\n          type: string\n          enum: [\"bug\", \"feature\", \"enhancement\", \"refactor\", \"chore\", \"documentation\"]\n        title:\n          type: string\n        reasoning:\n          type: string\n      required: [issue_type, title, reasoning]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 2: RESEARCH (parallel with PR template fetch)\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: web-research\n    command: archon-web-research\n    depends_on: [classify]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 3: INVESTIGATE (bugs) / PLAN (features)\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: investigate\n    command: archon-investigate-issue\n    depends_on: [classify, web-research]\n    when: \"$classify.output.issue_type == 'bug'\"\n    context: fresh\n\n  - id: plan\n    command: archon-create-plan\n    depends_on: [classify, web-research]\n    when: \"$classify.output.issue_type != 'bug'\"\n    context: fresh\n\n  # Bridge: ensure investigation.md exists for the implement step\n  # archon-fix-issue reads from $ARTIFACTS_DIR/investigation.md\n  # archon-create-plan writes to $ARTIFACTS_DIR/plan.md\n  # This node copies plan.md → investigation.md when the plan path was taken\n  - id: bridge-artifacts\n    bash: |\n      if [ -f \"$ARTIFACTS_DIR/plan.md\" ] && [ ! -f \"$ARTIFACTS_DIR/investigation.md\" ]; then\n        cp \"$ARTIFACTS_DIR/plan.md\" \"$ARTIFACTS_DIR/investigation.md\"\n        echo \"Bridged plan.md to investigation.md for implement step\"\n      elif [ -f \"$ARTIFACTS_DIR/investigation.md\" ]; then\n        echo \"investigation.md exists from investigate step\"\n      else\n        # Fail, do not warn. investigate/plan can \"succeed\" while producing no\n        # artifact — an AI node that declines the task still exits 0, so the\n        # refusal reads downstream as a completed investigation. This node holds\n        # the only cheap deterministic view of that precondition, so it is where\n        # the run has to stop, before implement spends a model on nothing.\n        echo \"bridge-artifacts: neither investigation.md nor plan.md exists in \\$ARTIFACTS_DIR.\" >&2\n        echo \"The investigate/plan phase produced no specification — implement has nothing to work from.\" >&2\n        exit 1\n      fi\n    depends_on: [investigate, plan]\n    trigger_rule: one_success\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 4: IMPLEMENT\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: implement\n    command: archon-fix-issue\n    depends_on: [bridge-artifacts]\n    context: fresh\n    model: large\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 5: VALIDATE\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: validate\n    command: archon-validate\n    depends_on: [implement]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 6: CREATE DRAFT PR\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: create-pr\n    prompt: |\n      Create a draft pull request for the current branch.\n\n      ## Context\n\n      - **Issue**: $ARGUMENTS\n      - **Classification**: $classify.output\n      - **Issue title**: $classify.output.title\n\n      ## Instructions\n\n      1. Check git status. If uncommitted changes exist, stage and commit ONLY source files that are part of the fix:\n         - List them by name with `git add <path1> <path2> ...` — never `git add -A`, `git add .`, or `git add -u`\n         - **Never commit** scratch / review / PR-body artifacts, even if they appear in `git status`:\n           - `.pr-body.md`, `pr-body.md`, `*.scratch.md`, `*.tmp.md` at any path\n           - `review/`, `*-report.md` at the repo root\n           - Anything under `$ARTIFACTS_DIR`\n           - Repo-local Archon telemetry: `.archon/artifacts/`, `.archon/logs/`, `.archon/state/` (local-only — never in git)\n         - Verify with `git status --porcelain` that nothing scratch is staged before committing\n         - If files you don't recognize as part of the fix appear modified or untracked, leave them alone\n      2. Push the branch: `git push -u origin HEAD`\n      3. Read implementation artifacts from `$ARTIFACTS_DIR/` for context:\n         - `$ARTIFACTS_DIR/investigation.md` or `$ARTIFACTS_DIR/plan.md`\n         - `$ARTIFACTS_DIR/implementation.md`\n         - `$ARTIFACTS_DIR/validation.md`\n      4. Resolve the origin repo — in a fork clone, gh otherwise targets the upstream parent:\n         `ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')`\n         Then check if a PR already exists for this branch: `gh pr list --repo \"$ORIGIN_REPO\" --head $(git branch --show-current)`\n         - If PR exists, skip creation and capture its number\n      5. Look for the project's PR template at `.github/pull_request_template.md`, `.github/PULL_REQUEST_TEMPLATE.md`, or `docs/PULL_REQUEST_TEMPLATE.md`. Read whichever one exists.\n      6. Create a DRAFT PR: `gh pr create --repo \"$ORIGIN_REPO\" --draft --base $BASE_BRANCH`\n         - Title: concise, imperative mood, under 70 chars\n         - Body: if a PR template was found, fill in **every section** with details from the artifacts. Don't skip sections or leave placeholders. If no template, write a body with summary, changes, validation evidence, and `Fixes #...`.\n         - **PR body file location**: if you write the body to a file (e.g. for `--body-file`), the file MUST live at `$ARTIFACTS_DIR/pr-body.md` or under `/tmp/` — NEVER inside the worktree. Files like `.pr-body.md` at the repo root will be picked up by later commits.\n         - Link to issue: include `Fixes #...` or `Closes #...`\n      7. Capture PR identifiers:\n         ```bash\n         ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')\n         HEAD_BRANCH=$(git branch --show-current)\n         PR_NUMBER=$(gh pr list --repo \"$ORIGIN_REPO\" --head \"$HEAD_BRANCH\" --state open --json number -q '.[0].number')\n         if [ -z \"$PR_NUMBER\" ]; then\n           echo \"No open PR found for branch $HEAD_BRANCH — PR creation failed\" >&2\n           exit 1\n         fi\n         echo \"$PR_NUMBER\" > \"$ARTIFACTS_DIR/.pr-number\"\n         PR_URL=$(gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json url -q '.url')\n         echo \"$PR_URL\" > \"$ARTIFACTS_DIR/.pr-url\"\n         ```\n    depends_on: [validate]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 7: REVIEW\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: verify-pr-base\n    bash: |\n      set -euo pipefail\n      # Pin to the origin remote — in a fork clone, gh otherwise queries the upstream parent\n      ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')\n      HEAD_BRANCH=$(git rev-parse --abbrev-ref HEAD)\n      PR_NUMBER=$(gh pr list --repo \"$ORIGIN_REPO\" --head \"$HEAD_BRANCH\" --state open --json number -q '.[0].number')\n      if [ -z \"$PR_NUMBER\" ]; then\n        echo \"No open PR found for branch $HEAD_BRANCH\" >&2\n        exit 1\n      fi\n      EXPECTED=\"$BASE_BRANCH\"\n      ACTUAL=$(gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json baseRefName -q '.baseRefName')\n      if [ \"$ACTUAL\" != \"$EXPECTED\" ]; then\n        echo \"Base mismatch on PR #$PR_NUMBER: expected=$EXPECTED actual=$ACTUAL — re-targeting\" >&2\n        gh pr edit \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --base \"$EXPECTED\"\n      else\n        echo \"PR base verified: $EXPECTED\"\n      fi\n    depends_on: [create-pr]\n\n  - id: review-scope\n    command: archon-pr-review-scope\n    depends_on: [verify-pr-base]\n    context: fresh\n\n  - id: review-classify\n    prompt: |\n      You are a PR review classifier. Analyze the PR scope and determine\n      which review agents should run.\n\n      ## PR Scope\n\n      $review-scope.output\n\n      ## Rules\n\n      - **Code review**: ALWAYS run. This is mandatory for every PR. It also checks\n        the PR against CLAUDE.md rules and project conventions.\n      - **Error handling**: Run if the diff touches code with try/catch, error handling,\n        async/await, or adds new failure paths.\n      - **Test coverage**: Run if the diff touches source code (not just tests, docs, or config).\n      - **Comment quality**: Run if the diff adds or modifies comments, docstrings, JSDoc,\n        or significant documentation within code files.\n      - **Docs impact**: Run if the diff adds/removes/renames public APIs, commands, CLI flags,\n        environment variables, or user-facing features.\n\n      Provide your reasoning for each decision.\n    depends_on: [review-scope]\n    model: small\n    allowed_tools: []\n    context: fresh\n    output_format:\n      type: object\n      properties:\n        run_code_review:\n          type: string\n          enum: [\"true\", \"false\"]\n        run_error_handling:\n          type: string\n          enum: [\"true\", \"false\"]\n        run_test_coverage:\n          type: string\n          enum: [\"true\", \"false\"]\n        run_comment_quality:\n          type: string\n          enum: [\"true\", \"false\"]\n        run_docs_impact:\n          type: string\n          enum: [\"true\", \"false\"]\n        reasoning:\n          type: string\n      required:\n        - run_code_review\n        - run_error_handling\n        - run_test_coverage\n        - run_comment_quality\n        - run_docs_impact\n        - reasoning\n\n  # Code review always runs — mandatory\n  - id: code-review\n    command: archon-code-review-agent\n    depends_on: [review-classify]\n    context: fresh\n\n  - id: error-handling\n    command: archon-error-handling-agent\n    depends_on: [review-classify]\n    when: \"$review-classify.output.run_error_handling == 'true'\"\n    context: fresh\n\n  - id: test-coverage\n    command: archon-test-coverage-agent\n    depends_on: [review-classify]\n    when: \"$review-classify.output.run_test_coverage == 'true'\"\n    context: fresh\n\n  - id: comment-quality\n    command: archon-comment-quality-agent\n    depends_on: [review-classify]\n    when: \"$review-classify.output.run_comment_quality == 'true'\"\n    context: fresh\n\n  - id: docs-impact\n    command: archon-docs-impact-agent\n    depends_on: [review-classify]\n    when: \"$review-classify.output.run_docs_impact == 'true'\"\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 8: SYNTHESIZE + SELF-FIX\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: synthesize\n    command: archon-synthesize-review\n    depends_on: [code-review, error-handling, test-coverage, comment-quality, docs-impact]\n    trigger_rule: one_success\n    context: fresh\n\n  - id: self-fix\n    command: archon-self-fix-all\n    depends_on: [synthesize]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 9: SIMPLIFY\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: simplify\n    command: archon-simplify-changes\n    depends_on: [self-fix]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 10: REPORT\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: report\n    command: archon-issue-completion-report\n    depends_on: [simplify]\n    context: fresh\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-idea-to-pr": "name: archon-idea-to-pr\ndescription: |\n  Use when: You have a feature idea or description and want end-to-end development.\n  Input: Feature description in natural language, or path to a PRD file\n  Output: PR ready for merge with comprehensive review completed\n\n  Full workflow:\n  1. Create comprehensive implementation plan with codebase analysis\n  2. Setup branch and extract scope limits\n  3. Verify plan research is still valid\n  4. Implement all tasks with type-checking\n  5. Run full validation suite\n  6. Create PR with template, mark ready\n  7. Comprehensive code review (5 parallel agents with scope limit awareness)\n  8. Synthesize and fix review findings\n  9. Final summary with decision matrix -> GitHub comment + follow-up recommendations\n\n  NOT for: Executing existing plans (use archon-plan-to-pr), quick fixes, standalone reviews.\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 0: CREATE PLAN\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: create-plan\n    command: archon-create-plan\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 1: SETUP\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: plan-setup\n    command: archon-plan-setup\n    depends_on: [create-plan]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 2: CONFIRM PLAN\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: confirm-plan\n    command: archon-confirm-plan\n    depends_on: [plan-setup]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 3: IMPLEMENT\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: implement-tasks\n    command: archon-implement-tasks\n    depends_on: [confirm-plan]\n    context: fresh\n    provider: claude\n    model: large\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 4: VALIDATE\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: validate\n    command: archon-validate\n    depends_on: [implement-tasks]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 5: FINALIZE PR\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: finalize-pr\n    command: archon-finalize-pr\n    depends_on: [validate]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 6-7: CODE REVIEW + FIX (shared building block)\n  # Inlines archon-review-block: verify-pr-base -> review-scope -> sync ->\n  # 5 parallel review agents -> synthesize -> implement-fixes.\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: review\n    include: archon-review-block\n    depends_on: [finalize-pr]\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 8: FINAL SUMMARY & FOLLOW-UP\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: workflow-summary\n    command: archon-workflow-summary\n    depends_on: [review]\n    context: fresh\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-implement": "name: archon-implement\ndescription: |\n  Implement a change and keep working until it is complete and the project's own\n  checks pass. Commits as it goes; opens no PR. The input is anything intent-shaped:\n  a plan (path or inline), review findings, a CI failure to fix, or a plain\n  description of what to build.\n\n  Use when: the work is already decided and needs building — \"implement this plan\",\n  \"apply these review findings\", \"build what this describes\", \"fix this CI failure\".\n  NOT for: deciding what to build, reviewing changes, or opening a PR.\n\nmodel: large\n\ninputs:\n  work:\n    default: \"\"\n    description: >-\n      What to implement — a plan path, review findings, a CI failure, or a plain\n      description. When empty, the run's trigger message is the work.\n\nreturns: implement\noutcome_field: green\n\nnodes:\n  - id: record-start\n    bash: |\n      # The anchor assert-changed measures against: proves work happened THIS run,\n      # independent of how far the branch was already ahead when the run started.\n      # Chained with && so a failed write fails the node instead of echoing success\n      # (a bash line's failure does not abort the script without set -e).\n      mkdir -p \"$ARTIFACTS_DIR\" &&\n        git rev-parse HEAD > \"$ARTIFACTS_DIR/.start-sha\" &&\n        echo '{\"start\":\"recorded\"}'\n\n  # Run success ≠ green. The loop completes on `done`, which deliberately includes\n  # a definitive blocked decline (green: false) — so a completed run's status never\n  # certifies the work. Consumers read $implement.output.green; compositions gate on\n  # it deterministically before spending or shipping (deliver does), and the\n  # workflow's outcome_field records it as the run's authored outcome.\n  - id: implement\n    loop:\n      command: implement\n      until_field: done\n      max_iterations: 5\n    depends_on: [record-start]\n    output_type: implementation\n    output_format:\n      type: object\n      properties:\n        done:\n          type: boolean\n        green:\n          type: boolean\n        # Why the checks are red, when they are. A green turn has no red to\n        # explain, and the empty string is how it says so: OpenAI strict mode rejects\n        # any schema whose `required` omits a declared property, so optionality has to\n        # live inside the type rather than in what `required` leaves out: every\n        # archon-deliver run on a Codex config died at the first turn while this\n        # was optional by omission. '' is the value gate-green.py already treats as\n        # no cause declared, so the gate that spends on this verdict is unchanged.\n        red_cause:\n          type: string\n          enum: [introduced, inherited, environment, \"\"]\n        summary:\n          type: string\n      required: [done, green, red_cause, summary]\n\n  # Decline is not success: an AI node that declines its task still exits 0. This\n  # deterministic guard proves work actually happened before anything downstream\n  # spends money or goes public — see scripts/assert-changed.py. The whole verdict\n  # arrives as bound inputs, no artifact bridge: green, the declared cause of any\n  # red, and the summary carrying the evidence for it. The guard needs all three,\n  # because an iteration whose remaining red is inherited or environmental can\n  # honestly have nothing left to change.\n  - id: assert-changed\n    script: assert-changed\n    runtime: uv\n    depends_on: [implement]\n    with:\n      green: \"$implement.output.green\"\n      red_cause: \"$implement.output.red_cause\"\n      summary: \"$implement.output.summary\"\n",
  "archon-interactive-prd": "name: archon-interactive-prd\ndescription: |\n  Use when: User wants to create a PRD through guided conversation.\n  Triggers: \"create a prd\", \"new prd\", \"interactive prd\", \"plan a feature\",\n            \"product requirements\", \"write a prd\".\n  NOT for: Autonomous PRD generation without human input (use archon-ralph-generate).\n\n  Interactive workflow that guides the user through problem-first PRD creation:\n  1. Understand the idea → ask foundation questions → wait for answers\n  2. Research market & codebase → ask deep dive questions → wait for answers\n  3. Assess technical feasibility → ask scope questions → wait for answers\n  4. Generate PRD → validate technical claims against codebase → output\n\nprovider: claude\ninteractive: true\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 1: INITIATE — Understand the idea\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: initiate\n    model: medium\n    prompt: |\n      You are a sharp product manager starting a PRD creation process.\n      You think from first principles — start with primitives, not features.\n\n      The user wants to build: $ARGUMENTS\n\n      If the input is clear, restate your understanding in 2-3 sentences and confirm:\n      \"I understand you want to build: {restated understanding}. Is this correct?\"\n\n      If the input is vague or empty, ask:\n      \"What do you want to build? Describe the product, feature, or capability.\"\n\n      Then present the Foundation Questions (all at once — the user will answer in the next step):\n\n      **Foundation Questions:**\n\n      1. **Who** has this problem? Be specific — not just \"users\" but what type of person/role?\n      2. **What** problem are they facing? Describe the observable pain, not the assumed need.\n      3. **Why** can't they solve it today? What alternatives exist and why do they fail?\n      4. **Why now?** What changed that makes this worth building?\n      5. **How** will you know if you solved it? What would success look like?\n\n      Keep it conversational. Don't generate any PRD content yet.\n\n  # ═══════════════════════════════════════════════════════════════\n  # GATE 1: User answers foundation questions\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: foundation-gate\n    approval:\n      message: \"Answer the foundation questions above. Your answers will guide the research phase.\"\n      capture_response: true\n    depends_on: [initiate]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 2: GROUNDING — Research market & codebase\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: research\n    model: medium\n    prompt: |\n      You are researching context for a PRD. Think from first principles —\n      what already exists before proposing anything new.\n\n      **The idea**: $ARGUMENTS\n\n      **User's foundation answers**:\n      $foundation-gate.output\n\n      Research the landscape:\n\n      1. Search the web for similar products, competitors, and how others solve this problem\n      2. **Explore the codebase deeply** — find related existing functionality, APIs, UI components,\n         database tables, and patterns. Read actual files, don't assume. Note exact file paths and\n         what each file does.\n      3. Look for common patterns, anti-patterns, and recent trends\n\n      **First principles rule**: Before suggesting anything new, verify what already exists.\n      If there's an existing API endpoint, UI page, or component that partially solves the\n      problem, note it explicitly. The best solution extends what exists, not replaces it.\n\n      Present a summary to the user:\n\n      **What I found:**\n      - {Market insights — similar products, competitor approaches}\n      - {What already exists in the codebase — specific files, endpoints, components}\n      - {Key insight that might change the approach}\n\n      Then ask the **Deep Dive Questions**:\n\n      1. **Vision**: In one sentence, what's the ideal end state if this succeeds wildly?\n      2. **Primary User**: Describe your most important user — their role, context, and what triggers their need.\n      3. **Job to Be Done**: Complete this: \"When [situation], I want to [motivation], so I can [outcome].\"\n      4. **Non-Users**: Who is explicitly NOT the target?\n      5. **Constraints**: What limitations exist? (time, budget, technical, regulatory)\n\n      Does the research change or refine your thinking? Answer the deep dive questions.\n    depends_on: [foundation-gate]\n\n  # ═══════════════════════════════════════════════════════════════\n  # GATE 2: User answers deep dive questions\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: deepdive-gate\n    approval:\n      message: \"Answer the deep dive questions above (vision, primary user, JTBD, constraints). Add any adjustments from the research.\"\n      capture_response: true\n    depends_on: [research]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 3: TECHNICAL GROUNDING — Feasibility from what exists\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: technical\n    model: medium\n    prompt: |\n      You are assessing technical feasibility for a PRD.\n      Think from first principles — start with what exists, not what you'd build from scratch.\n\n      **The idea**: $ARGUMENTS\n      **Foundation answers**: $foundation-gate.output\n      **Deep dive answers**: $deepdive-gate.output\n\n      **CRITICAL**: Explore the codebase by READING actual files. Do not guess or assume.\n      For every claim you make about the codebase, cite the exact file and line.\n\n      1. **What already exists** that partially solves this problem?\n         - Read existing API endpoints, DB queries, UI components\n         - Note exact function names, table schemas, component names\n         - What data is already being collected/stored?\n      2. **What's the smallest change** to the existing system that solves the core problem?\n         - Prefer extending existing files over creating new ones\n         - Prefer using existing endpoints over creating new ones\n         - Prefer adding to existing UI pages over new pages\n      3. **What are the actual primitives** we need?\n         - A new DB query? An existing one that needs a parameter?\n         - A new component? Or an existing component that needs a prop?\n         - A new endpoint? Or an existing endpoint that already returns the data?\n      4. **What's the risk?**\n         - Where could this go wrong?\n         - What assumptions need validation?\n\n      Present a summary:\n\n      **What Already Exists (verified by reading code):**\n      - {endpoint/component/query} at `{file:line}` — {what it does}\n      - {endpoint/component/query} at `{file:line}` — {what it does}\n\n      **Smallest Change to Solve the Problem:**\n      - {change 1}: {extend/modify} `{file}` — {what to do}\n      - {change 2}: {extend/modify} `{file}` — {what to do}\n\n      **Technical Context:**\n      - Feasibility: {HIGH/MEDIUM/LOW} because {reason}\n      - Key risk: {main concern}\n      - Estimated phases: {rough breakdown}\n\n      Then ask the **Scope Questions**:\n\n      1. **MVP Definition**: What's the absolute minimum to test if this works?\n      2. **Must Have vs Nice to Have**: What 2-3 things MUST be in v1? What can wait?\n      3. **Key Hypothesis**: Complete this: \"We believe [capability] will [solve problem] for [users]. We'll know we're right when [measurable outcome].\"\n      4. **Out of Scope**: What are you explicitly NOT building?\n      5. **Open Questions**: What uncertainties could change the approach?\n    depends_on: [deepdive-gate]\n\n  # ═══════════════════════════════════════════════════════════════\n  # GATE 3: User answers scope questions\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: scope-gate\n    approval:\n      message: \"Answer the scope questions above (MVP, must-haves, hypothesis, exclusions). This is the final input before PRD generation.\"\n      capture_response: true\n    depends_on: [technical]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 4: GENERATE — Write the PRD\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: generate\n    model: medium\n    prompt: |\n      You are generating a PRD from the user's guided inputs.\n\n      **The idea**: $ARGUMENTS\n      **Foundation answers**: $foundation-gate.output\n      **Deep dive answers**: $deepdive-gate.output\n      **Scope answers**: $scope-gate.output\n\n      Generate a complete PRD file at `$ARTIFACTS_DIR/prds/{kebab-case-name}.prd.md`.\n\n      First create the directory:\n      ```bash\n      mkdir -p $ARTIFACTS_DIR/prds\n      ```\n\n      **First principles rule**: Before writing the Technical Approach section, READ the\n      actual codebase files you're referencing. Verify:\n      - File paths exist\n      - Function/component names are correct\n      - API endpoints you reference actually exist (or note they need to be created)\n      - DB table and column names match the schema\n      - Event type names match the constants in the code\n\n      The PRD must include ALL of these sections, filled from the user's answers:\n\n      1. **Problem Statement** — from foundation answers (who/what/why)\n      2. **Evidence** — from research findings and user's evidence\n      3. **Proposed Solution** — synthesized from all inputs. Prefer extending existing\n         primitives over creating new ones.\n      4. **Key Hypothesis** — from scope answers\n      5. **What We're NOT Building** — from scope answers\n      6. **Success Metrics** — from foundation \"how will you know\" + scope\n      7. **Open Questions** — from scope answers\n      8. **Users & Context** — from deep dive (primary user, JTBD, non-users)\n      9. **Solution Detail** — MoSCoW table from scope must-haves, MVP definition\n      10. **Technical Approach** — from technical feasibility. MUST reference actual\n          verified file paths, function names, and schemas. Mark anything unverified\n          as \"needs verification\".\n      11. **Implementation Phases** — from technical breakdown, with status table\n          and parallel opportunities\n      12. **Decisions Log** — key decisions made during the conversation\n\n      **Rules:**\n      - If info is missing, write \"TBD — needs research\" not filler\n      - Be specific and concrete, not generic\n      - Every file path in Technical Approach must be verified by reading the file\n      - Prefer \"extend X\" over \"create new Y\" in implementation phases\n\n      After writing the file, output the file path only — the validator will check it.\n    depends_on: [scope-gate]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 5: VALIDATE — Check technical claims against codebase\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: validate\n    model: medium\n    prompt: |\n      You are a technical validator checking a PRD for accuracy.\n\n      Read the PRD file that was just generated. The generate node output the file path:\n      $generate.output\n\n      Find the PRD file — check `$ARTIFACTS_DIR/prds/` for the most recently created `.prd.md` file:\n      ```bash\n      ls -t $ARTIFACTS_DIR/prds/*.prd.md | head -1\n      ```\n\n      Read the entire PRD, then verify EVERY technical claim against the actual codebase:\n\n      **Check 1: File paths** — For every file referenced in \"Technical Approach\" and\n      \"Implementation Phases\", verify it exists. If it doesn't, note the correction.\n\n      **Check 2: API endpoints** — For every endpoint mentioned, check if it already exists\n      in `packages/server/src/routes/api.ts`. If it does, the PRD should say \"extend\" not \"create\".\n      If the PRD proposes a new endpoint for data that an existing endpoint already returns,\n      flag it.\n\n      **Check 3: DB schemas** — For every table/column referenced, verify the actual names\n      in the migration files or schema code. Check event type names against the\n      `WORKFLOW_EVENT_TYPES` constant.\n\n      **Check 4: UI components** — For every component referenced, verify it exists.\n      If the PRD proposes a new page but an existing page already serves a similar purpose,\n      flag it.\n\n      **Check 5: Function/type names** — Verify function names, type names, and interface\n      names are correct.\n\n      After checking, if there are ANY corrections needed:\n      1. Edit the PRD file directly — fix incorrect names, paths, and references\n      2. Add a `## Validation Notes` section at the bottom documenting what was corrected\n\n      If everything checks out, add:\n      ```\n      ## Validation Notes\n\n      All technical references verified against codebase. No corrections needed.\n      ```\n\n      Output a summary of what was checked and corrected:\n\n      ```\n      ## PRD Validated\n\n      **File**: `{prd-path}`\n      **Checks**: {N} file paths, {N} endpoints, {N} DB references, {N} components\n      **Corrections**: {count}\n      {list corrections if any}\n\n      To start implementation: `/prp-plan {prd-path}`\n      ```\n    depends_on: [generate]\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-investigate": "name: archon-investigate\ndescription: |\n  Establish the proven causal chain for a bug, unexplained behavior, or open\n  question — to the root cause whose fix prevents the symptom, never the first\n  plausible explanation — and write an evidence-backed report a fixer or\n  planner can act on without repeating the work. Advisory: it reads,\n  reproduces, and reports — the repository is left exactly as it was found.\n\n  Use when: the cause is not yet known — \"investigate this issue\", \"why does\n  this fail\", \"root-cause this before we fix it\".\n  NOT for: deciding how to build the fix (plan), or building it (implement).\n\nmodel: medium\n\ninputs:\n  target:\n    default: \"\"\n    description: >-\n      What to investigate — an issue reference, a symptom, a failing command, or\n      a question. When empty, the run's trigger message is the target.\n\n# rooted:false is a valid completion (see the investigate node): the run succeeds\n# with an authored outcome of false — lifecycle status and work outcome are separate facts.\nreturns: investigate\noutcome_field: rooted\n\nnodes:\n\n  # Inconclusive is a valid outcome, not a failure: rooted:false with the gaps\n  # named honestly beats a confident guess. Consumers gate on\n  # $investigate.output.rooted before building on the chain.\n  - id: investigate\n    command: investigate\n    # Advisory: the engine fails this node with the touched paths named if it\n    # modifies the working tree; replaced the record-state snapshot.\n    mutates_checkout: false\n    output_type: investigation-report\n    output_format:\n      type: object\n      properties:\n        rooted:\n          type: boolean\n        summary:\n          type: string\n      required: [rooted, summary]\n\n  # Deterministic on both promises: a pleasant summary is not a report, and an\n  # advisory run must not mutate the checkout (advisory agents resetting user\n  # work is a lived failure mode, not a hypothetical).\n  - id: assert-intact\n    bash: |\n      # Tree-intactness is engine-enforced via mutates_checkout: false above;\n      # what remains is the evidence contract.\n      if [ ! -s \"$ARTIFACTS_DIR/investigation.md\" ]; then\n        echo \"assert-intact: the run completed but wrote no investigation.md — a summary is not a report.\" >&2\n        exit 1\n      fi\n      echo '{\"intact\":\"true\"}'\n    depends_on: [investigate]\n",
  "archon-issue-review-full": "name: archon-issue-review-full\ndescription: |\n  Use when: User wants a FULL, COMPREHENSIVE fix + review pipeline for a GitHub issue.\n  Triggers: \"full review\", \"comprehensive fix\", \"fix with full review\", \"deep review\", \"issue review full\".\n  NOT for: Simple issue fixes (use archon-fix-github-issue instead),\n           questions about issues, CI failures, PR reviews, general exploration.\n\n  Full workflow:\n  1. Investigate issue -> root cause analysis, implementation plan\n  2. Implement fix -> code changes, tests, PR creation\n  3. Comprehensive review -> 5 parallel agents with scope awareness\n  4. Fix review issues -> address CRITICAL/HIGH findings\n  5. Final summary -> decision matrix, follow-up recommendations\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 1: INVESTIGATE\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: investigate\n    command: archon-investigate-issue\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 2: IMPLEMENT\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: implement\n    command: archon-implement-issue\n    depends_on: [investigate]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 3-4: CODE REVIEW + FIX (shared building block)\n  # Inlines archon-review-block: verify-pr-base -> review-scope -> sync ->\n  # 5 parallel review agents -> synthesize -> implement-fixes.\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: review\n    include: archon-review-block\n    depends_on: [implement]\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 5: FINAL SUMMARY\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: summary\n    command: archon-workflow-summary\n    depends_on: [review]\n    context: fresh\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-piv-loop": "name: archon-piv-loop\ndescription: |\n  Use when: User wants guided Plan-Implement-Validate development with human-in-the-loop.\n  Triggers: \"piv\", \"piv loop\", \"plan implement validate\", \"guided development\",\n            \"structured development\", \"build a feature\", \"develop with review\".\n  NOT for: Autonomous implementation without planning (use archon-feature-development).\n  NOT for: PRD creation (use archon-interactive-prd).\n  NOT for: Ralph story-based implementation (use archon-ralph-dag).\n\n  Interactive PIV loop workflow — the foundational AI coding methodology:\n  1. EXPLORE: Iterative conversation with human to understand the problem (arbitrary rounds)\n  2. PLAN: Create structured plan -> iterative review & revision (arbitrary rounds)\n  3. IMPLEMENT: Autonomous task-by-task implementation from plan (Ralph loop)\n  4. VALIDATE: Automated code review -> iterative human feedback & fixes (arbitrary rounds)\n\n  The PIV loop comes AFTER a PRD exists. Each PIV loop focuses on ONE granular feature or bug fix.\n  Input: A description of what to build, a path to an existing plan, or a GitHub issue number.\n\nprovider: claude\ninteractive: true\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 1: EXPLORE — Iterative exploration with human\n  # Understand the idea, explore the codebase, converge on approach\n  # Loops until the user says they're ready to create the plan.\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: explore\n    loop:\n      prompt: |\n        # PIV Loop — Exploration\n\n        You are a senior engineering partner in an iterative exploration session.\n        Your goal: DEEPLY UNDERSTAND what to build before any code is written.\n\n        **User's request**: $ARGUMENTS\n        **User's latest input**: $LOOP_USER_INPUT\n\n        ---\n\n        ## If this is the FIRST iteration (no user input yet):\n\n        ### Step 1: Parse the Input\n\n        Determine what the user provided:\n\n        **If it's a file path** (ends in `.md`, `.plan.md`, or `.prd.md`):\n        - Read the file\n        - If it's an existing plan → summarize it and ask if they want to refine or proceed\n        - If it's a PRD → identify the specific phase/feature to focus on\n\n        **If it's a GitHub issue** (`#123` format):\n        - Fetch it: `gh issue view {number} --json title,body,labels,comments`\n        - Summarize the issue context\n\n        **If it's free text**:\n        - This is a feature idea or bug description. Use it directly.\n\n        ### Step 2: Explore the Codebase\n\n        Before asking questions, DO YOUR HOMEWORK:\n\n        1. **Read CLAUDE.md** — understand project conventions, architecture, and constraints\n        2. **Search for related code** — find existing implementations similar to what the user wants\n        3. **Read key files** — understand the current state of code the user wants to change\n        4. **Check recent git history** — `git log --oneline -20` for recent changes in the area\n\n        ### Step 3: Present Your Understanding\n\n        ```\n        ## What I Understand\n\n        You want to: {restated understanding in 2-3 sentences}\n\n        ## What Already Exists\n\n        - {file:line} — {what it does and how it relates}\n        - {file:line} — {what it does and how it relates}\n        - {pattern/component} — {how it could be extended or reused}\n\n        ## Initial Architecture Thoughts\n\n        Based on what exists, I'm thinking:\n        - {approach 1 — extend existing X}\n        - {approach 2 — if approach 1 doesn't work}\n        - {key architectural decision that needs your input}\n        ```\n\n        ### Step 4: Ask Targeted Questions\n\n        Ask 4-6 questions focused on DECISIONS, not information gathering:\n        - Scope boundaries, architecture preferences, tech decisions\n        - Constraints, existing code extension vs fresh build, testing expectations\n        - Reference actual code you found — don't ask generic questions\n\n        ---\n\n        ## If the user has provided input (subsequent iterations):\n\n        ### Step 1: Process Their Response\n\n        Read their answers carefully. Identify:\n        - Decisions they've made\n        - Areas they want you to explore further\n        - Questions they asked YOU back (answer these with evidence!)\n\n        ### Step 2: Do Targeted Research\n\n        Based on their response:\n        - If they mentioned specific technologies → research best practices\n        - If they pointed you to specific code → read it thoroughly\n        - If they asked you to explore an area → do a thorough investigation\n        - If they made architecture decisions → validate against the codebase\n\n        ### Step 3: Present Updated Understanding\n\n        Show what you learned, answer their questions with file:line references,\n        and present your refined architecture recommendation.\n\n        ### Step 4: Converge or Continue\n\n        **If there are still important open questions:**\n        Ask 2-4 focused questions about remaining ambiguities.\n\n        **If the picture is clear and you have enough to create a plan:**\n        Present a final implementation summary:\n\n        ```\n        ## Implementation Summary\n\n        ### What We're Building\n        {Clear, specific description}\n\n        ### Scope Boundary\n        - IN: {what's included}\n        - OUT: {what's explicitly excluded}\n\n        ### Architecture\n        - {key decisions}\n\n        ### Files That Will Change\n        - `{file}` — {what changes and why}\n\n        ### Success Criteria\n        - [ ] {specific, testable criterion}\n        - [ ] All validation passes\n\n        ### Key Risks\n        - {risk — and mitigation}\n        ```\n\n        Then tell the user: \"I have a clear picture. Say **ready** and I'll create\n        the structured implementation plan, or share any final thoughts.\"\n\n        **CRITICAL — READ THIS CAREFULLY**:\n        - NEVER output <promise>PLAN_READY</promise> unless the user's LATEST message contains\n          an EXPLICIT phrase like \"ready\", \"create the plan\", \"let's go\", \"proceed\", or \"I'm done\".\n        - If the user asked a question → do NOT emit the signal. Answer the question.\n        - If the user gave feedback or requested changes → do NOT emit the signal. Address it.\n        - If the user said \"also check X\" or \"one more thing\" → do NOT emit the signal. Explore it.\n        - If you are unsure whether the user is approving → do NOT emit the signal. Ask them.\n        - The ONLY correct time to emit the signal is when the user's message CLEARLY means\n          \"stop exploring, I'm ready for you to create the plan.\"\n      until: PLAN_READY\n      max_iterations: 15\n      interactive: true\n      gate_message: |\n        Answer the questions above, ask me to explore specific areas,\n        or say \"ready\" when you're satisfied with the exploration.\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 2: PLAN — Create the structured implementation plan\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: create-plan\n    model: medium\n    depends_on: [explore]\n    context: fresh\n    prompt: |\n      # PIV Loop — Create Structured Plan\n\n      You are creating a structured implementation plan from a completed exploration phase.\n      This plan will be the SOLE GUIDE for the implementation agent — it must be complete,\n      specific, and actionable.\n\n      **Original request**: $ARGUMENTS\n      **Final exploration summary**: $explore.output\n\n      ---\n\n      ## Step 1: Read the Codebase (Again)\n\n      Before writing the plan, verify your understanding is current:\n\n      1. **Read CLAUDE.md** — capture all relevant conventions\n      2. **Read every file you plan to change** — note exact current state\n      3. **Read example test files** — understand testing patterns\n      4. **Check for any recent changes** — `git log --oneline -10`\n\n      ## Step 2: Plan File Location\n\n      Save the plan to `$ARTIFACTS_DIR/plan.md`.\n      The directory already exists (pre-created by the workflow executor).\n\n      ## Step 3: Write the Plan\n\n      Use this template. Fill EVERY section with specific, verified information.\n\n      ```markdown\n      # Feature: {Title}\n\n      ## Summary\n      {1-2 sentences: what changes and why}\n\n      ## Mission\n      {The core goal in one clear statement}\n\n      ## Success Criteria\n      - [ ] {Specific, testable criterion}\n      - [ ] All validation passes (`bun run validate` or equivalent)\n      - [ ] No regressions in existing tests\n\n      ## Scope\n      ### In Scope\n      - {What we ARE building}\n      ### Out of Scope\n      - {What we are NOT building — and why}\n\n      ## Codebase Context\n      ### Key Files\n      | File | Role | Action |\n      |------|------|--------|\n      | `{path}` | {what it does} | CREATE / UPDATE |\n\n      ### Patterns to Follow\n      {Actual code snippets from the codebase to mirror}\n\n      ## Architecture\n      - {Decision 1 — with rationale}\n      - {Decision 2 — with rationale}\n\n      ## Task List\n      Execute in order. Each task is atomic and independently verifiable.\n\n      ### Task 1: {ACTION} `{file path}`\n      **Action**: CREATE / UPDATE\n      **Details**: {Exact changes — specific enough for an agent with no context}\n      **Pattern**: Follow `{source file}:{lines}`\n      **Validate**: `{command to verify this task}`\n\n      ## Testing Strategy\n      | Test File | Test Cases | Validates |\n      |-----------|-----------|-----------|\n      | `{path}` | {cases} | {what it validates} |\n\n      ## Validation Commands\n      1. Type check: `{command}`\n      2. Lint: `{command}`\n      3. Tests: `{command}`\n      4. Full validation: `{command}`\n\n      ## Risks\n      | Risk | Impact | Mitigation |\n      |------|--------|------------|\n      | {risk} | {HIGH/MED/LOW} | {specific mitigation} |\n      ```\n\n      ## Step 4: Verify the Plan\n\n      1. Check every file path referenced — verify they exist\n      2. Check every pattern cited — verify the code matches\n      3. Check task ordering — ensure dependencies are respected\n      4. Check completeness — could an agent with NO context implement this?\n\n      ## Step 5: Report\n\n      ```\n      ## Plan Created\n\n      **File**: `$ARTIFACTS_DIR/plan.md`\n      **Tasks**: {count}\n      **Files to change**: {count}\n\n      Key decisions:\n      - {decision 1}\n      - {decision 2}\n\n      Please review the plan and provide feedback.\n      ```\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 2b: PLAN — Iterative plan refinement\n  # Review and revise the plan as many times as needed.\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: refine-plan\n    depends_on: [create-plan]\n    loop:\n      prompt: |\n        # PIV Loop — Plan Refinement\n\n        The user is reviewing the implementation plan and providing feedback.\n\n        **User's feedback**: $LOOP_USER_INPUT\n\n        ---\n\n        ## Step 1: Read the Plan\n\n        Read `$ARTIFACTS_DIR/plan.md` and CLAUDE.md for conventions.\n\n        ## Step 2: Process Feedback\n\n        **If there is no user feedback yet** (first iteration, $LOOP_USER_INPUT is empty):\n        - Read the plan carefully\n        - Present a summary of the plan's key decisions and task list\n        - Ask the user to review and provide feedback\n        - Do NOT emit the completion signal on the first iteration\n\n        **If the user EXPLICITLY approved** (said \"approved\", \"looks good\", \"let's go\", etc.):\n        - Make no changes\n        - Output: \"Plan approved. Proceeding to implementation.\"\n        - Signal completion: <promise>PLAN_APPROVED</promise>\n\n        **If the user provided specific feedback:**\n        - Parse each piece of feedback\n        - Edit the plan file directly:\n          - Add/remove/modify tasks as requested\n          - Update success criteria if needed\n          - Adjust testing strategy if needed\n          - Re-verify file paths and patterns after changes\n\n        **CRITICAL**: NEVER emit <promise>PLAN_APPROVED</promise> unless the user's latest\n        message EXPLICITLY says \"approved\", \"looks good\", \"ship it\", or similar approval.\n        Questions, feedback, and requests for changes are NOT approval.\n\n        ## Step 3: Show Changes\n\n        ```\n        ## Plan Revised\n\n        Changes made:\n        - {change 1}\n        - {change 2}\n\n        Updated stats:\n        - Tasks: {count}\n        - Files to change: {count}\n\n        Review the updated plan and provide more feedback, or say \"approved\" to proceed.\n        ```\n      until: PLAN_APPROVED\n      max_iterations: 10\n      interactive: true\n      gate_message: |\n        Review the plan document. Provide specific feedback on what to change,\n        or say \"approved\" to begin implementation.\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 3: IMPLEMENT — Setup\n  # Read the plan, prepare the environment\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: implement-setup\n    depends_on: [refine-plan]\n    bash: |\n      set -e\n\n      PLAN_FILE=\"$ARTIFACTS_DIR/plan.md\"\n\n      if [ ! -f \"$PLAN_FILE\" ]; then\n        echo \"ERROR: No plan file found at $ARTIFACTS_DIR/plan.md\"\n        exit 1\n      fi\n\n      # Install dependencies if needed\n      if [ -f \"bun.lock\" ] || [ -f \"bun.lockb\" ]; then\n        echo \"Installing dependencies...\"\n        bun install --frozen-lockfile 2>&1 | tail -3\n      elif [ -f \"package-lock.json\" ]; then\n        npm ci 2>&1 | tail -3\n      elif [ -f \"yarn.lock\" ]; then\n        yarn install --frozen-lockfile 2>&1 | tail -3\n      elif [ -f \"pnpm-lock.yaml\" ]; then\n        pnpm install --frozen-lockfile 2>&1 | tail -3\n      fi\n\n      echo \"BRANCH=$(git branch --show-current)\"\n      echo \"GIT_ROOT=$(git rev-parse --show-toplevel)\"\n      echo \"PLAN_FILE=$PLAN_FILE\"\n\n      echo \"=== PLAN_START ===\"\n      cat \"$PLAN_FILE\"\n      echo \"\"\n      echo \"=== PLAN_END ===\"\n\n      TASK_COUNT=$(grep -c \"^### Task [0-9]\" \"$PLAN_FILE\" 2>/dev/null || echo \"0\")\n      if [ \"$TASK_COUNT\" -eq 0 ]; then\n        echo \"ERROR: No '### Task N:' sections found in $PLAN_FILE. Plan may be malformed.\"\n        exit 1\n      fi\n      echo \"TASK_COUNT=${TASK_COUNT}\"\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 3b: IMPLEMENT — Task-by-Task Loop (Ralph pattern)\n  # Fresh context each iteration. Reads plan from disk.\n  # One task per iteration. Validates before committing.\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: implement\n    depends_on: [implement-setup]\n    idle_timeout: 600000\n    model: large\n    loop:\n      prompt: |\n        # PIV Loop — Implementation Agent\n\n        You are an autonomous coding agent in a FRESH session — no memory of previous iterations.\n        Your job: Read the plan from disk, implement ONE task, validate, commit, update tracking, exit.\n\n        **Golden Rule**: If validation fails, fix it before committing. Never commit broken code.\n\n        ---\n\n        ## Phase 0: CONTEXT — Load State\n\n        The setup node produced this context:\n\n        $implement-setup.output\n\n        **User's original request**: $USER_MESSAGE\n\n        ---\n\n        ### 0.1 Parse Plan File\n\n        Extract the `PLAN_FILE=...` line from the context above.\n\n        ### 0.2 Read Current State (from disk — not from context above)\n\n        The context above is a snapshot from before the loop started. Previous iterations\n        may have changed things. **You MUST re-read from disk:**\n\n        1. **Read the plan file** — your implementation guide\n        2. **Read progress tracking** — check if `$ARTIFACTS_DIR/progress.txt` exists\n        3. **Read CLAUDE.md** — project conventions and constraints\n\n        ### 0.3 Check Git State\n\n        ```bash\n        git log --oneline -10\n        git status\n        ```\n\n        ---\n\n        ## Phase 1: SELECT — Pick Next Task\n\n        From the plan file, identify tasks by `### Task N:` headers.\n        Cross-reference with commits from previous iterations and progress tracking.\n\n        **If ALL tasks are complete** → Skip to Phase 5 (Completion).\n\n        ### Announce Selection\n\n        ```\n        -- Task Selected ------------------------------------------------\n        Task: {N} — {task title}\n        Action: {CREATE / UPDATE}\n        File: {file path}\n        -----------------------------------------------------------------\n        ```\n\n        ---\n\n        ## Phase 2: IMPLEMENT — Execute the Task\n\n        1. Read the file you're about to change (if it exists)\n        2. Read the pattern file referenced in the plan\n        3. Make changes following the plan EXACTLY\n        4. Type-check after each file: `bun run type-check 2>&1 || true`\n\n        ---\n\n        ## Phase 3: VALIDATE — Verify the Task\n\n        ```bash\n        bun run type-check && bun run lint && bun run test && bun run format:check\n        ```\n\n        If validation fails: fix, re-run (up to 3 attempts). If unfixable, note in progress\n        tracking and do NOT commit broken code.\n\n        ---\n\n        ## Phase 4: COMMIT — Save Changes\n\n        Stage **only** the files you edited for this PIV task — never `git add -A`, `git add .`, or `git add -u`. List them by name:\n\n        ```bash\n        git add path/to/file1 path/to/file2 ...\n        git status --porcelain  # verify nothing scratch/review/PR-body is staged\n        git diff --cached --stat\n        git commit -m \"$(cat <<'EOF'\n        {type}: {task description}\n\n        PIV Task {N}: {brief details}\n        EOF\n        )\"\n        ```\n\n        **Never stage**: `.pr-body.md`, `pr-body.md`, `*.scratch.md`, `*.tmp.md`, `review/`, `*-report.md` at the repo root, anything under `$ARTIFACTS_DIR`, or repo-local `.archon/artifacts/`, `.archon/logs/`, `.archon/state/` (local-only Archon telemetry — never in git).\n\n        Track progress in `$ARTIFACTS_DIR/progress.txt`:\n        ```\n        ## Task {N}: {title} — COMPLETED\n        Date: {ISO date}\n        Files: {list}\n        Commit: {short hash}\n        ---\n        ```\n\n        ---\n\n        ## Phase 5: COMPLETE — Check All Tasks\n\n        If ALL tasks are done:\n        1. Run full validation: `bun run validate 2>&1`\n        2. Push: `git push -u origin HEAD`\n        3. Signal: `<promise>COMPLETE</promise>`\n\n        If tasks remain, report status and end normally. The loop engine starts a fresh iteration.\n      until: COMPLETE\n      max_iterations: 15\n      fresh_context: true\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 4: VALIDATE — Automated code review\n  # Review all changes against the plan\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: code-review\n    model: medium\n    depends_on: [implement]\n    context: fresh\n    prompt: |\n      # PIV Loop — Automated Code Review\n\n      The implementation phase is complete. Review ALL changes against the plan.\n\n      **Implementation output**: $implement.output\n\n      ---\n\n      ## Step 1: Read the Plan\n\n      Read `$ARTIFACTS_DIR/plan.md` to understand the intended implementation.\n\n      ## Step 2: Review All Changes\n\n      ```bash\n      git log --oneline --no-merges $(git merge-base HEAD $BASE_BRANCH)..HEAD\n      git diff $BASE_BRANCH..HEAD --stat\n      git diff $BASE_BRANCH..HEAD\n      ```\n\n      ## Step 3: Check Against Plan\n\n      For EACH task: was it implemented correctly? Do success criteria hold?\n      For EACH file: check quality, security, patterns, CLAUDE.md compliance.\n\n      ## Step 4: Run Validation\n\n      ```bash\n      bun run validate 2>&1 || (bun run type-check && bun run lint && bun run test && bun run format:check)\n      ```\n\n      ## Step 5: Fix Obvious Issues\n\n      Fix type errors, lint warnings, missing imports, formatting. Stage only the files you fixed — never `git add -A`. Skip the commit if there were no fixes:\n      ```bash\n      git add path/to/file1 path/to/file2 ...  # list real fixes only\n      git status --porcelain  # verify nothing scratch/review/PR-body is staged\n      git diff --cached --quiet || git commit -m \"fix: address code review findings\"\n      ```\n\n      **Never stage**: `.pr-body.md`, `pr-body.md`, `*.scratch.md`, `*.tmp.md`, `review/`, `*-report.md` at the repo root, anything under `$ARTIFACTS_DIR`, or repo-local `.archon/artifacts/`, `.archon/logs/`, `.archon/state/` (local-only Archon telemetry — never in git).\n\n      ## Step 6: Present Review\n\n      ```\n      ## Code Review Complete\n\n      ### Implementation Status\n      | Task | Status | Notes |\n      |------|--------|-------|\n      | {task} | DONE / PARTIAL / MISSING | {notes} |\n\n      ### Validation Results\n      - Type-check: PASS / FAIL\n      - Lint: PASS / FAIL\n      - Tests: PASS / FAIL\n      - Format: PASS / FAIL\n\n      ### Code Quality Findings\n      {Issues found, or \"No issues found.\"}\n\n      ### Recommendation\n      {READY FOR REVIEW / NEEDS FIXES}\n      ```\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 4b: VALIDATE — Iterative human feedback & fixes\n  # The user tests the implementation and provides feedback.\n  # Loops until the user approves.\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: fix-feedback\n    depends_on: [code-review]\n    loop:\n      prompt: |\n        # PIV Loop — Address Validation Feedback\n\n        The human has reviewed the implementation and provided feedback.\n\n        **Human's feedback**: $LOOP_USER_INPUT\n\n        ---\n\n        ## Step 1: Read Context\n\n        Read `$ARTIFACTS_DIR/plan.md` and CLAUDE.md for conventions.\n\n        ## Step 2: Process Feedback\n\n        **If there is no user feedback yet** (first iteration, $LOOP_USER_INPUT is empty):\n        - Present the code review results and ask the user to test the implementation\n        - Do NOT emit the completion signal on the first iteration\n\n        **If the user EXPLICITLY approved** (said \"approved\", \"looks good\", \"ship it\", etc.):\n        - Output: \"Implementation approved!\"\n        - Signal: <promise>VALIDATED</promise>\n\n        **CRITICAL**: NEVER emit <promise>VALIDATED</promise> unless the user's latest\n        message EXPLICITLY says \"approved\", \"looks good\", \"ship it\", or similar approval.\n\n        **If the user provided specific feedback:**\n        1. Read the relevant files\n        2. Understand each issue\n        3. Make the fixes\n        4. Type-check after each change\n\n        ## Step 3: Full Validation\n\n        ```bash\n        bun run validate 2>&1 || (bun run type-check && bun run lint && bun run test && bun run format:check)\n        ```\n\n        ## Step 4: Commit Fixes\n\n        Stage **only** the files you actually edited while addressing feedback — never `git add -A`. List them by name:\n\n        ```bash\n        git add path/to/file1 path/to/file2 ...\n        git status --porcelain  # verify nothing scratch/review/PR-body is staged\n        git commit -m \"$(cat <<'EOF'\n        fix: address review feedback\n\n        Changes:\n        - {fix 1}\n        - {fix 2}\n        EOF\n        )\"\n        ```\n\n        **Never stage**: `.pr-body.md`, `pr-body.md`, `*.scratch.md`, `*.tmp.md`, `review/`, `*-report.md` at the repo root, anything under `$ARTIFACTS_DIR`, or repo-local `.archon/artifacts/`, `.archon/logs/`, `.archon/state/` (local-only Archon telemetry — never in git).\n\n        ## Step 5: Report\n\n        ```\n        ## Feedback Addressed\n\n        Changes made:\n        - {fix 1}\n        - {fix 2}\n\n        Validation: {PASS / FAIL with details}\n\n        Review again, or say \"approved\" to finalize.\n        ```\n      until: VALIDATED\n      max_iterations: 10\n      interactive: true\n      gate_message: |\n        Test the implementation yourself and review the code changes.\n        Provide specific feedback on what needs fixing, or say \"approved\" to finalize.\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 5: FINALIZE — Push, create PR, generate summary\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: finalize\n    model: medium\n    depends_on: [fix-feedback]\n    context: fresh\n    prompt: |\n      # PIV Loop — Finalize\n\n      The implementation has been approved. Push changes and create a PR.\n\n      ---\n\n      ## Step 1: Push Changes\n\n      ```bash\n      git push -u origin HEAD 2>&1 || echo \"WARNING: Push failed — verify remote authentication and branch state before creating the PR.\"\n      ```\n\n      ## Step 2: Generate Summary\n\n      ```bash\n      git log --oneline --no-merges $(git merge-base HEAD $BASE_BRANCH)..HEAD\n      git diff --stat $(git merge-base HEAD $BASE_BRANCH)..HEAD\n      ```\n\n      Read `$ARTIFACTS_DIR/plan.md` and `$ARTIFACTS_DIR/progress.txt` for context.\n\n      ## Step 3: Create PR (if not already created)\n\n      Resolve the origin repo first — in a fork clone, gh otherwise targets the upstream parent:\n\n      ```bash\n      ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')\n      gh pr view HEAD --repo \"$ORIGIN_REPO\" --json url 2>/dev/null || echo \"NO_PR\"\n      ```\n\n      If no PR exists:\n\n      ```bash\n      cat .github/pull_request_template.md 2>/dev/null || echo \"NO_TEMPLATE\"\n      ```\n\n      Create with `gh pr create --repo \"$ORIGIN_REPO\" --draft --base $BASE_BRANCH`\n      (re-run the `ORIGIN_REPO=...` line in the same shell — it does not persist across shells):\n      - Title from the plan's feature name\n      - Body summarizing the implementation\n      - Use a HEREDOC for the body\n\n      ## Step 4: Output Summary\n\n      ```\n      ===============================================================\n      PIV LOOP — COMPLETE\n      ===============================================================\n\n      Feature: {from plan}\n      Plan: {plan file path}\n      Branch: {branch name}\n      PR: {url}\n\n      -- Tasks Completed -----------------------------------------------\n      {list from progress tracking}\n\n      -- Commits -------------------------------------------------------\n      {git log output}\n\n      -- Files Changed -------------------------------------------------\n      {git diff --stat output}\n\n      -- Validation ----------------------------------------------------\n      All checks passed.\n      ===============================================================\n      ```\n\n  - id: verify-pr-base\n    bash: |\n      set -euo pipefail\n      # Pin to the origin remote — in a fork clone, gh otherwise queries the upstream parent\n      ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')\n      HEAD_BRANCH=$(git rev-parse --abbrev-ref HEAD)\n      PR_NUMBER=$(gh pr list --repo \"$ORIGIN_REPO\" --head \"$HEAD_BRANCH\" --state open --json number -q '.[0].number')\n      if [ -z \"$PR_NUMBER\" ]; then\n        echo \"No open PR found for branch $HEAD_BRANCH\" >&2\n        exit 1\n      fi\n      EXPECTED=\"$BASE_BRANCH\"\n      ACTUAL=$(gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json baseRefName -q '.baseRefName')\n      if [ \"$ACTUAL\" != \"$EXPECTED\" ]; then\n        echo \"Base mismatch on PR #$PR_NUMBER: expected=$EXPECTED actual=$ACTUAL — re-targeting\" >&2\n        gh pr edit \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --base \"$EXPECTED\"\n      else\n        echo \"PR base verified: $EXPECTED\"\n      fi\n    depends_on: [finalize]\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-plan": "name: archon-plan\ndescription: |\n  Turn decided intent — a feature request, an investigation report, an idea —\n  into an implementable plan: the approach chosen with alternatives rejected for\n  stated reasons, the work broken into verifiable steps, and the validation that\n  proves it. Advisory: it reads and reports — the repository is left exactly as\n  it was found.\n\n  Use when: what to build is known but how is not yet decided — \"plan this\n  feature\", \"turn this investigation into a plan\", \"how should we build this\".\n  NOT for: root-causing a bug (investigate), or building the plan (implement).\n\nmodel: large\n\ninputs:\n  work:\n    default: \"\"\n    description: >-\n      What to plan — a feature description, an issue reference, or a goal. When\n      empty, the run's trigger message is the work.\n  report:\n    default: \"\"\n    description: >-\n      Optional path to a prior investigation report to build on — its claims are\n      verified, not trusted. Empty means no prior report.\n\n# ready:false is a valid completion (see the plan node): the run succeeds with\n# an authored outcome of false — lifecycle status and work outcome are separate facts.\nreturns: plan\noutcome_field: ready\n\nnodes:\n\n  # Blocked is a valid outcome, not a failure: ready:false naming exactly what\n  # is missing beats a plan built on guesses. Consumers gate on\n  # $plan.output.ready before building.\n  - id: plan\n    command: plan\n    # Advisory: the engine fails this node with the touched paths named if it\n    # modifies the working tree; replaced the record-state snapshot.\n    mutates_checkout: false\n    output_type: implementation-plan\n    output_format:\n      type: object\n      properties:\n        ready:\n          type: boolean\n        summary:\n          type: string\n      required: [ready, summary]\n\n  # Deterministic on both promises: a pleasant summary is not a plan, and an\n  # advisory run must not mutate the checkout (advisory agents resetting user\n  # work is a lived failure mode, not a hypothetical).\n  - id: assert-intact\n    bash: |\n      # Tree-intactness is engine-enforced via mutates_checkout: false above;\n      # what remains is the evidence contract.\n      if [ ! -s \"$ARTIFACTS_DIR/plan.md\" ]; then\n        echo \"assert-intact: the run completed but wrote no plan.md — a summary is not a plan.\" >&2\n        exit 1\n      fi\n      echo '{\"intact\":\"true\"}'\n    depends_on: [plan]\n",
  "archon-plan-to-pr": "name: archon-plan-to-pr\ndescription: |\n  Use when: You have an existing implementation plan and want to execute it end-to-end.\n  Input: Path to a plan file ($ARTIFACTS_DIR/plan.md or .agents/plans/*.md)\n  Output: PR ready for merge with comprehensive review completed\n\n  Full workflow:\n  1. Read plan, setup branch, extract scope limits\n  2. Verify plan research is still valid\n  3. Implement all tasks with type-checking\n  4. Run full validation suite\n  5. Create PR with template, mark ready\n  6. Comprehensive code review (5 parallel agents with scope limit awareness)\n  7. Synthesize and fix review findings\n  8. Final summary with decision matrix -> GitHub comment + follow-up recommendations\n\n  NOT for: Creating plans from scratch (use archon-idea-to-pr), quick fixes, standalone reviews.\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 1: SETUP\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: plan-setup\n    command: archon-plan-setup\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 2: CONFIRM PLAN\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: confirm-plan\n    command: archon-confirm-plan\n    depends_on: [plan-setup]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 3: IMPLEMENT\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: implement-tasks\n    command: archon-implement-tasks\n    depends_on: [confirm-plan]\n    context: fresh\n    provider: claude\n    model: large\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 4: VALIDATE\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: validate\n    command: archon-validate\n    depends_on: [implement-tasks]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 5: FINALIZE PR\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: finalize-pr\n    command: archon-finalize-pr\n    depends_on: [validate]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 6-7: CODE REVIEW + FIX (shared building block)\n  # Inlines archon-review-block: verify-pr-base -> review-scope -> sync ->\n  # 5 parallel review agents -> synthesize -> implement-fixes.\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: review\n    include: archon-review-block\n    depends_on: [finalize-pr]\n\n  # ═══════════════════════════════════════════════════════════════════\n  # PHASE 8: FINAL SUMMARY & FOLLOW-UP\n  # ═══════════════════════════════════════════════════════════════════\n\n  - id: workflow-summary\n    command: archon-workflow-summary\n    depends_on: [review]\n    context: fresh\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-pr": "name: archon-pr\ndescription: |\n  Open a pull request for the committed work on the current branch — draft by\n  default when composed, template-aware, with the body built from the run's\n  artifacts. Verifies by reading the created PR back. Never sweeps unrelated\n  changes and never force-pushes.\n\n  Use when: committed work on a branch needs a PR — \"open a PR\", \"create a\n  draft PR for this branch\".\n  NOT for: implementing (implement), reviewing (review), or merging (always human).\n\nmodel: medium\nrequires: [github]\n\ninputs:\n  draft:\n    default: \"true\"\n    description: '\"true\" opens the PR as a draft; anything else opens it ready for review.'\n\nreturns: pr\n\nnodes:\n  - id: pr\n    command: pr\n    output_type: pull-request\n    # This is the durable ownership record for every later public action in\n    # delivery and inbound forge event. Consumers use this qualified identity,\n    # never gh's ambient branch lookup.\n    output_format:\n      type: object\n      properties:\n        repo:\n          type: object\n          properties:\n            host: { type: string }\n            path: { type: string }\n          required: [host, path]\n        number: { type: integer }\n        url: { type: string }\n        head: { type: string }\n        base: { type: string }\n        is_draft: { type: boolean }\n      required: [repo, number, url, head, base, is_draft]\n",
  "archon-ralph-dag": "name: archon-ralph-dag\ndescription: |\n  Use when: User wants to run a Ralph implementation loop.\n  Triggers: \"ralph\", \"run ralph\", \"ralph dag\", \"run ralph dag\".\n\n  DAG workflow that:\n  1. Detects input: existing prd.json, existing prd.md (needs stories), or raw idea\n  2. Generates prd.md + prd.json if needed (explores codebase, breaks into stories)\n  3. Validates PRD files, reads project context, installs dependencies\n  4. Runs Ralph loop (fresh context per iteration) implementing one story per iteration\n  5. Creates PR and reports completion\n\n  Accepts: An idea description, a path to an existing prd.md, or a directory with prd.md + prd.json\n\nprovider: claude\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════\n  # NODE 1: DETECT INPUT\n  # Determines what the user provided: full PRD, partial PRD, or idea\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: detect-input\n    model: small\n    prompt: |\n      # Detect Ralph Input\n\n      **User input**: $ARGUMENTS\n\n      Determine what the user provided and prepare the PRD directory. Follow these steps exactly:\n\n      ## Step 1: Detect worktree\n\n      Run `git worktree list --porcelain` to check if you're in a worktree.\n      If you see multiple entries, you ARE in a worktree. The first entry (the one without \"branch\" pointing to your current branch) is the **main repo root**. Save it — you'll need it to find files.\n\n      ## Step 2: Classify the input\n\n      Look at the user input above. It's one of three things:\n\n      **Case A — Ralph directory path** (contains `.archon/ralph/`):\n      Extract the directory. Check if both `prd.json` and `prd.md` exist there (try locally first, then in the main repo root if in a worktree).\n\n      **Case B — File path** (ends in `.md`):\n      This is an external PRD file. Find it:\n      1. Try the path as-is (relative to cwd)\n      2. Try it as an absolute path\n      3. If in a worktree, try it relative to the **main repo root** from Step 1\n      Once found, read the file to confirm it's a PRD.\n\n      **Case C — Free text**:\n      Not a file path — it's a feature idea.\n\n      ## Step 3: Auto-discover existing ralph PRDs\n\n      If the input didn't point to a specific path, check if `.archon/ralph/` contains any `prd.json` files:\n      ```bash\n      find .archon/ralph -name \"prd.json\" -type f 2>/dev/null\n      ```\n\n      ## Step 4: Take action based on classification\n\n      **If Case A and both files exist** → output `ready` (no further action needed)\n\n      **If Case B (external PRD found)**:\n      1. Derive a kebab-case slug from the PRD filename or title (e.g., `workflow-lifecycle-overhaul`)\n      2. Create the ralph directory: `mkdir -p .archon/ralph/{slug}`\n      3. Copy the PRD content to `.archon/ralph/{slug}/prd.md`\n      4. Output `external_prd` with the new prd_dir\n\n      **If Case C or auto-discovered ralph dir has prd.md but no prd.json** → output `needs_generation`\n\n      ## Output\n\n      Your final output MUST be exactly one JSON object:\n      ```json\n      {\"input_type\": \"ready|external_prd|needs_generation\", \"prd_dir\": \".archon/ralph/{slug}\"}\n      ```\n    output_format:\n      type: object\n      properties:\n        input_type:\n          type: string\n          enum: [ready, external_prd, needs_generation]\n        prd_dir:\n          type: string\n      required: [input_type, prd_dir]\n\n  # ═══════════════════════════════════════════════════════════════\n  # NODE 2: GENERATE PRD\n  # Scenario 1: User has an idea → generate prd.md + prd.json\n  # Scenario 2: User has prd.md → generate prd.json with stories\n  # Skipped if prd.json already exists\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: generate-prd\n    depends_on: [detect-input]\n    when: \"$detect-input.output.input_type != 'ready'\"\n    command: archon-ralph-generate\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # NODE 3: VALIDATE & SETUP\n  # Finds PRD directory, reads all state files, installs deps,\n  # verifies the environment is ready for implementation.\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: validate-prd\n    depends_on: [detect-input, generate-prd]\n    trigger_rule: one_success\n    bash: |\n      set -e\n\n      # ── 1. Find PRD directory (passed from detect-input) ──────\n      PRD_DIR=$detect-input.output.prd_dir\n\n      # If detect-input didn't know the PRD dir (generated from scratch), discover it\n      if [ -z \"$PRD_DIR\" ] || [ ! -f \"$PRD_DIR/prd.json\" ]; then\n        FOUND=$(find .archon/ralph -name \"prd.json\" -type f 2>/dev/null | head -1)\n        if [ -n \"$FOUND\" ]; then\n          PRD_DIR=$(dirname \"$FOUND\")\n        fi\n      fi\n\n      if [ -z \"$PRD_DIR\" ] || [ ! -f \"$PRD_DIR/prd.json\" ]; then\n        echo \"ERROR: No prd.json found after generation step.\"\n        echo \"Check the generate-prd node output for errors.\"\n        exit 1\n      fi\n\n      if [ ! -f \"$PRD_DIR/prd.md\" ]; then\n        echo \"ERROR: prd.md not found in $PRD_DIR\"\n        exit 1\n      fi\n\n      # ── 2. Install dependencies (worktrees lack node_modules) ──\n      if [ -f \"bun.lock\" ] || [ -f \"bun.lockb\" ]; then\n        echo \"Installing dependencies (bun)...\"\n        bun install --frozen-lockfile 2>&1 | tail -3\n      elif [ -f \"package-lock.json\" ]; then\n        echo \"Installing dependencies (npm)...\"\n        npm ci 2>&1 | tail -3\n      elif [ -f \"yarn.lock\" ]; then\n        echo \"Installing dependencies (yarn)...\"\n        yarn install --frozen-lockfile 2>&1 | tail -3\n      elif [ -f \"pnpm-lock.yaml\" ]; then\n        echo \"Installing dependencies (pnpm)...\"\n        pnpm install --frozen-lockfile 2>&1 | tail -3\n      fi\n\n      # ── 3. Git state ──────────────────────────────────────────\n      echo \"BRANCH=$(git branch --show-current)\"\n      echo \"GIT_ROOT=$(git rev-parse --show-toplevel)\"\n\n      # ── 4. Output PRD context ─────────────────────────────────\n      echo \"PRD_DIR=$PRD_DIR\"\n      echo \"=== PRD_JSON_START ===\"\n      cat \"$PRD_DIR/prd.json\"\n      echo \"\"\n      echo \"=== PRD_JSON_END ===\"\n      echo \"=== PRD_MD_START ===\"\n      cat \"$PRD_DIR/prd.md\"\n      echo \"\"\n      echo \"=== PRD_MD_END ===\"\n      echo \"=== PROGRESS_START ===\"\n      if [ -f \"$PRD_DIR/progress.txt\" ]; then\n        cat \"$PRD_DIR/progress.txt\"\n      else\n        echo \"(no progress yet)\"\n      fi\n      echo \"\"\n      echo \"=== PROGRESS_END ===\"\n\n      # ── 5. Summary ────────────────────────────────────────────\n      TOTAL=$(grep -c '\"passes\"' \"$PRD_DIR/prd.json\" || true)\n      DONE=$(grep -c '\"passes\": true' \"$PRD_DIR/prd.json\" || true)\n      TOTAL=${TOTAL:-0}\n      DONE=${DONE:-0}\n      echo \"STORIES_TOTAL=$TOTAL\"\n      echo \"STORIES_DONE=$DONE\"\n      echo \"STORIES_REMAINING=$(( TOTAL - DONE ))\"\n\n  # ═══════════════════════════════════════════════════════════════\n  # NODE 4: RALPH IMPLEMENTATION LOOP\n  # Fresh context each iteration. Reads PRD state from disk.\n  # One story per iteration. Validates before committing.\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: implement\n    depends_on: [validate-prd]\n    idle_timeout: 600000\n    model: large\n    loop:\n      prompt: |\n        # Ralph Agent — Autonomous Story Implementation\n\n        You are an autonomous coding agent in a FRESH session — you have no memory of previous iterations.\n        Your job: Read state from disk, implement ONE story, validate, commit, update tracking, exit.\n\n        **Golden Rule**: If validation fails, fix it before committing. Never commit broken code. Never skip validation.\n\n        ---\n\n        ## Phase 0: CONTEXT — Load Project State\n\n        The upstream setup node produced this context:\n\n        $validate-prd.output\n\n        **User message**: $USER_MESSAGE\n\n        ---\n\n        ### 0.1 Parse PRD Directory\n\n        Extract the `PRD_DIR=...` line from the context above. This is the directory containing your PRD files.\n        Store this path — use it for ALL file operations below.\n\n        ### 0.2 Read Current State (from disk, not from context above)\n\n        The context above is a snapshot from before the loop started. Previous iterations may have changed files.\n        **You MUST re-read from disk to get the current state:**\n\n        1. **Read `{prd-dir}/progress.txt`** — your only link to previous iterations\n           - Check the `## Codebase Patterns` section FIRST for learnings from prior iterations\n           - Check recent entries for gotchas to avoid\n        2. **Read `{prd-dir}/prd.json`** — the source of truth for story completion state\n        3. **Read `{prd-dir}/prd.md`** — full requirements, technical patterns, acceptance criteria\n\n        ### 0.3 Read Project Rules\n\n        ```bash\n        cat CLAUDE.md\n        ```\n\n        Note all coding standards, patterns, and rules. Follow them exactly.\n\n        **PHASE_0_CHECKPOINT:**\n        - [ ] PRD directory identified\n        - [ ] progress.txt read (or noted as absent)\n        - [ ] prd.json read — know which stories pass/fail\n        - [ ] prd.md read — understand requirements\n        - [ ] CLAUDE.md rules noted\n\n        ---\n\n        ## Phase 1: SELECT — Pick Next Story\n\n        ### 1.1 Find Eligible Story\n\n        From `prd.json`, find the **highest priority** story where:\n        - `passes` is `false`\n        - ALL stories in `dependsOn` have `passes: true`\n\n        **If ALL stories have `passes: true`** → Skip to Phase 6 (Completion).\n\n        **If no eligible stories exist** (all remaining are blocked):\n        ```\n        BLOCKED: No eligible stories. Remaining stories and their blockers:\n        - {story-id}: blocked by {dep-id} (passes: false)\n        ```\n        End normally. The loop will terminate on max_iterations.\n\n        ### 1.2 Announce Selection\n\n        ```\n        ── Story Selected ──────────────────────────────────\n        ID: {story-id}\n        Title: {story-title}\n        Priority: {priority}\n        Dependencies: {deps or \"none\"}\n\n        Acceptance Criteria:\n        - {criterion 1}\n        - {criterion 2}\n        - ...\n        ────────────────────────────────────────────────────\n        ```\n\n        After announcing the selected story, emit the story started event:\n        ```bash\n        bun run cli workflow event emit --run-id $WORKFLOW_ID --type ralph_story_started --data '{\"story_id\":\"{story-id}\",\"title\":\"{story-title}\"}' || true\n        ```\n\n        **PHASE_1_CHECKPOINT:**\n        - [ ] Eligible story found (or all complete / all blocked)\n        - [ ] Acceptance criteria understood\n        - [ ] Dependencies verified as complete\n\n        ---\n\n        ## Phase 2: IMPLEMENT — Code the Story\n\n        ### 2.1 Explore Before Coding\n\n        Before writing any code:\n        1. Read all files you plan to modify — understand current state\n        2. Check `## Codebase Patterns` in progress.txt for discovered patterns\n        3. Look for similar implementations in the codebase to mirror\n        4. Read the `technicalNotes` field from the story in prd.json\n\n        ### 2.2 Implementation Rules\n\n        **DO:**\n        - Implement ONLY the selected story — one story per iteration\n        - Follow existing code patterns exactly (naming, structure, imports, error handling)\n        - Match the project's coding standards from CLAUDE.md\n        - Write or update tests as required by acceptance criteria\n        - Keep changes minimal and focused\n\n        **DON'T:**\n        - Refactor unrelated code\n        - Add improvements not in the acceptance criteria\n        - Change formatting of lines you didn't modify\n        - Install new dependencies without justification from prd.md\n        - Touch files unrelated to this story\n        - Over-engineer — do the simplest thing that satisfies the criteria\n\n        ### 2.3 Verify Types After Each File\n\n        After modifying each file, run:\n        ```bash\n        bun run type-check\n        ```\n\n        **If types fail:**\n        1. Read the error carefully\n        2. Fix the type issue in your code\n        3. Re-run type-check\n        4. Do NOT proceed to the next file until types pass\n\n        **PHASE_2_CHECKPOINT:**\n        - [ ] Only the selected story was implemented\n        - [ ] Types compile after each file change\n        - [ ] Tests written/updated as needed\n        - [ ] No unrelated changes\n\n        ---\n\n        ## Phase 3: VALIDATE — Full Verification\n\n        ### 3.1 Static Analysis\n\n        ```bash\n        bun run type-check && bun run lint\n        ```\n\n        **Must pass with zero errors and zero warnings.**\n\n        **If lint fails:**\n        1. Run `bun run lint:fix` for auto-fixable issues\n        2. Manually fix remaining issues\n        3. Re-run lint\n        4. Proceed only when clean\n\n        ### 3.2 Tests\n\n        ```bash\n        bun run test\n        ```\n\n        **All tests must pass.**\n\n        **If tests fail:**\n        1. Read the failure output\n        2. Determine: bug in your implementation or pre-existing failure?\n        3. If your bug → fix the implementation (not the test)\n        4. If pre-existing → note it but don't fix unrelated tests\n        5. Re-run tests\n        6. Repeat until green\n\n        ### 3.3 Format Check\n\n        ```bash\n        bun run format:check\n        ```\n\n        **If formatting fails:**\n        ```bash\n        bun run format\n        ```\n\n        ### 3.4 Verify Acceptance Criteria\n\n        Go through EACH acceptance criterion from the story:\n        - Is it satisfied by your implementation?\n        - Can you verify it (read the code, run a command, check a file)?\n\n        If a criterion is NOT met, go back to Phase 2 and fix it.\n\n        **PHASE_3_CHECKPOINT:**\n        - [ ] Type-check passes\n        - [ ] Lint passes (0 errors, 0 warnings)\n        - [ ] All tests pass\n        - [ ] Format is clean\n        - [ ] Every acceptance criterion verified\n\n        ---\n\n        ## Phase 4: COMMIT — Save Changes\n\n        ### 4.1 Stage Only Files You Edited\n\n        Stage **only** the files you actually edited for this story — never `git add -A`, `git add .`, or `git add -u`. List them by name:\n\n        ```bash\n        git add path/to/file1 path/to/file2 ...\n        git status --porcelain  # verify nothing scratch/review/PR-body is staged\n        git diff --cached --stat\n        ```\n\n        **Never stage** scratch / review / PR-body artifacts, even if they show up in `git status`:\n\n        - `.pr-body.md`, `pr-body.md`, `*.scratch.md`, `*.tmp.md`\n        - `review/`, `*-report.md` at the repo root\n        - Anything under `$ARTIFACTS_DIR`\n        - Repo-local Archon telemetry: `.archon/artifacts/`, `.archon/logs/`, `.archon/state/` (local-only — never in git)\n\n        Verify only expected files are staged. If unexpected files appear, investigate before committing.\n\n        ### 4.2 Write Commit Message\n\n        ```bash\n        git commit -m \"$(cat <<'EOF'\n        feat: {story-title}\n\n        Implements {story-id} from PRD.\n\n        Changes:\n        - {change 1}\n        - {change 2}\n        - {change 3}\n        EOF\n        )\"\n        ```\n\n        **Commit message rules:**\n        - Prefix: `feat:` for features, `fix:` for bugs, `refactor:` for refactors\n        - Title: the story title (not the PRD name)\n        - Body: list the actual changes made\n        - Do NOT include AI attribution\n\n        **PHASE_4_CHECKPOINT:**\n        - [ ] Only expected files committed\n        - [ ] Commit message is clear and accurate\n        - [ ] Working directory is clean after commit\n\n        ---\n\n        ## Phase 5: TRACK — Update Progress Files\n\n        ### 5.1 Update prd.json\n\n        Set `passes: true` and add a note for the completed story:\n\n        ```json\n        {\n          \"id\": \"{story-id}\",\n          \"passes\": true,\n          \"notes\": \"Implemented in iteration {N}. Files: {list}.\"\n        }\n        ```\n\n        After updating prd.json, emit the story completed event:\n        ```bash\n        bun run cli workflow event emit --run-id $WORKFLOW_ID --type ralph_story_completed --data '{\"story_id\":\"{story-id}\",\"title\":\"{story-title}\"}' || true\n        ```\n\n        ### 5.2 Update progress.txt\n\n        **Append** to `{prd-dir}/progress.txt`:\n\n        ```\n        ## {ISO Date} — {story-id}: {story-title}\n\n        **Status**: PASSED\n        **Files changed**:\n        - {file1} — {what changed}\n        - {file2} — {what changed}\n\n        **Acceptance criteria verified**:\n        - [x] {criterion 1}\n        - [x] {criterion 2}\n\n        **Learnings**:\n        - {Any pattern discovered}\n        - {Any gotcha encountered}\n        - {Any deviation from expected approach}\n\n        ---\n        ```\n\n        ### 5.3 Update Codebase Patterns (if applicable)\n\n        If you discovered a **reusable pattern** that future iterations should know about, **prepend** it to the `## Codebase Patterns` section at the TOP of progress.txt.\n\n        Format:\n        ```\n        ## Codebase Patterns\n\n        ### {Pattern Name}\n        - **Where**: `{file:lines}`\n        - **Pattern**: {description}\n        - **Example**: `{code snippet}`\n        ```\n\n        If the `## Codebase Patterns` section doesn't exist yet, create it at the top of the file.\n\n        **PHASE_5_CHECKPOINT:**\n        - [ ] prd.json updated with `passes: true`\n        - [ ] progress.txt appended with iteration details\n        - [ ] Codebase patterns updated (if applicable)\n\n        ---\n\n        ## Phase 6: COMPLETE — Check All Stories\n\n        ### 6.1 Re-read prd.json\n\n        ```bash\n        cat {prd-dir}/prd.json\n        ```\n\n        Count stories where `passes: false`.\n\n        ### 6.2 If ALL Stories Pass\n\n        1. **Push the branch:**\n           ```bash\n           git push -u origin HEAD\n           ```\n\n        2. **Read the PR template:**\n           Look for a PR template in the repo — check `.github/pull_request_template.md`, `.github/PULL_REQUEST_TEMPLATE.md`, and `docs/pull_request_template.md`. Read whichever one exists.\n\n           If a template was found, fill in **every section** using the context from this implementation. Don't skip sections or leave placeholders — fill them honestly based on the actual changes (summary, architecture, validation evidence, security, compatibility, rollback, etc.).\n\n           If no template was found, write a summary with: problem, what changed, stories table, and validation evidence.\n\n        3. **Create a draft PR** — resolve the origin repo first (in a fork clone, gh otherwise targets the upstream parent):\n           `ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')`\n           then `gh pr create --repo \"$ORIGIN_REPO\" --draft --base $BASE_BRANCH --title \"feat: {PRD feature name}\"` with the filled-in template as the body. Use a HEREDOC for the body.\n\n        4. **Output completion signal:**\n           ```\n           <promise>COMPLETE</promise>\n           ```\n\n        ### 6.3 If Stories Remain\n\n        Report status and end normally:\n        ```\n        ── Iteration Complete ──────────────────────────────\n        Story completed: {story-id} — {story-title}\n        Stories remaining: {count}\n        Next eligible: {next-story-id} — {next-story-title}\n        ────────────────────────────────────────────────────\n        ```\n\n        The loop engine will start the next iteration with a fresh context.\n\n        ---\n\n        ## Handling Edge Cases\n\n        ### Validation fails repeatedly\n        - If type-check or tests fail 3+ times on the same error, step back\n        - Re-read the acceptance criteria — you may be misunderstanding the requirement\n        - Check if the story is too large (needs breaking down)\n        - Note the blocker in progress.txt and end the iteration\n\n        ### Story is too large for one iteration\n        - Implement the minimum viable subset that satisfies the most critical acceptance criteria\n        - Set `passes: true` only if ALL criteria are met\n        - If you can't meet all criteria, leave `passes: false` and note what's done in progress.txt\n        - The next iteration will pick it up and continue\n\n        ### Pre-existing test failures\n        - If tests were failing BEFORE your changes, note them but don't fix unrelated code\n        - Run only the test files related to your changes if the full suite has pre-existing issues\n        - Document pre-existing failures in progress.txt\n\n        ### Dependency install fails\n        - Check if `bun.lock` or equivalent exists\n        - Try `bun install` without `--frozen-lockfile`\n        - Note the issue in progress.txt\n\n        ### Git state is dirty at iteration start\n        - This shouldn't happen (fresh worktree), but if it does:\n        - Run `git status` to understand what's dirty\n        - If it's leftover from a failed previous iteration, commit or stash\n        - Never discard changes silently\n\n        ### Blocked stories — all remaining have unmet dependencies\n        - Report the dependency chain in your output\n        - Check if a dependency was incorrectly left as `passes: false`\n        - If a dependency should be `passes: true` (the code exists and works), fix prd.json\n        - Otherwise, end the iteration — the loop will exhaust max_iterations\n\n        ---\n\n        ## File Format Reference\n\n        ### prd.json Schema\n\n        ```json\n        {\n          \"feature\": \"Feature Name\",\n          \"issueNumber\": 123,\n          \"userStories\": [\n            {\n              \"id\": \"US-001\",\n              \"title\": \"Short title\",\n              \"description\": \"As a..., I want..., so that...\",\n              \"acceptanceCriteria\": [\"criterion 1\", \"criterion 2\"],\n              \"technicalNotes\": \"Implementation hints\",\n              \"dependsOn\": [\"US-000\"],\n              \"priority\": 1,\n              \"passes\": false,\n              \"notes\": \"\"\n            }\n          ]\n        }\n        ```\n\n        ### progress.txt Format\n\n        ```\n        ## Codebase Patterns\n\n        ### {Pattern Name}\n        - Where: `file:lines`\n        - Pattern: description\n        - Example: `code`\n\n        ---\n\n        ## {Date} — {story-id}: {title}\n\n        **Status**: PASSED\n        **Files changed**: ...\n        **Acceptance criteria verified**: ...\n        **Learnings**: ...\n\n        ---\n        ```\n\n        ---\n\n        ## Success Criteria\n\n        - **ONE_STORY**: Exactly one story implemented per iteration\n        - **VALIDATED**: Type-check + lint + tests + format all pass before commit\n        - **COMMITTED**: Changes committed with clear message\n        - **TRACKED**: prd.json and progress.txt updated accurately\n        - **PATTERNS_SHARED**: Discovered patterns added to progress.txt for future iterations\n        - **NO_SCOPE_CREEP**: No unrelated changes, no refactoring, no \"improvements\"\n      until: COMPLETE\n      max_iterations: 15\n      fresh_context: true\n\n  - id: verify-pr-base\n    bash: |\n      set -euo pipefail\n      # Pin to the origin remote — in a fork clone, gh otherwise queries the upstream parent\n      ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')\n      HEAD_BRANCH=$(git rev-parse --abbrev-ref HEAD)\n      PR_NUMBER=$(gh pr list --repo \"$ORIGIN_REPO\" --head \"$HEAD_BRANCH\" --state open --json number -q '.[0].number')\n      if [ -z \"$PR_NUMBER\" ]; then\n        echo \"No open PR found for branch $HEAD_BRANCH\" >&2\n        exit 1\n      fi\n      EXPECTED=\"$BASE_BRANCH\"\n      ACTUAL=$(gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json baseRefName -q '.baseRefName')\n      if [ \"$ACTUAL\" != \"$EXPECTED\" ]; then\n        echo \"Base mismatch on PR #$PR_NUMBER: expected=$EXPECTED actual=$ACTUAL — re-targeting\" >&2\n        gh pr edit \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --base \"$EXPECTED\"\n      else\n        echo \"PR base verified: $EXPECTED\"\n      fi\n    depends_on: [implement]\n\n  # ═══════════════════════════════════════════════════════════════\n  # NODE 5: COMPLETION REPORT\n  # Reads final state and produces a summary.\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: report\n    depends_on: [verify-pr-base]\n    prompt: |\n      # Completion Report\n\n      The Ralph implementation loop has finished. Generate a completion report.\n\n      ## Context\n\n      **Loop output (last iteration):**\n\n      $implement.output\n\n      **Setup context:**\n\n      $validate-prd.output\n\n      ---\n\n      ## Instructions\n\n      ### 1. Read Final State\n\n      Extract the `PRD_DIR=...` from the setup context above.\n      Read the CURRENT files from disk:\n\n      ```bash\n      cat {prd-dir}/prd.json\n      cat {prd-dir}/progress.txt\n      ```\n\n      ### 2. Gather Git Info\n\n      ```bash\n      git log --oneline --no-merges $(git merge-base HEAD $BASE_BRANCH)..HEAD\n      git diff --stat $(git merge-base HEAD $BASE_BRANCH)..HEAD\n      ```\n\n      ### 3. Check PR Status\n\n      ```bash\n      gh pr view HEAD --json url,number,state 2>/dev/null || echo \"No PR found\"\n      ```\n\n      ### 4. Generate Report\n\n      Output this format:\n\n      ```\n      ═══════════════════════════════════════════════════════\n      RALPH DAG — COMPLETION REPORT\n      ═══════════════════════════════════════════════════════\n\n      Feature: {feature name from prd.json}\n      PRD: {prd-dir}\n      Branch: {branch name}\n      PR: {url or \"not created\"}\n\n      ── Stories ─────────────────────────────────────────\n\n      | ID | Title | Status |\n      |----|-------|--------|\n      {for each story from prd.json}\n\n      Total: {N}/{M} stories passing\n\n      ── Commits ─────────────────────────────────────────\n\n      {git log output}\n\n      ── Files Changed ─────────────────────────────────\n\n      {git diff --stat output}\n\n      ── Patterns Discovered ─────────────────────────────\n\n      {from ## Codebase Patterns in progress.txt, or \"None\"}\n\n      ═══════════════════════════════════════════════════════\n      ```\n\n      Keep it factual. No commentary — just the data.\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-refactor-safely": "name: archon-refactor-safely\ndescription: |\n  Use when: User wants to refactor code safely with continuous validation and behavior preservation.\n  Triggers: \"refactor\", \"refactor safely\", \"split this file\", \"extract module\", \"break up\",\n            \"decompose\", \"safe refactor\", \"split file\", \"extract into modules\".\n  Does: Scans refactoring scope -> analyzes impact (read-only) -> plans ordered task list ->\n        executes with type-check hooks after every edit -> validates full suite ->\n        verifies behavior preservation (read-only) -> creates PR with before/after comparison.\n  NOT for: Bug fixes (use archon-fix-github-issue), feature development (use archon-feature-development),\n           general architecture sweeps (use archon-architect), PR reviews.\n\n  Key safety features:\n  - Analysis and verification nodes are read-only (denied_tools: [Write, Edit, Bash])\n  - PreToolUse hooks check if each edit is in the plan\n  - PostToolUse hooks force type-check after every file change\n  - Behavior verification confirms no logic changes after refactoring\n\nprovider: claude\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 1: SCAN — Find files matching the refactoring target\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: scan-scope\n    bash: |\n      echo \"=== REFACTORING TARGET ===\"\n      echo \"User request: $ARGUMENTS\"\n      echo \"\"\n\n      echo \"=== FILE SIZE ANALYSIS (source files by size) ===\"\n      find . -name '*.ts' -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/dist/*' -not -name '*.test.ts' -not -name '*.d.ts' \\\n        -exec wc -l {} + 2>/dev/null | sort -rn | head -30\n      echo \"\"\n\n      echo \"=== FILES OVER 500 LINES ===\"\n      find . -name '*.ts' -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/dist/*' -not -name '*.test.ts' -not -name '*.d.ts' \\\n        -exec sh -c 'lines=$(wc -l < \"$1\"); if [ \"$lines\" -gt 500 ]; then echo \"$lines $1\"; fi' _ {} \\; 2>/dev/null | sort -rn\n      echo \"\"\n\n      echo \"=== FUNCTION COUNT PER FILE (top 20) ===\"\n      for f in $(find . -name '*.ts' -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/dist/*' -not -name '*.test.ts' -not -name '*.d.ts'); do\n        count=$(grep -cE '^\\s*(export\\s+)?(async\\s+)?function\\s|=>\\s*\\{' \"$f\" 2>/dev/null) || count=0\n        if [ \"$count\" -gt 5 ]; then\n          echo \"$count functions: $f\"\n        fi\n      done | sort -rn | head -20\n      echo \"\"\n\n      echo \"=== EXPORT ANALYSIS (files with many exports) ===\"\n      for f in $(find . -name '*.ts' -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/dist/*' -not -name '*.test.ts' -not -name '*.d.ts'); do\n        count=$(grep -c \"^export \" \"$f\" 2>/dev/null) || count=0\n        if [ \"$count\" -gt 5 ]; then\n          echo \"$count exports: $f\"\n        fi\n      done | sort -rn | head -20\n    timeout: 60000\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 2: ANALYZE IMPACT — Read-only deep analysis\n  # Maps call sites, identifies risk areas, understands dependencies\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: analyze-impact\n    prompt: |\n      You are a senior software engineer analyzing code for a safe refactoring.\n\n      ## Refactoring Request\n\n      $ARGUMENTS\n\n      ## Codebase Scan Results\n\n      $scan-scope.output\n\n      ## Instructions\n\n      1. Identify the PRIMARY file(s) targeted for refactoring based on the user's request\n         and the scan results above\n      2. Read each target file thoroughly — understand every function, type, and export\n      3. For each target file, map ALL call sites:\n         - Use Grep to find every import of the target file across the codebase\n         - Track which specific exports are used and where\n         - Note any dynamic imports or re-exports through index files\n      4. Identify risk areas:\n         - Functions with complex internal dependencies (shared closures, module-level state)\n         - Circular dependencies between functions in the file\n         - Any module-level side effects (top-level `const`, initialization code)\n         - Exports that are part of the public API vs internal-only\n      5. Check for existing tests:\n         - Find test files for the target module(s)\n         - Note what's tested and what isn't\n\n      ## Output\n\n      Write a thorough impact analysis to `$ARTIFACTS_DIR/impact-analysis.md` with:\n\n      ### Target Files\n      - File path, line count, function count\n      - List of all exported symbols with brief descriptions\n\n      ### Dependency Map\n      - Which files import from the target (with specific imports used)\n      - Which files the target imports from\n\n      ### Risk Assessment\n      - Module-level state or side effects\n      - Complex internal dependencies between functions\n      - Public API surface that must be preserved exactly\n\n      ### Test Coverage\n      - Existing test files and what they cover\n      - Critical paths that must remain tested\n\n      ### Recommended Decomposition Strategy\n      - Suggested module boundaries (which functions group together)\n      - Rationale for each grouping (cohesion, shared dependencies)\n    depends_on: [scan-scope]\n    context: fresh\n    denied_tools: [Edit, Bash]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 3: PLAN REFACTOR — Ordered task list with rollback strategy\n  # Read-only: produces the plan, does not execute it\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: plan-refactor\n    prompt: |\n      You are planning a safe refactoring. You must produce a precise, ordered plan\n      that another agent will follow literally.\n\n      ## Impact Analysis\n\n      $analyze-impact.output\n\n      ## Refactoring Goal\n\n      $ARGUMENTS\n\n      ## Principles\n\n      - **Behavior preservation**: The refactoring must NOT change any behavior — only structure\n      - **Incremental**: Each step must leave the codebase in a compilable state\n      - **Reversible**: Each step can be independently reverted\n      - **No mixed concerns**: Do not combine refactoring with bug fixes or improvements\n      - **Preserve public API**: All existing exports must remain accessible from the same import paths\n      - **Maximum file size**: Target 500 lines or fewer per file after refactoring\n\n      ## Instructions\n\n      1. Read the impact analysis from `$ARTIFACTS_DIR/impact-analysis.md`\n      2. Read the target file(s) to understand the current structure\n      3. Design the decomposition:\n         - Group related functions into cohesive modules\n         - Identify shared utilities, types, and constants\n         - Plan the new file structure with descriptive names\n      4. Write an ordered task list where each task is:\n         - Independent and leaves code compilable after completion\n         - Specific about what to extract and where\n         - Clear about import updates needed\n\n      ## Output\n\n      Write the plan to `$ARTIFACTS_DIR/refactor-plan.md` with:\n\n      ### File Structure (Before)\n      ```\n      [current structure with line counts]\n      ```\n\n      ### File Structure (After)\n      ```\n      [planned structure with estimated line counts]\n      ```\n\n      ### Ordered Tasks\n\n      For each task:\n      ```\n      ## Task N: [brief description]\n\n      **Action**: CREATE | EXTRACT | UPDATE\n      **Source**: [source file]\n      **Target**: [target file]\n      **What moves**:\n      - function functionName (lines X-Y)\n      - type TypeName (lines X-Y)\n\n      **Import updates needed**:\n      - [file]: change import from [old] to [new]\n\n      **Rollback**: [how to undo this specific step]\n      ```\n\n      ### Validation Commands\n      - Type check: `bun run type-check`\n      - Lint: `bun run lint`\n      - Tests: `bun run test`\n      - Format: `bun run format:check`\n    depends_on: [analyze-impact]\n    context: fresh\n    denied_tools: [Edit, Bash]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 4: EXECUTE REFACTOR — Implements the plan with guardrails\n  # Hooks enforce type-check after every edit and plan adherence\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: execute-refactor\n    model: large\n    prompt: |\n      You are executing a refactoring plan with strict safety guardrails.\n\n      ## Plan\n\n      Read the full plan from `$ARTIFACTS_DIR/refactor-plan.md` — follow it LITERALLY.\n\n      ## Rules\n\n      - **Follow the plan exactly** — do not add extra improvements or cleanups\n      - **One task at a time** — complete each task fully before starting the next\n      - **Type-check after every file change** — you'll be prompted to do this after each edit\n      - **Preserve all behavior** — refactoring means moving code, not changing it\n      - **Preserve the public API** — if the original file exported something, it must still be\n        importable from the same path (use re-exports in the original file if needed)\n      - **Update all import sites** — every file that imported from the original must be updated\n      - **Commit after each logical task** — one commit per plan task with a clear message\n\n      ## Process for Each Task\n\n      1. Read the plan task\n      2. Read the source file to understand current state\n      3. Create the new file (if extracting) with the functions/types being moved\n      4. Update the source file to remove the moved code and add imports from the new file\n      5. Update the original file's exports to re-export from the new module (API preservation)\n      6. Use Grep to find and update ALL import sites across the codebase\n      7. Run `bun run type-check` to verify (you'll be reminded by hooks)\n      8. Commit ONLY the files you edited for this task — never `git add -A`. Stage by name, then commit:\n         ```bash\n         git add path/to/file1 path/to/file2 ...\n         git status --porcelain  # verify nothing scratch is staged\n         git commit -m \"refactor: [task description]\"\n         ```\n         **Never stage**: `.pr-body.md`, `pr-body.md`, `*.scratch.md`, `*.tmp.md`, `review/`, `*-report.md` at the repo root, anything under `$ARTIFACTS_DIR`, or repo-local `.archon/artifacts/`, `.archon/logs/`, `.archon/state/` (local-only Archon telemetry — never in git).\n      9. Move to next task\n\n      ## Handling Problems\n\n      - If type-check fails after a change: fix it immediately before proceeding\n      - If a task is more complex than planned: complete it anyway, note the deviation\n      - If you discover the plan missed an import site: update it and note it\n      - NEVER skip a task — complete them in order\n    depends_on: [plan-refactor]\n    context: fresh\n    hooks:\n      PreToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PreToolUse\n              additionalContext: >\n                Before modifying this file: Is this file in your refactoring plan\n                ($ARTIFACTS_DIR/refactor-plan.md)? If it's not a planned target file\n                AND not a file that imports from the target, explain why you're touching it.\n                Unplanned changes increase risk.\n      PostToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            systemMessage: >\n              You just modified a file. STOP and do these things NOW before making any\n              other changes:\n              1. Run `bun run type-check` to verify the change compiles\n              2. If type-check fails, fix the error immediately\n              3. Verify you preserved the exact same behavior — no logic changes, only structural moves\n              Only proceed to the next change after type-check passes.\n        - matcher: \"Bash\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PostToolUse\n              additionalContext: >\n                Check the exit code. If type-check or any validation failed, fix the issue\n                before continuing. Do not accumulate broken state.\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 5: VALIDATE — Full test suite (bash, no AI escape hatch)\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: validate\n    bash: |\n      echo \"=== TYPE CHECK ===\"\n      bun run type-check 2>&1\n      TC_EXIT=$?\n\n      echo \"\"\n      echo \"=== LINT ===\"\n      bun run lint 2>&1\n      LINT_EXIT=$?\n\n      echo \"\"\n      echo \"=== FORMAT CHECK ===\"\n      bun run format:check 2>&1\n      FMT_EXIT=$?\n\n      echo \"\"\n      echo \"=== TESTS ===\"\n      bun run test 2>&1\n      TEST_EXIT=$?\n\n      echo \"\"\n      echo \"=== FILE SIZE CHECK ===\"\n      echo \"Files still over 500 lines:\"\n      find . -name '*.ts' -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/dist/*' -not -name '*.test.ts' -not -name '*.d.ts' \\\n        -exec sh -c 'lines=$(wc -l < \"$1\"); if [ \"$lines\" -gt 500 ]; then echo \"$lines $1\"; fi' _ {} \\; 2>/dev/null | sort -rn\n      echo \"\"\n\n      echo \"=== RESULTS ===\"\n      echo \"Type check: $([ $TC_EXIT -eq 0 ] && echo 'PASS' || echo 'FAIL')\"\n      echo \"Lint: $([ $LINT_EXIT -eq 0 ] && echo 'PASS' || echo 'FAIL')\"\n      echo \"Format: $([ $FMT_EXIT -eq 0 ] && echo 'PASS' || echo 'FAIL')\"\n      echo \"Tests: $([ $TEST_EXIT -eq 0 ] && echo 'PASS' || echo 'FAIL')\"\n\n      if [ $TC_EXIT -eq 0 ] && [ $LINT_EXIT -eq 0 ] && [ $FMT_EXIT -eq 0 ] && [ $TEST_EXIT -eq 0 ]; then\n        echo \"VALIDATION_STATUS: PASS\"\n      else\n        echo \"VALIDATION_STATUS: FAIL\"\n      fi\n    depends_on: [execute-refactor]\n    timeout: 300000\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 6: FIX VALIDATION FAILURES (if any)\n  # Only does real work if validation failed\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: fix-failures\n    prompt: |\n      Review the validation output below.\n\n      ## Validation Output\n\n      $validate.output\n\n      ## Instructions\n\n      If the output ends with \"VALIDATION_STATUS: PASS\", respond with\n      \"All checks passed — no fixes needed.\" and stop.\n\n      If there are failures:\n\n      1. Read the validation failures carefully\n      2. Fix ONLY what's broken — do not make additional improvements\n      3. If a fix requires changing behavior (not just fixing a type/lint error),\n         revert the original change instead\n      4. Run the specific failing check after each fix to confirm it passes\n      5. After all fixes, run the full validation suite: `bun run validate`\n\n      If there are files still over 500 lines, note them but do NOT attempt further\n      splitting in this node — that would require a new plan cycle.\n    depends_on: [validate]\n    context: fresh\n    hooks:\n      PostToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            systemMessage: >\n              You just made a fix. Run the specific failing validation check NOW\n              to verify your fix works. Do not batch fixes — verify each one.\n      PreToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PreToolUse\n              additionalContext: >\n                You are fixing validation failures only. Do not make any changes\n                beyond what's needed to pass the failing checks. If in doubt, revert\n                the original change that caused the failure.\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 7: VERIFY BEHAVIOR — Read-only confirmation\n  # Ensures the refactoring preserved behavior by tracing call paths\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: verify-behavior\n    prompt: |\n      You are a code reviewer verifying that a refactoring preserved exact behavior.\n      You can ONLY read files — you cannot make any changes.\n\n      ## Refactoring Plan\n\n      Read the plan from `$ARTIFACTS_DIR/refactor-plan.md` to understand what was intended.\n\n      ## Instructions\n\n      1. Use Grep and Glob to find all files in the new module locations listed in\n         the plan, then Read each one. (Note: Bash is denied in this read-only node,\n         so use Grep/Glob/Read to discover changes instead of git commands.)\n      2. For each new file created by the refactoring:\n         - Verify the extracted functions match the originals exactly (no logic changes)\n         - Check that all types and interfaces are preserved\n      3. For the original file(s):\n         - Verify re-exports exist for all symbols that were previously exported\n         - Confirm no function bodies were changed (only moved)\n      4. For all import sites updated:\n         - Verify imports resolve to the correct new locations\n         - Check that no import was missed\n      5. Verify the public API is preserved:\n         - Any code that imported from the original file should still work unchanged\n         - Re-exports in the original file should cover all moved symbols\n\n      ## Output\n\n      Write your verification report to `$ARTIFACTS_DIR/behavior-verification.md`:\n\n      ### Verdict: PASS | FAIL\n\n      ### Functions Verified\n      | Function | Original Location | New Location | Behavior Preserved |\n      |----------|------------------|--------------|-------------------|\n      | funcName | file.ts:42 | new-file.ts:10 | Yes/No |\n\n      ### Public API Check\n      - [ ] All original exports still accessible from original import path\n      - [ ] Re-exports correctly configured\n\n      ### Import Sites Updated\n      - [ ] All N import sites verified\n\n      ### Issues Found\n      [List any behavior changes detected, or \"None — refactoring is behavior-preserving\"]\n    depends_on: [fix-failures]\n    context: fresh\n    denied_tools: [Write, Edit, Bash]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 8: CREATE PR — Detailed description with before/after\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: create-pr\n    prompt: |\n      Create a pull request for the refactoring.\n\n      ## Context\n\n      - **Refactoring goal**: $ARGUMENTS\n      - **Impact analysis**: Read `$ARTIFACTS_DIR/impact-analysis.md`\n      - **Refactoring plan**: Read `$ARTIFACTS_DIR/refactor-plan.md`\n      - **Validation**: $validate.output\n      - **Behavior verification**: Read `$ARTIFACTS_DIR/behavior-verification.md`\n\n      ## Instructions\n\n      1. Stage all changes and create a final commit if there are uncommitted changes\n      2. Push the branch: `git push -u origin HEAD`\n      3. Resolve the origin repo — in a fork clone, gh otherwise targets the upstream parent:\n         `ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')`\n      4. Check if a PR already exists: `gh pr list --repo \"$ORIGIN_REPO\" --head $(git branch --show-current)`\n      5. Create the PR targeting `$BASE_BRANCH` as the base branch:\n         `gh pr create --repo \"$ORIGIN_REPO\" --base $BASE_BRANCH --title \"...\" --body \"...\"`, then format\n         title/body per the template below\n      6. Save the PR URL to `$ARTIFACTS_DIR/.pr-url`\n\n      ## PR Format\n\n      - **Title**: `refactor: [concise description]` (under 70 chars)\n      - **Body**:\n\n      ```markdown\n      ## Refactoring: [goal]\n\n      ### Motivation\n\n      [Why this refactoring was needed — file sizes, complexity, maintainability]\n\n      ### Before\n\n      ```\n      [Original file structure with line counts from the plan]\n      ```\n\n      ### After\n\n      ```\n      [New file structure with line counts]\n      ```\n\n      ### Changes\n\n      [For each new module: what was extracted and why it's a cohesive unit]\n\n      ### Safety\n\n      - [x] Type check passes\n      - [x] Lint passes\n      - [x] Tests pass (all existing tests still green)\n      - [x] Public API preserved (re-exports maintain backward compatibility)\n      - [x] Behavior verification passed (read-only audit confirmed no logic changes)\n      - [x] Each task committed separately for easy review/revert\n\n      ### Review Guide\n\n      Each commit represents one extraction step. Review commits individually for easiest review.\n      All commits are behavior-preserving structural moves.\n      ```\n    depends_on: [verify-behavior]\n    context: fresh\n    hooks:\n      PreToolUse:\n        - matcher: \"Write|Edit\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PreToolUse\n              permissionDecision: deny\n              permissionDecisionReason: \"PR creation node — do not modify source files. Use only git and gh commands.\"\n      PostToolUse:\n        - matcher: \"Bash\"\n          response:\n            hookSpecificOutput:\n              hookEventName: PostToolUse\n              additionalContext: >\n                Verify this command succeeded. If git push or gh pr create failed,\n                read the error message carefully before retrying.\n\n  - id: verify-pr-base\n    bash: |\n      set -euo pipefail\n      # Pin to the origin remote — in a fork clone, gh otherwise queries the upstream parent\n      ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')\n      HEAD_BRANCH=$(git rev-parse --abbrev-ref HEAD)\n      PR_NUMBER=$(gh pr list --repo \"$ORIGIN_REPO\" --head \"$HEAD_BRANCH\" --state open --json number -q '.[0].number')\n      if [ -z \"$PR_NUMBER\" ]; then\n        echo \"No open PR found for branch $HEAD_BRANCH\" >&2\n        exit 1\n      fi\n      EXPECTED=\"$BASE_BRANCH\"\n      ACTUAL=$(gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json baseRefName -q '.baseRefName')\n      if [ \"$ACTUAL\" != \"$EXPECTED\" ]; then\n        echo \"Base mismatch on PR #$PR_NUMBER: expected=$EXPECTED actual=$ACTUAL — re-targeting\" >&2\n        gh pr edit \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --base \"$EXPECTED\"\n      else\n        echo \"PR base verified: $EXPECTED\"\n      fi\n    depends_on: [create-pr]\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-remotion-generate": "name: archon-remotion-generate\ndescription: |\n  Use when: User wants to generate or modify a Remotion video composition using AI.\n  Triggers: \"create a video\", \"generate video\", \"remotion\", \"make an animation\",\n            \"video about\", \"animate\".\n  Does: AI writes Remotion React code -> renders preview stills -> renders full video ->\n        summarizes the output.\n  Requires: A Remotion project in the working directory (src/index.ts, src/Root.tsx).\n  Optional: Install the remotion-best-practices skill for higher quality output:\n            npx skills add remotion-dev/skills\n\nnodes:\n  # ── Layer 0: Check project structure ──────────────────────────────────\n  - id: check-project\n    bash: |\n      if [ ! -f \"src/index.ts\" ] || [ ! -f \"src/Root.tsx\" ]; then\n        echo \"ERROR: Not a Remotion project. Expected src/index.ts and src/Root.tsx.\"\n        echo \"Run 'npx create-video@latest' first, then run this workflow from that directory.\"\n        exit 1\n      fi\n      echo \"Remotion project detected.\"\n      npx remotion compositions src/index.ts 2>&1 | tail -5\n      echo \"\"\n      echo \"PROJECT_READY\"\n    timeout: 60000\n\n  # ── Layer 1: Generate composition code ────────────────────────────────\n  - id: generate\n    prompt: |\n      You are working in a Remotion video project. The project root is the current directory.\n\n      Find and read the existing composition files to understand the project structure.\n      Look in src/ for Root.tsx and any composition components.\n\n      Now create or modify the composition to match this request:\n\n      $ARGUMENTS\n\n      Use $remotion-best-practices for the implementation.\n\n      Rules:\n      - Use useCurrentFrame() and interpolate()/spring() for ALL animations\n      - Never use CSS transitions, Math.random(), setTimeout, or Date.now()\n      - Use AbsoluteFill for layout, Sequence for scene timing\n      - Use the <Img> component from 'remotion' (not native <img>) for images\n      - Keep dimensions 1920x1080 at 30 fps unless the user specifies otherwise\n      - Update the Zod schema and defaultProps in Root.tsx if you change props\n      - Use even numbers for width/height (required for MP4)\n      - Always clamp interpolations: extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n\n      After writing the code, read it back to verify it looks correct.\n    depends_on: [check-project]\n    skills:\n      - remotion-best-practices\n    allowed_tools:\n      - Read\n      - Write\n      - Edit\n      - Glob\n\n  # ── Layer 2: Render preview stills ────────────────────────────────────\n  - id: render-preview\n    bash: |\n      mkdir -p out\n      COMP_ID=$(npx remotion compositions src/index.ts 2>&1 | grep -E '^\\S' | head -1 | awk '{print $1}')\n      if [ -z \"$COMP_ID\" ]; then\n        echo \"RENDER_FAILED: Could not detect composition ID\"\n        exit 1\n      fi\n      echo \"Composition: $COMP_ID\"\n\n      DURATION=$(npx remotion compositions src/index.ts 2>&1 | grep -E '^\\S' | head -1 | awk '{print $4}')\n      MID_FRAME=$(( ${DURATION:-150} / 2 ))\n      LATE_FRAME=$(( ${DURATION:-150} * 3 / 4 ))\n\n      echo \"Rendering preview stills at frames 1, $MID_FRAME, $LATE_FRAME...\"\n      npx remotion still src/index.ts \"$COMP_ID\" out/preview-early.png --frame=1 2>&1 | tail -2\n      npx remotion still src/index.ts \"$COMP_ID\" out/preview-mid.png --frame=$MID_FRAME 2>&1 | tail -2\n      npx remotion still src/index.ts \"$COMP_ID\" out/preview-late.png --frame=$LATE_FRAME 2>&1 | tail -2\n      RESULT=$?\n\n      if [ $RESULT -eq 0 ]; then\n        echo \"\"\n        echo \"RENDER_SUCCESS\"\n        ls -la out/preview-*.png\n      else\n        echo \"RENDER_FAILED\"\n      fi\n    depends_on: [generate]\n    timeout: 120000\n\n  # ── Layer 3: Render full video ────────────────────────────────────────\n  - id: render-video\n    bash: |\n      COMP_ID=$(npx remotion compositions src/index.ts 2>&1 | grep -E '^\\S' | head -1 | awk '{print $1}')\n      echo \"Rendering full video: $COMP_ID\"\n      npx remotion render src/index.ts \"$COMP_ID\" out/video.mp4 --codec=h264 --crf=18 2>&1 | tail -10\n      RESULT=$?\n\n      if [ $RESULT -eq 0 ]; then\n        echo \"\"\n        echo \"VIDEO_RENDER_SUCCESS\"\n        ls -la out/video.mp4\n      else\n        echo \"VIDEO_RENDER_FAILED\"\n      fi\n    depends_on: [render-preview]\n    timeout: 300000\n\n  # ── Layer 4: Summary ──────────────────────────────────────────────────\n  - id: summary\n    prompt: |\n      A Remotion video was generated and rendered.\n\n      Original request: $ARGUMENTS\n\n      Preview render: $render-preview.output\n      Video render: $render-video.output\n\n      Read the generated composition code and the preview stills (out/preview-early.png,\n      out/preview-mid.png, out/preview-late.png) to verify the output.\n\n      Summarize:\n      1. What the video contains (based on code and stills)\n      2. Whether the renders succeeded\n      3. Where the output file is (out/video.mp4)\n    depends_on: [render-video]\n    allowed_tools:\n      - Read\n    model: small\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-resolve-conflicts": "name: archon-resolve-conflicts\ndescription: |\n  Use when: PR has merge conflicts that need resolution.\n  Triggers: \"resolve conflicts\", \"fix merge conflicts\", \"rebase this PR\", \"resolve this\",\n            \"fix conflicts\", \"merge conflicts\", \"rebase and fix\".\n  Does: Fetches latest base branch -> analyzes conflicts -> auto-resolves simple conflicts ->\n        presents options for complex conflicts -> commits and pushes resolution.\n  NOT for: PRs without conflicts, general rebasing without conflicts, squashing commits.\n\n  This workflow helps resolve merge conflicts by analyzing the conflicting changes,\n  automatically resolving where intent is clear, and presenting options for complex conflicts.\n\nnodes:\n  - id: resolve\n    command: archon-resolve-merge-conflicts\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-review": "name: archon-review\ndescription: |\n  Review a change through parallel specialist lenses and produce one evidence-based\n  verdict. On the first round, code, seams, simplify, and tests always run; errors are\n  selected for failure-path changes and docs only for shipped-doc changes. Reviews a PR when given one, otherwise the\n  working diff. Advisory and read-only: it judges, it never edits. Given the\n  previous round's report, one continuation reviewer verifies the prior findings,\n  reviews the correction delta, and follows their causal class without repeating\n  the full specialist fan-out.\n\n  When reviewing a PR, the final synthesized report is posted to it as one\n  canonical comment, edited in place on re-review.\n\n  Use when: changes need judging — \"review this PR\", \"review my changes\",\n  \"is this ready to merge\".\n  NOT for: fixing findings (implement), running the project's checks (validate),\n  or writing code.\n\nmodel: medium\n\ninputs:\n  scope:\n    default: \"\"\n    description: >-\n      What to review — a PR number/URL, a branch, or empty for the working diff\n      against the merge-base.\n  prior_report:\n    default: \"\"\n    description: >-\n      Path to the previous review round's report. When set, this round verifies\n      prior findings first and reviews only the delta since the report's recorded\n      head SHA.\n  work_order:\n    default: \"\"\n    description: >-\n      The accepted outcome and scope boundaries for this change. Delivery passes\n      the same work order implementation received. Standalone review may leave\n      this empty and use the PR's problem, outcome, and explicit scope instead.\n  errors:\n    default: false\n    description: Enable the silent-failure lens on a full review.\n  docs:\n    default: \"auto\"\n    description: >-\n      Docs-impact lens — auto selects shipped-documentation changes from the\n      reviewed diff; true or false overrides that selection.\n\nreturns: synthesize\noutcome_field: ready\n\nnodes:\n  - id: mode\n    script: resolve-review-mode\n    runtime: uv\n    with:\n      prior_report: \"$INPUTS.prior_report\"\n\n  - id: scope\n    command: review-scope\n    context: fresh\n    depends_on: [mode]\n    output_format:\n      type: object\n      properties:\n        docs: { type: boolean }\n      required: [docs]\n\n  # ── Default-on lenses ─────────────────────────────────────────────\n  - id: code\n    command: review-code\n    context: fresh\n    depends_on: [scope]\n    when: \"$mode.output.continuation == false\"\n    retry:\n      max_attempts: 2\n      delay_ms: 20000\n\n  - id: seams\n    command: review-seams\n    context: fresh\n    depends_on: [scope]\n    when: \"$mode.output.continuation == false\"\n    retry:\n      max_attempts: 2\n      delay_ms: 20000\n\n  # Structure is judged on every change, never selected for one. The lens this\n  # replaces was gated behind a suggestions-only charter and measured zero yield —\n  # which measured the demotion, not the concern.\n  - id: simplify\n    command: review-simplify\n    context: fresh\n    depends_on: [scope]\n    when: \"$mode.output.continuation == false\"\n    retry:\n      max_attempts: 2\n      delay_ms: 20000\n\n  # ── Default-on and conditional lenses ─────────────────────────────\n  - id: tests\n    command: review-tests\n    context: fresh\n    depends_on: [scope]\n    when: \"$mode.output.continuation == false\"\n    retry:\n      max_attempts: 2\n      delay_ms: 20000\n\n  - id: errors\n    command: review-errors\n    context: fresh\n    depends_on: [scope]\n    when: \"$mode.output.continuation == false && $INPUTS.errors == 'true'\"\n    retry:\n      max_attempts: 2\n      delay_ms: 20000\n\n  - id: docs\n    command: review-docs\n    context: fresh\n    depends_on: [scope]\n    when: \"$mode.output.continuation == false && $INPUTS.docs == 'true' || $mode.output.continuation == false && $INPUTS.docs == 'auto' && $scope.output.docs == true\"\n    retry:\n      max_attempts: 2\n      delay_ms: 20000\n\n  # all_done lets this barrier settle after input-disabled lenses, every skipped\n  # continuation lens, or a lens whose retries were exhausted. The deciding\n  # agent can then tolerate specialist failures without also tolerating a failed\n  # mode/scope preflight: synthesize separately requires scope to have succeeded.\n  - id: review-complete\n    bash: \"true\"\n    depends_on: [code, seams, simplify, tests, errors, docs]\n    trigger_rule: all_done\n\n  # A failed specialist (a provider stream dying mid-review, say) must not kill\n  # the review: synthesize detects the missing\n  # report for an ENABLED lens and forces ready:false naming the gap, so\n  # degradation is disclosed, never silent, and the correction loop's recheck is\n  # the retry. `ready` is a real boolean — the load-bearing field a composing\n  # loop terminates on. Full reviews receive complete lens files; continuation\n  # reviews receive the complete prior report and correction delta.\n  #\n  # The deciding agent starts fresh and re-reads the diff. On a continuation it\n  # performs the review itself from the previous report and correction delta;\n  # that keeps the accumulated review state without paying for a cold fan-out.\n  # Returning into the scope\n  # node's session is not portable across the bundle's supported providers:\n  # Claude Code, Codex, and Pi. Bundled defaults stay on that shared capability\n  # floor even where the configured provider can resume a named upstream session.\n  #\n  # v1 note: adversarial per-finding verification happens inside this node's\n  # prompt. When in-parent runtime fan-out lands, a verify stage slots in\n  # between the lenses and this node without changing either side's contract —\n  # the findings files are the declared boundary.\n  - id: synthesize\n    command: review-synthesize\n    context: fresh\n    output_type: review-report\n    depends_on: [scope, review-complete]\n    output_format:\n      type: object\n      properties:\n        ready:\n          type: boolean\n        action:\n          type: string\n          enum: [none, correct, replan]\n        findings_summary:\n          type: string\n      required: [ready, action, findings_summary]\n",
  "archon-review-block": "name: archon-review-block\ndescription: |\n  Building block — included by other workflows via `include: archon-review-block`;\n  not intended for standalone runs. Provides the shared 9-node PR review sub-DAG:\n  verify PR base -> scope -> sync -> 5 parallel review agents -> synthesize -> implement fixes.\n\n  Included by archon-idea-to-pr, archon-plan-to-pr, and archon-issue-review-full so the\n  review flow lives in exactly one file. The including workflow supplies the upstream\n  dependency (the node the review should run after); `$review.output` on the parent\n  resolves to this block's terminal node (implement-fixes).\n\nnodes:\n  - id: verify-pr-base\n    bash: |\n      set -euo pipefail\n      # Pin to the origin remote — in a fork clone, gh otherwise queries the upstream parent\n      ORIGIN_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/]+/[^/]+)$#\\1#; s#\\.git$##')\n      HEAD_BRANCH=$(git rev-parse --abbrev-ref HEAD)\n      PR_NUMBER=$(gh pr list --repo \"$ORIGIN_REPO\" --head \"$HEAD_BRANCH\" --state open --json number -q '.[0].number')\n      if [ -z \"$PR_NUMBER\" ]; then\n        echo \"No open PR found for branch $HEAD_BRANCH\" >&2\n        exit 1\n      fi\n      EXPECTED=\"$BASE_BRANCH\"\n      ACTUAL=$(gh pr view \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --json baseRefName -q '.baseRefName')\n      if [ \"$ACTUAL\" != \"$EXPECTED\" ]; then\n        echo \"Base mismatch on PR #$PR_NUMBER: expected=$EXPECTED actual=$ACTUAL — re-targeting\" >&2\n        gh pr edit \"$PR_NUMBER\" --repo \"$ORIGIN_REPO\" --base \"$EXPECTED\"\n      else\n        echo \"PR base verified: $EXPECTED\"\n      fi\n\n  - id: review-scope\n    command: archon-pr-review-scope\n    depends_on: [verify-pr-base]\n    context: fresh\n\n  - id: sync\n    command: archon-sync-pr-with-main\n    depends_on: [review-scope]\n    context: fresh\n\n  - id: code-review\n    command: archon-code-review-agent\n    depends_on: [sync]\n    context: fresh\n\n  - id: error-handling\n    command: archon-error-handling-agent\n    depends_on: [sync]\n    context: fresh\n\n  - id: test-coverage\n    command: archon-test-coverage-agent\n    depends_on: [sync]\n    context: fresh\n\n  - id: comment-quality\n    command: archon-comment-quality-agent\n    depends_on: [sync]\n    context: fresh\n\n  - id: docs-impact\n    command: archon-docs-impact-agent\n    depends_on: [sync]\n    context: fresh\n\n  - id: synthesize\n    command: archon-synthesize-review\n    depends_on: [code-review, error-handling, test-coverage, comment-quality, docs-impact]\n    trigger_rule: one_success\n    context: fresh\n\n  - id: implement-fixes\n    command: archon-implement-review-fixes\n    depends_on: [synthesize]\n    context: fresh\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-ship": "name: archon-ship\ndescription: |\n  Ground an issue or request against the current repository before spending on\n  it, then take the least speculative path: investigate an unknown cause, plan\n  an undecided shape, deliver an implementation-ready work order, or stop when\n  no work remains. Actionable paths converge on the reviewed delivery tail.\n  One governed run, one artifact store, no inherited issue assumptions.\n\n  Use when: a GitHub issue or request should be taken from current-truth check\n  through to a reviewed PR — \"fix this issue\", \"implement issue #123\", \"take\n  this work item to a PR\".\n  NOT for: bypassing triage with already-prepared work (deliver directly),\n  reviewing an existing PR, or merging.\n\nrequires: [github]\n\ninputs:\n  target:\n    default: \"\"\n    description: >-\n      What to take through the pipeline — an issue, document, plan, report, or\n      free-form request. When empty, the run's trigger message is the target.\n  errors:\n    default: \"auto\"\n    description: Silent-failure lens — auto, true, or false.\n\nreturns: outcome\n\nnodes:\n  # The source is history, not a work order. Triage checks it against current\n  # code and direction before deciding which kind of reasoning is still owed.\n  - id: triage\n    include: archon-triage\n    with:\n      target: \"$INPUTS.target\"\n\n  - id: inv\n    include: archon-investigate\n    with:\n      target: >-\n        Investigate the unresolved causal question recorded in\n        $ARTIFACTS_DIR/triage.md. Read that assessment first; its confirmed facts\n        are context, while its unknowns are the investigation target.\n    depends_on: [triage]\n    when: \"$triage.output.route == 'investigate'\"\n\n  # These three route markers form one join into delivery. Expected negative\n  # judgments skip their marker; contract failures inside the advisory package\n  # still fail normally. That keeps \"not ready to build\" distinct from \"the\n  # workflow failed to execute\" without weakening the spend boundary.\n  - id: gate-direct\n    bash: echo '{\"gate\":\"direct\"}'\n    depends_on: [triage]\n    when: \"$triage.output.route == 'deliver'\"\n\n  - id: gate-rooted\n    bash: echo '{\"gate\":\"rooted\"}'\n    depends_on: [inv]\n    when: \"$inv.output.rooted == 'true'\"\n\n  - id: planned\n    include: archon-plan\n    with:\n      work: >-\n        Plan the current work item from $ARTIFACTS_DIR/triage.md. Read that\n        assessment first, preserve its verified outcome and constraints, and\n        decide the implementation questions it identified.\n    depends_on: [triage]\n    when: \"$triage.output.route == 'plan'\"\n\n  - id: gate-planned\n    bash: echo '{\"gate\":\"planned\"}'\n    depends_on: [planned]\n    when: \"$planned.output.ready == 'true'\"\n\n  - id: deliver\n    include: archon-deliver\n    with:\n      errors: \"$INPUTS.errors\"\n      work: >-\n        Deliver the work prepared by this run. Read $ARTIFACTS_DIR/triage.md\n        first. When present, plan.md or investigation.md is the detailed work\n        order and must be read in full; triage.md records which path produced it\n        and which source assumptions were corrected. On the direct route,\n        triage.md itself is the verified work order.\n    depends_on: [gate-direct, gate-rooted, gate-planned]\n    trigger_rule: none_failed_min_one_success\n\n  # One return for every legitimate terminal result. Negative advisory verdicts\n  # complete with the report that explains them; delivery is reported from the\n  # flip's verified URL the deliver branch returned (bound with if_skipped, so a\n  # skipped flip arrives as null) — see scripts/outcome.py.\n  - id: outcome\n    script: outcome\n    runtime: uv\n    depends_on: [triage, inv, planned, gate-direct, gate-rooted, gate-planned, deliver]\n    trigger_rule: none_failed_min_one_success\n    with:\n      route: \"$triage.output.route\"\n      summary: \"$triage.output.summary\"\n      delivered: { from: \"$deliver.output\", if_skipped: null }\n      # A passed spend gate with no delivered output means delivery STARTED and\n      # died mid-flight — a different fact from an advisory stop, and the report\n      # must not claim the advisory refused.\n      gate_passed_direct: { from: \"$gate-direct.output\", if_skipped: null }\n      gate_passed_rooted: { from: \"$gate-rooted.output\", if_skipped: null }\n      gate_passed_planned: { from: \"$gate-planned.output\", if_skipped: null }\n",
  "archon-smart-pr-review": "name: archon-smart-pr-review\ndescription: |\n  Use when: User wants a smart, efficient PR review that adapts to PR complexity.\n  Triggers: \"smart review\", \"review this PR\", \"review PR #123\", \"efficient review\",\n            \"smart PR review\", \"quick review\".\n  Does: Gathers PR scope -> classifies complexity -> routes to only relevant review agents ->\n        synthesizes findings -> auto-fixes CRITICAL/HIGH issues.\n  NOT for: When you explicitly want ALL review agents (use archon-comprehensive-pr-review instead).\n\n  Unlike the comprehensive review, this workflow classifies the PR first and only runs\n  the review agents that are relevant. A 3-line typo fix skips test-coverage and docs-impact.\n\nnodes:\n  - id: scope\n    command: archon-pr-review-scope\n\n  - id: sync\n    command: archon-sync-pr-with-main\n    depends_on: [scope]\n\n  - id: classify\n    prompt: |\n      You are a PR complexity classifier. Analyze the PR scope below and determine\n      which review agents should run.\n\n      ## PR Scope\n      $scope.output\n\n      ## Rules\n      - **Code review**: Always run unless the diff is empty or only touches non-code files\n        (e.g. README-only, config-only, or .yaml-only changes).\n      - **Error handling**: Run if the diff touches code with try/catch, error handling,\n        async/await, or adds new failure paths.\n      - **Test coverage**: Run if the diff touches source code (not just tests, docs, or config).\n      - **Comment quality**: Run if the diff adds or modifies comments, docstrings, JSDoc,\n        or significant documentation within code files.\n      - **Docs impact**: Run if the diff adds/removes/renames public APIs, commands, CLI flags,\n        environment variables, or user-facing features.\n\n      Classify the PR complexity:\n      - **trivial**: Typo fixes, formatting, single-line changes, version bumps\n      - **small**: 1-3 files, straightforward logic, no architectural changes\n      - **medium**: 4-10 files, moderate logic changes, some cross-cutting concerns\n      - **large**: 10+ files, architectural changes, new subsystems, complex refactors\n\n      Provide your reasoning for each decision.\n    depends_on: [scope]\n    model: small\n    allowed_tools: []\n    output_format:\n      type: object\n      properties:\n        run_code_review:\n          type: string\n          enum: [\"true\", \"false\"]\n        run_error_handling:\n          type: string\n          enum: [\"true\", \"false\"]\n        run_test_coverage:\n          type: string\n          enum: [\"true\", \"false\"]\n        run_comment_quality:\n          type: string\n          enum: [\"true\", \"false\"]\n        run_docs_impact:\n          type: string\n          enum: [\"true\", \"false\"]\n        complexity:\n          type: string\n          enum: [\"trivial\", \"small\", \"medium\", \"large\"]\n        reasoning:\n          type: string\n      required:\n        - run_code_review\n        - run_error_handling\n        - run_test_coverage\n        - run_comment_quality\n        - run_docs_impact\n        - complexity\n        - reasoning\n\n  - id: code-review\n    command: archon-code-review-agent\n    depends_on: [classify, sync]\n    when: \"$classify.output.run_code_review == 'true'\"\n\n  - id: error-handling\n    command: archon-error-handling-agent\n    depends_on: [classify, sync]\n    when: \"$classify.output.run_error_handling == 'true'\"\n\n  - id: test-coverage\n    command: archon-test-coverage-agent\n    depends_on: [classify, sync]\n    when: \"$classify.output.run_test_coverage == 'true'\"\n\n  - id: comment-quality\n    command: archon-comment-quality-agent\n    depends_on: [classify, sync]\n    when: \"$classify.output.run_comment_quality == 'true'\"\n\n  - id: docs-impact\n    command: archon-docs-impact-agent\n    depends_on: [classify, sync]\n    when: \"$classify.output.run_docs_impact == 'true'\"\n\n  - id: synthesize\n    command: archon-synthesize-review\n    depends_on: [code-review, error-handling, test-coverage, comment-quality, docs-impact]\n    trigger_rule: one_success\n\n  - id: implement-fixes\n    command: archon-implement-review-fixes\n    depends_on: [synthesize]\n\n  # Optional: push notification when review completes.\n  # To enable, create .archon/mcp/ntfy.json — see docs/mcp-servers.md\n  - id: check-ntfy\n    bash: \"test -f .archon/mcp/ntfy.json && echo 'true' || echo 'false'\"\n    depends_on: [implement-fixes]\n\n  - id: notify\n    depends_on: [check-ntfy, synthesize, implement-fixes]\n    when: \"$check-ntfy.output == 'true'\"\n    trigger_rule: all_success\n    mcp: .archon/mcp/ntfy.json\n    allowed_tools: []\n    prompt: |\n      Send a push notification summarizing the PR review results.\n\n      Review synthesis:\n      $synthesize.output\n\n      Fix results:\n      $implement-fixes.output\n\n      Send with:\n      - title: \"PR Review Complete\"\n      - message: 1-2 sentence summary — verdict and issue count. Short enough for a lock screen.\n      - priority: 3 if ready to merge, 4 if needs fixes, 5 if critical issues remain\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-test-loop-dag": "name: archon-test-loop-dag\ndescription: |\n  Use when: User explicitly says \"test-loop-dag\" or \"run test-loop-dag\".\n  IMPORTANT: This is a DAG workflow with a loop node that iterates until completion.\n  NOT for: General testing questions or debugging.\n  Does: Initializes a counter, iterates until it reaches 3, then reports completion.\n\nnodes:\n  - id: setup\n    bash: |\n      echo \"0\" > .archon/test-loop-dag-counter.txt\n      echo \"Counter initialized to 0\"\n\n  - id: loop-counter\n    depends_on: [setup]\n    loop:\n      prompt: |\n        You are testing the loop node functionality within a DAG workflow.\n\n        ## Your Task\n\n        1. Read the file `.archon/test-loop-dag-counter.txt`\n        2. Parse the current counter value\n        3. Increment it by 1\n        4. Write the new value back to the file\n        5. Report the current iteration\n\n        ## User Intent\n\n        $USER_MESSAGE\n\n        ## Completion Criteria\n\n        - If the counter reaches 3 or higher, output: <promise>COMPLETE</promise>\n        - Otherwise, just report your progress and end normally\n\n        ## Important\n\n        Be concise. Just do the task and report the counter value.\n      until: COMPLETE\n      max_iterations: 5\n      fresh_context: false\n\n  - id: report\n    depends_on: [loop-counter]\n    prompt: |\n      The loop counter test has completed. The loop node output was:\n\n      $loop-counter.output\n\n      Read `.archon/test-loop-dag-counter.txt` and confirm the final counter value.\n      Report: \"Test loop DAG completed successfully. Final counter: {value}\"\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-triage": "name: archon-triage\ndescription: |\n  Ground one work item against the current repository before deciding what kind\n  of work it needs. Reconciles tracker history, current code, moved branches,\n  stale assumptions, and explicit direction; then routes to investigate, plan,\n  deliver, or no action. Advisory: it leaves the checkout unchanged.\n\n  Use when: an issue, plan, report, or request may be stale or may prescribe an\n  unverified solution — \"triage this issue\", \"what does this need next\", \"is\n  this ready to build\".\n  NOT for: performing the investigation, writing the plan, or delivering work.\n\nmodel: medium\n\ninputs:\n  target:\n    default: \"\"\n    description: >-\n      What to triage — an issue, document, plan, report, or free-form request.\n      When empty, the run's trigger message is the target.\n\nreturns: triage\n\nnodes:\n  - id: triage\n    command: triage\n    # Triage is advisory: the engine fails this node with the touched paths\n    # named if it modifies the working tree. Replaced the\n    # record-state/assert-intact snapshot pair the pack carried before the\n    # engine could enforce this itself.\n    mutates_checkout: false\n    output_type: work-triage\n    output_format:\n      type: object\n      properties:\n        route:\n          type: string\n          enum: [investigate, plan, deliver, no_action]\n        summary:\n          type: string\n      required: [route, summary]\n\n  - id: assert-intact\n    bash: |\n      # Tree-intactness is engine-enforced via mutates_checkout: false above;\n      # what remains here is the evidence contract: a route without a written\n      # triage.md is not a triage.\n      if [ ! -s \"$ARTIFACTS_DIR/triage.md\" ]; then\n        echo \"assert-intact: the run completed but wrote no triage.md — a route without evidence is not a triage.\" >&2\n        exit 1\n      fi\n      echo '{\"intact\":\"true\"}'\n    depends_on: [triage]\n",
  "archon-upkeep": "name: archon-upkeep\ndescription: |\n  Keep one dependency current: ground the update request against the repository\n  as it exists (locked version, blast radius, breaking changes that touch real\n  usage), then either stop with the reason or take the bump through the full\n  reviewed delivery tail. One governed run; the assessment is the work order.\n\n  Use when: a dependency or security advisory should become a reviewed,\n  ready-to-merge PR — \"update sharp\", \"address the undici advisory\",\n  \"bump X to latest\".\n  NOT for: sweeping every outdated dependency at once (one target per run),\n  or deciding fork-vs-replace questions (that is a human decision the\n  assessment will surface, not make).\n\nrequires: [github]\n\ninputs:\n  target:\n    default: \"\"\n    description: >-\n      The update to assess — a dependency name, version, or advisory. When\n      empty, the run's trigger message is the target.\n  errors:\n    default: \"auto\"\n    description: Silent-failure lens — auto, true, or false.\n\nreturns: outcome\n\nnodes:\n  # The assessment stage is advisory and inline (not a composed package): the\n  # record/judge/verify triad appears here for the second time after triage —\n  # rule of three says extract on the third package that needs it, not now.\n  - id: assess\n    command: assess\n    # Advisory: the engine fails this node with the touched paths named if it\n    # modifies the working tree; replaced the record-state snapshot.\n    mutates_checkout: false\n    model: medium\n    output_type: dependency-assessment\n    output_format:\n      type: object\n      properties:\n        action:\n          type: string\n          enum: [update, no_action]\n        summary:\n          type: string\n      required: [action, summary]\n\n  - id: assert-intact\n    bash: |\n      # Tree-intactness is engine-enforced via mutates_checkout: false above;\n      # what remains is the evidence contract.\n      if [ ! -s \"$ARTIFACTS_DIR/upkeep-assessment.md\" ]; then\n        echo \"assert-intact: the run completed but wrote no upkeep-assessment.md — a verdict without evidence is not an assessment.\" >&2\n        exit 1\n      fi\n      echo '{\"intact\":\"true\"}'\n    depends_on: [assess]\n\n  # Spend gate: a no_action assessment skips everything paid or public below.\n  # An expected negative is a completed run with the assessment as its result.\n  - id: gate-update\n    bash: echo '{\"gate\":\"update\"}'\n    depends_on: [assert-intact]\n    when: \"$assess.output.action == 'update'\"\n\n  # The work order authorizes exactly the lockfile change implement's default\n  # forbids: implement.md's \"never update a lockfile\" exists to stop incidental\n  # churn, and the target dependency IS the work here — so the order re-scopes\n  # that rule explicitly (non-goals are transferable by the work item) while\n  # keeping it in force for every other dependency.\n  - id: deliver\n    include: archon-deliver\n    with:\n      errors: \"$INPUTS.errors\"\n      work: >-\n        Apply the dependency update specified in\n        $ARTIFACTS_DIR/upkeep-assessment.md. Read that file in full first — it\n        is the verified work order, and you know nothing about this update\n        beyond it and the repository itself. Follow its update order: use the\n        project's own package manager, change the manifest only as the\n        assessment directs, and update the lockfile for the TARGET dependency\n        only — this work item explicitly authorizes that lockfile change; the\n        no-lockfile-updates default still applies to every other dependency, so\n        keep churn minimal and never downgrade anything unrelated. Fix what the\n        bump breaks, validate with the project's own checks, and if reality\n        contradicts the assessment (version unavailable, an unlisted peer\n        conflict), stop honestly with green false and the contradiction in your\n        summary rather than improvising a different version. Carry the\n        assessment's chosen mechanism, its blast radius, and the alternative it\n        rejected into your report — the reviewer must be able to judge that\n        trade-off from the pull request. Original request:\n        $INPUTS.target\n    depends_on: [gate-update]\n\n  # One return for every legitimate terminal result: a no_action assessment\n  # completes with its report path; a delivered update is reported from the\n  # flip's verified URL the deliver branch returned (if_skipped binding, so a\n  # skipped flip arrives as null). A passed gate with no delivered output means delivery\n  # died mid-flight — outcome must never attribute that to the assessment.\n  - id: outcome\n    script: outcome\n    runtime: uv\n    depends_on: [assess, assert-intact, gate-update, deliver]\n    trigger_rule: none_failed_min_one_success\n    with:\n      action: \"$assess.output.action\"\n      summary: \"$assess.output.summary\"\n      delivered: { from: \"$deliver.output\", if_skipped: null }\n      gate_passed: { from: \"$gate-update.output\", if_skipped: null }\n",
  "archon-validate": "name: archon-validate\ndescription: |\n  Discover and run the project's own checks — types, lint, tests, build,\n  whatever the repository itself defines — and report a structured verdict.\n  Judges nothing and fixes nothing: it runs what the project declares and\n  tells the truth about the result.\n\n  Use when: the current state of the checkout needs a validation verdict —\n  \"run the checks\", \"is this green\", \"validate this\".\n  NOT for: fixing failures (implement) or reviewing code (review).\n\nmodel: medium\n\ninputs:\n  scope:\n    default: \"\"\n    description: >-\n      Optional narrowing — a package, directory, or named check to focus on.\n      Empty means the project's full applicable gate.\n\nreturns: validate\noutcome_field: green\n\nnodes:\n  - id: validate\n    command: validate\n    always_run: true\n    output_type: validation\n    output_format:\n      type: object\n      properties:\n        green:\n          type: boolean\n        # Why the checks are red, when they are. Carries the empty string\n        # when there is no red to explain, for the same reason implement's does:\n        # OpenAI strict mode rejects a schema whose `required` omits a declared\n        # property, so the absent form lives in the enum.\n        red_cause:\n          type: string\n          enum: [introduced, inherited, environment, \"\"]\n        summary:\n          type: string\n      required: [green, red_cause, summary]\n",
  "archon-validate-pr": "name: archon-validate-pr\ndescription: |\n  Use when: User wants a thorough PR validation that tests both main (bug present) and feature branch (bug fixed).\n  Triggers: \"validate PR\", \"validate pr #123\", \"test this PR\", \"verify PR\", \"full PR validation\",\n            \"validate pull request\", \"test PR end-to-end\".\n  Does: Fetches PR info -> finds free ports -> parallel code review (main vs feature) ->\n        E2E test on main (reproduce bug) -> E2E test on feature (verify fix) -> final verdict report.\n  NOT for: Quick code-only reviews (use archon-smart-pr-review), fixing issues, general exploration.\n\n  This workflow is designed for running in parallel — each instance finds its own free ports\n  to avoid conflicts. Produces artifacts in $ARTIFACTS_DIR/ and posts a validation report.\n\nprovider: claude\nmodel: large\n\nnodes:\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 1: SETUP — Fetch PR info and allocate ports\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: fetch-pr\n    bash: |\n      # Extract PR number from arguments\n      PR_NUMBER=$(echo \"$ARGUMENTS\" | grep -oE '/pull/[0-9]+' | grep -oE '[0-9]+' | head -1)\n      # Fallback: extract first number if no URL path found (e.g., \"validate PR 42\")\n      if [ -z \"$PR_NUMBER\" ]; then\n        PR_NUMBER=$(echo \"$ARGUMENTS\" | grep -oE '[0-9]+' | head -1)\n      fi\n      if [ -z \"$PR_NUMBER\" ]; then\n        # Try getting PR from current branch\n        PR_NUMBER=$(gh pr view --json number -q '.number' 2>/dev/null)\n      fi\n\n      if [ -z \"$PR_NUMBER\" ]; then\n        echo \"ERROR: No PR number found in arguments: $ARGUMENTS\"\n        exit 1\n      fi\n\n      echo \"$PR_NUMBER\" > \"$ARTIFACTS_DIR/.pr-number\"\n\n      # Fetch full PR details\n      gh pr view \"$PR_NUMBER\" --json number,title,body,url,headRefName,baseRefName,files,additions,deletions,changedFiles,state,author,labels,isDraft\n\n  - id: find-ports\n    bash: |\n      # Use Bun to let the OS pick truly free ports (cross-platform: Linux, macOS, Windows)\n      BACKEND_PORT=$(bun -e \"const s = Bun.serve({port: 0, fetch: () => new Response('')}); console.log(s.port); s.stop()\")\n      FRONTEND_PORT=$(bun -e \"const s = Bun.serve({port: 0, fetch: () => new Response('')}); console.log(s.port); s.stop()\")\n\n      echo \"$BACKEND_PORT\" > \"$ARTIFACTS_DIR/.backend-port\"\n      echo \"$FRONTEND_PORT\" > \"$ARTIFACTS_DIR/.frontend-port\"\n\n      echo \"BACKEND_PORT=$BACKEND_PORT\"\n      echo \"FRONTEND_PORT=$FRONTEND_PORT\"\n\n  - id: resolve-paths\n    bash: |\n      # Resolve canonical repo path (main branch) vs worktree path (feature branch)\n      CANONICAL_REPO=$(git rev-parse --path-format=absolute --git-common-dir 2>/dev/null | sed 's|/\\.git$||')\n      WORKTREE_PATH=$(pwd)\n      FEATURE_BRANCH=$(git branch --show-current)\n\n      # Get PR branch info\n      PR_NUMBER=$(cat \"$ARTIFACTS_DIR/.pr-number\")\n      PR_HEAD=$(gh pr view \"$PR_NUMBER\" --json headRefName -q '.headRefName')\n      PR_BASE=$(gh pr view \"$PR_NUMBER\" --json baseRefName -q '.baseRefName')\n\n      echo \"$CANONICAL_REPO\" > \"$ARTIFACTS_DIR/.canonical-repo\"\n      echo \"$WORKTREE_PATH\" > \"$ARTIFACTS_DIR/.worktree-path\"\n      echo \"$FEATURE_BRANCH\" > \"$ARTIFACTS_DIR/.feature-branch\"\n      echo \"$PR_HEAD\" > \"$ARTIFACTS_DIR/.pr-head\"\n      echo \"$PR_BASE\" > \"$ARTIFACTS_DIR/.pr-base\"\n\n      echo \"CANONICAL_REPO=$CANONICAL_REPO\"\n      echo \"WORKTREE_PATH=$WORKTREE_PATH\"\n      echo \"FEATURE_BRANCH=$FEATURE_BRANCH\"\n      echo \"PR_HEAD=$PR_HEAD\"\n      echo \"PR_BASE=$PR_BASE\"\n    depends_on: [fetch-pr]\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 2: CODE REVIEW — Parallel analysis of main vs feature\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: code-review-main\n    command: archon-validate-pr-code-review-main\n    depends_on: [fetch-pr, resolve-paths]\n    context: fresh\n\n  - id: code-review-feature\n    command: archon-validate-pr-code-review-feature\n    depends_on: [fetch-pr, resolve-paths, code-review-main]\n    context: fresh\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 3: E2E TESTING — Sequential (after code reviews finish)\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: classify-testability\n    prompt: |\n      You are a PR testability classifier. Determine whether this PR's changes can be\n      validated via browser E2E testing, or if it requires code-review-only validation.\n\n      ## PR Details\n\n      $fetch-pr.output\n\n      ## Rules\n\n      - **e2e_testable**: Changes affect the Web UI (components, hooks, styles, API routes\n        that serve the frontend, SSE streaming, layout, user-visible behavior). These can be\n        validated by starting Archon and using agent-browser to interact with the UI.\n      - **code_review_only**: Changes are purely backend logic, CLI-only, workflow engine,\n        database schemas, git operations, build tooling, tests, documentation, or other\n        non-UI code. No visual validation possible.\n\n      Consider: even if a change is backend, if it affects what the frontend displays\n      (e.g., API response format changes, SSE event changes), it IS e2e_testable.\n    depends_on: [fetch-pr]\n    model: small\n    allowed_tools: []\n    output_format:\n      type: object\n      properties:\n        testable:\n          type: string\n          enum: [\"e2e_testable\", \"code_review_only\"]\n        reasoning:\n          type: string\n        test_plan:\n          type: string\n      required: [testable, reasoning, test_plan]\n\n  - id: e2e-test-main\n    command: archon-validate-pr-e2e-main\n    depends_on: [classify-testability, find-ports, resolve-paths, code-review-main, code-review-feature]\n    when: \"$classify-testability.output.testable == 'e2e_testable'\"\n    context: fresh\n    idle_timeout: 1800000\n\n  - id: e2e-test-feature\n    command: archon-validate-pr-e2e-feature\n    depends_on: [e2e-test-main, find-ports, resolve-paths]\n    when: \"$classify-testability.output.testable == 'e2e_testable'\"\n    context: fresh\n    idle_timeout: 1800000\n\n  # ═══════════════════════════════════════════════════════════════\n  # PHASE 4: FINAL REPORT — Synthesize all findings\n  # ═══════════════════════════════════════════════════════════════\n\n  - id: cleanup-processes\n    bash: |\n      # Safety net: kill any orphaned processes from E2E testing\n      # This runs after E2E nodes complete (or timeout/fail) to prevent process accumulation\n      BACKEND_PORT=$(cat \"$ARTIFACTS_DIR/.backend-port\" 2>/dev/null | tr -d '\\n')\n      FRONTEND_PORT=$(cat \"$ARTIFACTS_DIR/.frontend-port\" 2>/dev/null | tr -d '\\n')\n\n      if [ -z \"$BACKEND_PORT\" ] || [ -z \"$FRONTEND_PORT\" ]; then\n        echo \"No port files found — skipping cleanup\"\n        exit 0\n      fi\n\n      echo \"Cleaning up ports $BACKEND_PORT and $FRONTEND_PORT...\"\n\n      # Kill by all recorded PID files\n      for pidfile in \"$ARTIFACTS_DIR\"/.e2e-*-pid; do\n        if [ -f \"$pidfile\" ]; then\n          PID=$(cat \"$pidfile\" | tr -d '\\n')\n          echo \"Killing PID $PID from $pidfile\"\n          kill \"$PID\" 2>/dev/null || taskkill //F //T //PID \"$PID\" 2>/dev/null || true\n        fi\n      done\n\n      # Kill by port (cross-platform fallback)\n      for PORT in $BACKEND_PORT $FRONTEND_PORT; do\n        fuser -k \"$PORT/tcp\" 2>/dev/null || true\n        lsof -ti:\"$PORT\" 2>/dev/null | xargs kill -9 2>/dev/null || true\n        netstat -ano 2>/dev/null | grep \":$PORT \" | grep LISTENING | awk '{print $5}' | sort -u | while read pid; do\n          taskkill //F //T //PID \"$pid\" 2>/dev/null || true\n        done\n      done\n\n      # pkill fallback: catch processes that escaped PID/port cleanup\n      pkill -f \"PORT=$BACKEND_PORT.*bun\" 2>/dev/null || true\n      pkill -f \"vite.*port.*$FRONTEND_PORT\" 2>/dev/null || true\n\n      # Close this workflow's browser session only (scoped by session ID)\n      BROWSER_SESSION=$(cat \"$ARTIFACTS_DIR/.browser-session\" 2>/dev/null | tr -d '\\n')\n      if [ -n \"$BROWSER_SESSION\" ]; then\n        agent-browser --session \"$BROWSER_SESSION\" close 2>/dev/null || true\n      fi\n\n      # Remove main E2E worktree if it still exists (safety net)\n      CANONICAL_REPO=$(cat \"$ARTIFACTS_DIR/.canonical-repo\" 2>/dev/null | tr -d '\\n')\n      MAIN_E2E_PATH=$(cat \"$ARTIFACTS_DIR/.e2e-main-worktree\" 2>/dev/null | tr -d '\\n')\n      if [ -n \"$MAIN_E2E_PATH\" ] && [ -n \"$CANONICAL_REPO\" ] && [ -d \"$MAIN_E2E_PATH\" ]; then\n        echo \"Removing leftover main E2E worktree: $MAIN_E2E_PATH\"\n        git -C \"$CANONICAL_REPO\" worktree remove \"$MAIN_E2E_PATH\" --force 2>/dev/null || rm -rf \"$MAIN_E2E_PATH\"\n      fi\n\n      sleep 1\n      echo \"Process cleanup complete\"\n    depends_on: [e2e-test-main, e2e-test-feature]\n    trigger_rule: all_done\n\n  - id: final-report\n    command: archon-validate-pr-report\n    depends_on: [code-review-main, code-review-feature, e2e-test-main, e2e-test-feature, classify-testability, cleanup-processes]\n    trigger_rule: all_done\n    context: fresh\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
  "archon-workflow-builder": "name: archon-workflow-builder\ndescription: |\n  Use when: User wants to create a new custom workflow for their project.\n  Triggers: \"build me a workflow\", \"create a workflow\", \"generate a workflow\",\n            \"new workflow\", \"make a workflow for\", \"workflow builder\".\n  Does: Scans codebase -> extracts intent (JSON) -> generates YAML -> validates -> saves.\n  NOT for: Editing existing workflows or creating non-workflow files.\n\n# Run in the live checkout, not in a fresh sub-worktree. Without this, every\n# archon-workflow-builder invocation creates an isolated sub-worktree and\n# writes the generated YAML there — the file never reaches the caller's\n# .archon/workflows/, so the run reports success while the user's repo gains\n# nothing. Closes #1220.\nworktree:\n  enabled: false\n\nnodes:\n  - id: scan-codebase\n    bash: |\n      echo \"=== Existing Commands ===\"\n      if [ -d \".archon/commands\" ]; then\n        find .archon/commands -type f -name \"*.md\" 2>/dev/null | head -30\n      else\n        echo \"(no .archon/commands/ directory)\"\n      fi\n\n      echo \"\"\n      echo \"=== Existing Workflows ===\"\n      if [ -d \".archon/workflows\" ]; then\n        find .archon/workflows -type f \\( -name \"*.yaml\" -o -name \"*.yml\" \\) 2>/dev/null | head -30\n      else\n        echo \"(no .archon/workflows/ directory)\"\n      fi\n\n      echo \"\"\n      echo \"=== Package Info ===\"\n      if [ -f \"package.json\" ]; then\n        grep -E '\"name\"|\"scripts\"' package.json | head -10\n      else\n        echo \"(no package.json)\"\n      fi\n\n      echo \"\"\n      echo \"=== Project Context (CLAUDE.md first 50 lines) ===\"\n      if [ -f \"CLAUDE.md\" ]; then\n        head -50 CLAUDE.md\n      else\n        echo \"(no CLAUDE.md)\"\n      fi\n\n  - id: extract-intent\n    prompt: |\n      You are a workflow design classifier. Given a user's description of what they want\n      a workflow to do, extract structured intent.\n\n      ## User's Request\n      $ARGUMENTS\n\n      ## Codebase Context\n      $scan-codebase.output\n\n      ## Instructions\n\n      Analyze the user's request and the existing codebase to determine:\n      1. A kebab-case workflow name (e.g., \"lint-and-test\", \"deploy-staging\")\n      2. A description following the Archon pattern (Use when / Triggers / Does / NOT for)\n      3. Trigger phrases the router should match\n      4. A list of proposed nodes with their types and purposes\n      5. Whether this should be a simple DAG or include a loop node\n\n      Be specific and concrete. Each proposed node should have a clear type\n      (bash, prompt, command, script, loop, loop_group, approval, or cancel) and\n      a one-line description of what it does.\n    model: small\n    allowed_tools: []\n    output_format:\n      type: object\n      properties:\n        workflow_name:\n          type: string\n        description:\n          type: string\n        trigger_phrases:\n          type: string\n        proposed_nodes:\n          type: string\n        execution_mode:\n          type: string\n          enum: [\"dag\", \"loop\"]\n      required: [workflow_name, description, trigger_phrases, proposed_nodes, execution_mode]\n    depends_on: [scan-codebase]\n\n  - id: generate-yaml\n    prompt: |\n      You are an Archon workflow author. Generate a complete, valid workflow YAML file\n      based on the structured intent provided.\n\n      ## Intent\n      - **Name**: $extract-intent.output.workflow_name\n      - **Description**: $extract-intent.output.description\n      - **Trigger Phrases**: $extract-intent.output.trigger_phrases\n      - **Proposed Nodes**: $extract-intent.output.proposed_nodes\n      - **Execution Mode**: $extract-intent.output.execution_mode\n\n      ## Original User Request\n      $ARGUMENTS\n\n      ## Archon Workflow YAML Schema Reference\n\n      A workflow YAML file has this structure:\n\n      ```yaml\n      name: workflow-name\n      description: |\n        Use when: ...\n        Triggers: ...\n        Does: ...\n        NOT for: ...\n\n      # Optional top-level settings:\n      # provider: claude    (or codex)\n      # model: medium       (or haiku, opus, etc.)\n      # interactive: true   (forces foreground execution in web UI)\n\n      nodes:\n        - id: node-id-kebab-case\n          # Choose ONE of: prompt, bash, command, script, loop, loop_group, approval, cancel\n\n          # --- prompt node (AI-executed) ---\n          prompt: |\n            Instructions for the AI...\n          # Optional: model, allowed_tools, denied_tools, output_format, context, idle_timeout\n\n          # --- bash node (shell script, no AI, stdout = $<nodeId>.output) ---\n          bash: |\n            #!/bin/bash\n            set -e\n            echo \"result\"\n\n          # --- command node (references a .archon/commands/ file) ---\n          command: command-name\n\n          # --- script node (TypeScript via bun, or Python via uv — no AI, stdout = $<nodeId>.output) ---\n          # Use for deterministic data transforms the shell would mangle (JSON parsing, etc.)\n          script: |\n            // JSON is valid JS expression syntax — assign directly (String.raw breaks on backticks)\n            const data = $<other-node>.output;\n            console.log(JSON.stringify({ count: data.items.length }));\n          runtime: bun                       # required: 'bun' (.ts/.js) or 'uv' (.py)\n          # deps: [requests]                 # uv only\n          # Or reference a named script in .archon/scripts/:\n          # script: extract-labels           # no extension; bun resolves .ts/.js, uv resolves .py\n\n          # --- loop node (iterative AI execution) ---\n          loop:\n            prompt: |\n              Instructions repeated each iteration...\n            until: COMPLETION_SIGNAL\n            max_iterations: 10\n            fresh_context: true  # optional: reset context each iteration\n\n          # --- loop_group node (iterate a multi-node sub-DAG until done) ---\n          loop_group:\n            until: COMPLETION_SIGNAL\n            max_iterations: 5\n            nodes:                             # sealed sub-DAG body, re-run each iteration\n              - id: body-step\n                prompt: |\n                  Do one unit of work. Emit COMPLETION_SIGNAL when finished.\n                depends_on: []\n\n          # --- approval node (human gate — pauses workflow) ---\n          approval:\n            message: \"Review the plan above. Approve to continue.\"\n            # capture_response: true         # store reviewer comment as $<nodeId>.output\n\n          # --- cancel node (terminate the run with a reason; no AI) ---\n          cancel: \"Reason the workflow was terminated\"\n\n          # Common options for all node types:\n          depends_on: [other-node-id]       # DAG edges\n          when: \"$<other-node>.output == 'value'\"  # conditional execution\n          trigger_rule: all_success          # all_success | one_success | all_done\n          timeout: 120000                    # ms, for bash and script nodes\n      ```\n\n      ## Variable Reference\n      - `$ARGUMENTS` — user's input text\n      - `$ARTIFACTS_DIR` — pre-created directory for workflow artifacts\n      - `$<nodeId>.output` — stdout from a bash/script node or AI response from a prompt node\n      - `$<nodeId>.output.field` — JSON field from a node with output_format\n      - `$BASE_BRANCH` — base git branch\n\n      ## Rules\n      1. The `name:` field MUST match: $extract-intent.output.workflow_name\n      2. The `description:` MUST follow the \"Use when / Triggers / Does / NOT for\" pattern\n      3. Every node MUST have a unique kebab-case `id`\n      4. Use `depends_on` to define execution order\n      5. Use `bash` nodes for deterministic shell operations (file checks, git commands, installs)\n      6. Use `script` nodes for typed data transforms (TypeScript JSON parsing, Python with deps)\n         — stdout is captured as output, stderr is forwarded as a warning.\n         `$<node-id>.output` is NOT shell-quoted in script bodies.\n         - **TypeScript/bun**: assign directly — `const data = $<node-id>.output;`\n           (JSON is valid JS expression syntax; avoid String.raw — it breaks on backticks)\n         - **Python/uv**: use json.loads — `import json; data = json.loads(\"\"\"$<node-id>.output\"\"\")`\n         Never interpolate into shell syntax.\n      7. Use `prompt` nodes for AI reasoning tasks\n      8. Use `approval` nodes to pause for human review at risky gates (plan→execute boundary, destructive actions)\n      9. Use `output_format` on prompt nodes when downstream nodes need structured data\n      10. Use `allowed_tools: []` on classification/analysis nodes that don't need tools\n      11. Use `denied_tools: [Edit, Bash]` when a node should only use Write (not edit existing files)\n      12. Prefer `model: small` for simple classification tasks to save cost\n\n      ## Output\n\n      Write the complete workflow YAML to: `$ARTIFACTS_DIR/generated-workflow.yaml`\n\n      Use the Write tool. Do NOT use Edit or Bash. The file must be valid YAML and follow\n      all the patterns above.\n    denied_tools: [Edit, Bash]\n    depends_on: [extract-intent]\n\n  - id: validate-yaml\n    bash: |\n      FILE=\"$ARTIFACTS_DIR/generated-workflow.yaml\"\n\n      if [ ! -f \"$FILE\" ]; then\n        echo \"ERROR: generated-workflow.yaml not found at $FILE\"\n        exit 1\n      fi\n\n      if [ ! -s \"$FILE\" ]; then\n        echo \"ERROR: generated-workflow.yaml is empty\"\n        exit 1\n      fi\n\n      if ! grep -q \"^name:\" \"$FILE\"; then\n        echo \"ERROR: missing 'name:' field\"\n        exit 1\n      fi\n\n      if ! grep -q \"^nodes:\" \"$FILE\"; then\n        echo \"ERROR: missing 'nodes:' field\"\n        exit 1\n      fi\n\n      echo \"VALID\"\n    depends_on: [generate-yaml]\n\n  - id: save-or-report\n    prompt: |\n      You are a workflow installer. Save the generated workflow and report to the user.\n\n      ## Workflow Details\n      - **Name**: $extract-intent.output.workflow_name\n      - **Trigger Phrases**: $extract-intent.output.trigger_phrases\n\n      ## Instructions\n\n      1. Read the generated workflow from `$ARTIFACTS_DIR/generated-workflow.yaml`\n      2. Create the directory `.archon/workflows/` if it doesn't exist (use Bash: `mkdir -p .archon/workflows/`)\n      3. Save the workflow to `.archon/workflows/$extract-intent.output.workflow_name.yaml`\n         Use the Write tool to write the file.\n      4. Report to the user:\n         - Workflow name and file location\n         - Trigger phrases that will invoke it\n         - How to run it: `bun run cli workflow run $extract-intent.output.workflow_name \"your input\"`\n         - How to test it: `bun run cli validate workflows $extract-intent.output.workflow_name`\n    depends_on: [validate-yaml]\n\n# Deprecated legacy default (#2781): announce removal in the run-start notice during this window.\ndeprecated:\n  message: Switch to the sdlc pack instead.\n",
};

